const e="65 chapters",t=[{id:"chapter-35",number:35,title:"V/A-(으)ㄴ/는데 · V/A-잖아요",goal:"Open a sensitive topic with 사실은 and sentence-final -는데요.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 사실은~",cards:[{kind:"guess",word:{ko:"사실은",romanization:"sasireun",en:"actually; to be honest",pos:"adverb",nuance:"사실은 does not mean every sentence is a dramatic confession. It often simply prepares the listener for background or a correction."},sentence:{ko:"사실은 오늘 자료가 아직 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},target:"사실은",options:["so; what you mean is","actually; to be honest","softly; gently; smoothly"],note:"Opens a sensitive update softly."},{kind:"guess",word:{ko:"그런데",romanization:"geureonde",en:"but; by the way",pos:"adverb",nuance:"그런데 (spoken: 근데) is the soft, all-purpose 'but' that also works as 'by the way' to glide into a new topic — this double life surprises English speakers most. As contrast it is far gentler than 하지만 or 그렇지만; it doesn't slam two ideas together, it just notes that something slightly different follows. As a topic-changer it carries no contrast at all: 그런데, 우리 언제 만나요? simply means 'So/Anyway, when shall we meet?'. It is closely tied to the mid-sentence ending -는데, which sets background before a turn (비싼데 살까? = it's pricey, but shall I buy it?). The everyday pitfall is over-translating it as a strong 'however'; if you mean a firm, contrastive 'however', reach for 하지만. And don't write the long form in chat — Koreans type 근데."},sentence:{ko:"알겠어요. 그런데 발표 전에 자료는 보내 줄 수 있어요?",en:"I understand. But can you send the materials before the presentation?"},target:"그런데",options:["but; by the way","so; what you mean is","softly; gently; smoothly"],note:"Shifts from accepting the situation to asking for the next action."},{kind:"guess",word:{ko:"근데",romanization:"geunde",en:"but; by the way (casual)",pos:"adverb",nuance:"근데 is common in speech, but it can sound too casual in a presentation, email, or formal announcement."},sentence:{ko:"근데 그건 조금 어려운데요.",en:"But that is a little difficult, though."},target:"근데",options:["so; what you mean is","softly; gently; smoothly","but; by the way (casual)"],note:"Casual version of 그런데 for spoken conversation."},{kind:"guess",word:{ko:"그러니까",romanization:"geureonikka",en:"so; what you mean is",pos:"adverb",nuance:"그러니까 means 'so / that's why' and presents what follows as the reason-driven result of what came before. It comes from 그렇다 + -(으)니까 ('because it is so'), and that -니까 root is the key to its flavor: -니까 is the 'because' that naturally leads into commands, requests, and urging, which is exactly why 그러니까 pairs so well with advice (일찍 자요) and 'I-told-you-so' lines. This is the sharp dividing line from near-synonym 그래서: 그래서 (from 그렇다 + -아서) merely REPORTS a result neutrally ('so, as a result'), and crucially 그래서 cannot head a command, while 그러니까 actively REASONS and PERSUADES and happily does. Beyond logic, 그러니까 is a heavy conversational filler — 그러니까 내 말이 means 'exactly, that's my point!' (strong agreement), and a trailing 그러니까... works like English 'I mean...' when you restate yourself. English speakers who treat it as a plain synonym of 그래서 miss both the urging nuance and these idiomatic uses."},sentence:{ko:"그러니까 먼저 회의를 시작해도 된다는 말이죠?",en:"So you mean we can start the meeting first, right?"},target:"그러니까",options:["so; what you mean is","actually; to be honest","but; by the way"],note:"Checks the implied meaning before moving on."},{kind:"guess",word:{ko:"잖아요",romanization:"janhayo",en:"you know; as you know",pos:"ending",nuance:"잖아요 is for shared information. For new background, use -거든요 instead."},sentence:{ko:"회의 시간이 짧잖아요.",en:"The meeting time is short, you know."},target:"잖아요",options:["you know; as you know","you see; the thing is","though; soft trailing ending"],note:"Use when the listener already knows the reason."},{kind:"guess",word:{ko:"거든요",romanization:"geodeunyo",en:"you see; the thing is",pos:"ending",nuance:"거든요 gives new background. It is softer than just dropping a reason, but it can sound defensive if the tone is too clipped."},sentence:{ko:"어제 갑자기 일이 생겼거든요.",en:"Something suddenly came up yesterday, you see."},target:"거든요",options:["you see; the thing is","you know; as you know","though; soft trailing ending"],note:"Use when the listener does not know the background yet."},{kind:"payoff",line:{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},hl:"사실은"}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b1",chapterId:"chapter-35",index:0},{kind:"pattern",title:"문법 Grammar · V/A-(으)ㄴ/는데",cards:[{kind:"hunt",name:"V/A-(으)ㄴ/는데",sub:"Giving Background Before Your Point",lines:[{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"없",mid:"는데",post:"",hit:!0},{pre:"택시",mid:"",post:"",hit:!1},{pre:"탈까요?",mid:"",post:"",hit:!1}],ko:"시간이 없는데 택시 탈까요?",en:"We don't have time, so should we take a taxi?",romanization:"sigani eomneunde taeksi talkkayo?"},{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"밥",mid:"",post:"",hit:!1},{pre:"먹",mid:"는데",post:"",hit:!0},{pre:"이따가",mid:"",post:"",hit:!1},{pre:"전화할게요.",mid:"",post:"",hit:!1}],ko:"지금 밥 먹는데 이따가 전화할게요.",en:"I'm eating right now, so I'll call you later.",romanization:"jigeum bap meongneunde ittaga jeonhwahalgeyo."}],rule:{name:"V/A-(으)ㄴ/는데",rows:[{when:"Action verb stem",add:"-는데",ex:"먹다 → 먹는데, 가다 → 가는데"},{when:"Adjective stem ending in a vowel/ㄹ",add:"-ㄴ데",ex:"바쁘다 → 바쁜데, 멀다 → 먼데 (ㄹ drops)"},{when:"Adjective stem ending in a consonant",add:"-은데",ex:"작다 → 작은데, 좋다 → 좋은데"},{when:"Noun + 이다 / past tense",add:"인데 / -았/었는데",ex:"학생이다 → 학생인데, 먹다 → 먹었는데"}]},more:{func:'Use -(으)ㄴ/는데 to give a piece of background first, then say what you really mean (a question, a suggestion, or a request) in the next clause. It loosely links two ideas, a bit like English "so..." or "and...".',funcLead:"Use -(으)ㄴ/는데 to give a piece of background first, then say what you really mean (a question, a suggestion, or a request) in the next clause.",keyPoint:{label:"-는데 vs. -아서/어서",body:"-아서/어서 ties a clause as a tight cause ('because A, B'). -(으)ㄴ/는데 just sets the scene ('A, and now...') and feels softer. Only -는데 can lead naturally into a -ㄹ까요? or -ㄹ래요? question. The full contrast use of -는데 comes later."},pronunciation:"는데 sounds like [는데] with no change, but after a ㄷ/ㅅ/ㅈ-final stem like 받다, 받는데 becomes [반는데] (the ㄷ turns into ㄴ before 는).",pitfall:{wrong:"시간이 없어서 택시 탈까요?",right:"시간이 없는데 택시 탈까요?",explanation:"English speakers grab -아서/어서 ('because') to lead into a suggestion, but -아서/어서 can't come before a -ㄹ까요?/-ㄹ래요? ending. Use -는데 to set up the background first."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "We don't have time, so should we take a taxi?"`,tokens:["시간이","없는데","택시","탈까요?"],correct:"시간이 없는데 택시 탈까요?",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm eating right now, so I'll call you later."`,tokens:["지금","밥","먹는데","이따가","전화할게요."],correct:"지금 밥 먹는데 이따가 전화할게요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"시간이 없는데 택시 탈까요?",ok:!0},{text:"시간이 없어서 택시 탈까요?",ok:!1}],explanation:"English speakers grab -아서/어서 ('because') to lead into a suggestion, but -아서/어서 can't come before a -ㄹ까요?/-ㄹ래요? ending. Use -는데 to set up the background first."}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b2",chapterId:"chapter-35",index:1},{kind:"words",title:"단어 Words 2 · 는데요~",cards:[{kind:"guess",word:{ko:"는데요",romanization:"neundeyo",en:"though; soft trailing ending",pos:"ending",nuance:"는데요 is not only 'but'. It often sets up background and hands the next move to the listener."},sentence:{ko:"자료가 아직 안 끝났는데요.",en:"The materials are not finished yet, though."},target:"는데요",options:["you know; as you know","though; soft trailing ending","you see; the thing is"],note:"Leaves space for the listener to respond."},{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"materials; data; documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"회의 전에 자료를 보내 줄게요.",en:"I will send the materials before the meeting."},target:"자료",options:["the other person; conversation partner","materials; data; documents","atmosphere; mood"],note:"The actual file, handout, slide deck, or reference material."},{kind:"guess",word:{ko:"배경",romanization:"baegyeong",en:"background; context",pos:"noun",nuance:"배경 is broader than 이유. 이유 is the reason; 배경 is the surrounding context that makes the reason understandable."},sentence:{ko:"제가 먼저 배경을 설명할게요.",en:"I will explain the background first."},target:"배경",options:["background; context","the other person; conversation partner","atmosphere; mood"],note:"Context that helps the listener understand the situation."},{kind:"guess",word:{ko:"상대방",romanization:"sangdaebang",en:"the other person; conversation partner",pos:"noun",nuance:"상대방 is neutral. It is not necessarily an opponent; it can simply mean the other person in the interaction."},sentence:{ko:"상대방이 모르는 내용이면 거든요가 더 자연스러워요.",en:"If the other person does not know it, 거든요 is more natural."},target:"상대방",options:["materials; data; documents","background; context","the other person; conversation partner"],note:"The listener's knowledge decides the marker."},{kind:"guess",word:{ko:"부드럽게",romanization:"budeureopge",en:"softly; gently; smoothly",pos:"adverb",nuance:"부드럽게 is about manner or tone. It does not automatically make the content polite if the sentence itself is too direct."},sentence:{ko:"그 의견에는 부드럽게 반대하는 게 좋아요.",en:"It is better to disagree with that opinion gently."},target:"부드럽게",options:["actually; to be honest","softly; gently; smoothly","but; by the way"],note:"Names the tone this chapter is practicing."},{kind:"guess",word:{ko:"말을 꺼내다",romanization:"mareul kkeonaeda",en:"to bring up a topic",pos:"phrase",nuance:"말을 꺼내다 is about starting a topic, not physically taking words out. It often implies a little hesitation or tact."},sentence:{ko:"자료가 늦어진 이야기는 제가 먼저 말을 꺼낼게요.",en:"I will bring up the delayed materials first."},target:"말을 꺼낼",options:["actually; to be honest","to bring up a topic","but; by the way"],note:"말 means words or speech here."},{kind:"payoff",line:{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet."},hl:"는데요"}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b3",chapterId:"chapter-35",index:2},{kind:"pattern",title:"문법 Grammar · V/A-잖아요",cards:[{kind:"hunt",name:"V/A-잖아요",sub:"Reminding Someone of What You Both Know",lines:[{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"식당은",mid:"",post:"",hit:!1},{pre:"비싸",mid:"잖아요",post:".",hit:!0},{pre:"다른",mid:"",post:"",hit:!1},{pre:"데",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"그 식당은 비싸잖아요. 다른 데 가요.",en:"That restaurant is expensive, you know. Let's go somewhere else.",romanization:"geu sikdangeun bissajanayo. dareun de gayo."},{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"일요일이",mid:"잖아요",post:".",hit:!0},{pre:"학교",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘 일요일이잖아요. 학교 안 가요.",en:"It's Sunday today, remember? We don't have school.",romanization:"oneul iryoirijanayo. hakgyo an gayo."}],rule:{name:"V/A-잖아요",rows:[{when:"Any verb/adjective stem (present)",add:"-잖아요",ex:"비싸다 → 비싸잖아요, 가다 → 가잖아요"},{when:"Past tense",add:"-았/었잖아요",ex:"먹다 → 먹었잖아요, 보다 → 봤잖아요"},{when:"Noun + 이다",add:"-(이)잖아요",ex:"일요일이다 → 일요일이잖아요, 친구다 → 친구잖아요"},{when:"Casual (반말)",add:"-잖아",ex:"비싸잖아, 먹었잖아"}]},more:{func:'Use -잖아요 to remind the listener of something you both already know, or to point out something obvious as your reason. It carries the feeling of "you know..." or "remember...".',funcLead:"Use -잖아요 to remind the listener of something you both already know, or to point out something obvious as your reason.",keyPoint:{label:"-잖아요 vs. -거든요",body:"-잖아요 points to OLD information the listener already knows ('you know that...'). -거든요 gives NEW information they don't know yet. Using -잖아요 for brand-new facts sounds odd, like 'you should have known this already'."},pronunciation:"잖아요 links across the syllable and sounds like [자나요], with the ㅈ and ㅇ flowing together. Don't break it into [잗-아요].",pitfall:{wrong:"저 처음 보죠? 제 이름은 민수잖아요.",right:"저 처음 보죠? 제 이름은 민수거든요.",explanation:"Don't use -잖아요 for information that's new to the listener — it sounds like you're saying they should already know it, which can feel like a scolding. For brand-new info, use -거든요."}}},{kind:"drill",prompt:"We ate together yesterday, remember? Did you forget already?",sentence:"어제 같이 밥 먹었___. 벌써 잊었어요?",options:[{text:"잖아요",ok:!0},{text:"은데",ok:!1},{text:"ㄴ데",ok:!1}],explanation:"Past tense -었잖아요 brings back a shared experience."},{kind:"drill",prompt:"Minsu is good at Korean, you know. Ask him.",sentence:"민수 씨가 한국어 잘하___. 민수 씨한테 물어봐요.",options:[{text:"잖아요",ok:!0},{text:"은데",ok:!1},{text:"ㄴ데",ok:!1}],explanation:"Uses a known fact about Minsu to back up the suggestion."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "That restaurant is expensive, you know. Let's go somewhere else."`,tokens:["그","식당은","비싸잖아요.","다른","데","가요."],correct:"그 식당은 비싸잖아요. 다른 데 가요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "It's Sunday today, remember? We don't have school."`,tokens:["오늘","일요일이잖아요.","학교","안","가요."],correct:"오늘 일요일이잖아요. 학교 안 가요.",explanation:""}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b4",chapterId:"chapter-35",index:3},{kind:"words",title:"단어 Words 3 · 설명하다~",cards:[{kind:"guess",word:{ko:"설명하다",romanization:"seolmyeonghada",en:"to explain",pos:"verb",nuance:"설명하다 is 說明(설명)하다, hanja 說 'speak' + 明 'bright/clear', so it literally means to 'speak something into clarity' — you talk about a thing so the listener understands it. The dividing line against 설득하다 and 말하다 matters: 설명하다 is to make something UNDERSTOOD (neutral, informational), 설득하다 is to PERSUADE (change someone's mind), and 말하다 is just to 'say/tell' without the goal of clarifying. So '설명해 주세요' = 'help me understand,' which is far more specific than '말해 주세요' = 'just tell me.' The thing explained takes 을/를 (이유를 설명하다), and for a broad topic Koreans add -에 대해(서): 그 사건에 대해 설명했어요. Natural adverbs are 자세히 (in detail), 쉽게 (simply), 간단히 (briefly). The English-speaker pitfall is the construction 'explain me' / 'explain to me' — Korean attaches the listener with 에게/한테, not the object slot, and very often just uses 설명해 주다 (explain as a favor) to imply the listener. It is a regular 하다 verb: 설명 + 해요, negating as 설명 안 해요 / 설명 못 해요."},sentence:{ko:"제가 배경을 설명할게요.",en:"I will explain the background."},target:"설명할",options:["to agree","to oppose; to disagree","to explain"],note:"A practical verb for giving context."},{kind:"guess",word:{ko:"동의하다",romanization:"donguihada",en:"to agree",pos:"verb",nuance:"동의하다 is 同意(동의, 'same-meaning/intent') + 하다 — literally to be of the same mind, i.e. to agree with an opinion or consent to terms. Its key grammar point is the particle 에: you agree 'to/with' something, so 의견에 동의하다, 약관에 동의하다 — never 을/를. Contrast it with 찬성하다 (贊成, 'approve/support'), which is voting in favor of a proposal or course of action ('그 계획에 찬성해요'), a public stance, whereas 동의하다 is sharing a viewpoint or giving consent; you can 동의하다 that a problem exists yet not 찬성하다 the proposed solution. Also contrast 인정하다 (concede a truth) — agreeing is positive alignment, acknowledging is conceding. As a 하다 verb: 동의해요 / 동의했어요. The English-speaker pitfall is twofold: the particle (don't say 의견을 동의해요 — use 에), and the structure 'I agree that...', which in Korean is ~다는 것에 동의하다 or simply ~다고 생각해요; a bare 'I agree' in casual reply is more often 맞아요 ('that's right') or 그러게요, with 동의하다 sounding a touch formal."},sentence:{ko:"저도 그 의견에 동의해요.",en:"I agree with that opinion too."},target:"동의해",options:["to agree","to explain","actually; to be honest"],note:"Pairs with 의견 and polite discussion."},{kind:"guess",word:{ko:"반대하다",romanization:"bandaehada",en:"to oppose; to disagree",pos:"verb",nuance:"반대하다 means to oppose, object to, or be against something (反 'reverse/anti' + 對 'face/oppose', literally 'to face in the opposite direction'). The single most important thing for intermediate learners is the PARTICLE: the thing you oppose takes 에, never 을/를 — 의견에 반대하다, 계획에 반대하다. English 'oppose X' treats X as a direct object, so learners overwhelmingly write 의견을 반대해요, which is wrong. As a 하다 verb it contracts to 반대해요. Its clean antonym is 찬성하다 (to be in favor), which shares the same 에 frame. Keep it apart from 거부하다 (to refuse): 반대하다 is taking a stance against an idea in discussion, while 거부하다 is actively turning down a concrete request or offer."},sentence:{ko:"그 의견에는 조금 반대하는데요.",en:"I disagree with that opinion a little, though."},target:"반대하",options:["to explain","actually; to be honest","to oppose; to disagree"],note:"Use -는데요 to make disagreement less abrupt."},{kind:"guess",word:{ko:"분위기",romanization:"bunwigi",en:"atmosphere; mood",pos:"noun",nuance:"분위기 (雰圍氣, 雰 'mist/vapor' + 圍 'surround' + 氣 'air/energy') is literally 'the air that surrounds you' — the collective mood of a place, gathering, or moment. The sharp contrast is 분위기 vs 기분: 분위기 is the SHARED vibe in the room (회식 분위기가 좋다), while 기분 is one person's INNER feeling (제 기분이 좋다 'I'm in a good mood'). Mixing them is the classic error: 'I'm in a good mood' is 기분이 좋아요, not 분위기가 좋아요 (which describes the room, not you). Habitual partners: 분위기가 좋다/편안하다/어색하다, 분위기를 띄우다/바꾸다, 분위기가 가라앉다, 분위기를 깨다 ('kill the mood'). 분위기 있다 colloquially means 'has a classy/romantic ambiance.' The English-speaker pitfall, beyond 기분 confusion, is the particle: 분위기를 좋다 ✗ → 분위기가 좋다 ✓."},sentence:{ko:"그렇게 말하면 분위기가 조금 딱딱해져요.",en:"If you say it like that, the mood becomes a little stiff."},target:"분위기",options:["materials; data; documents","atmosphere; mood","background; context"],note:"Discourse markers affect the mood of a conversation."},{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation; circumstances",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"상황을 먼저 설명하면 상대방이 이해하기 쉬워요.",en:"If you explain the situation first, it is easier for the other person to understand."},target:"상황",options:["materials; data; documents","the other person; conversation partner","situation; circumstances"],note:"The larger situation tells you which marker fits."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"그 의견도 좋은데 시간이 부족해요.",en:"That opinion is good too, but we are short on time."},target:"의견",options:["opinion","background; context","the other person; conversation partner"],note:"Natural noun for agreeing, disagreeing, or softening pushback."}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b5",chapterId:"chapter-35",index:4},{kind:"pattern",title:"문법 Grammar · V/A-지요/죠",cards:[{kind:"teach",name:"V/A-지요/죠",sub:"Checking Shared Understanding",rows:[{when:"Verb/adjective stem",add:"-지요? / -죠?",ex:"덥다 → 덥지요? / 덥죠?, 재미있다 → 재미있죠?"},{when:"Past tense",add:"-았/었지요? / -았/었죠?",ex:"봤다 → 봤지요? / 봤죠?, 먹었다 → 먹었죠?"},{when:"Noun + 이다",add:"-(이)지요? / -(이)죠?",ex:"학생이다 → 학생이지요? / 학생이죠?, 친구다 → 친구죠?"},{when:"Casual",add:"-지?",ex:"덥지?, 맞지?"}],examples:[{ko:"오늘 정말 덥죠?",en:"It's really hot today, isn't it?",romanization:"oneul jeongmal deopjyo?",note:"Weather small talk: the speaker expects agreement, not new information."},{ko:"민수 씨는 학생이지요?",en:"Minsu is a student, right?",romanization:"minsu ssineun haksaengijiyo?",note:"Noun + 이다 becomes 학생이지요; the speaker is confirming something they think is true."}],more:{func:`Use -지요? or its spoken contraction -죠? when you think you already know the answer and want the listener to confirm or agree. It is softer than a plain information question because it sounds like "right?" or "you know, don't you?" In everyday speech, -죠 is more common than the full -지요.`,funcLead:"Use -지요?",keyPoint:{label:"-아요? asks; -지요?/죠? confirms",body:"Use -아요? when you do not know and need information. Use -지요?/죠? when you already have an idea and want confirmation, agreement, or shared footing. If you truly have no idea, plain -아요? is safer."},pronunciation:"The contracted 죠 is one quick syllable. After a stop consonant like the ㅂ in 덥죠, the ㅈ is always pronounced tense, so 덥죠 sounds like [덥쬬] at any speed — but keep the spelling 덥죠, not 덥쬬.",pitfall:{wrong:"이름이 뭐죠? (when you truly do not know and are asking a stranger)",right:"이름이 뭐예요? / 성함이 어떻게 되세요?",explanation:"English tag questions are flexible, so learners overuse -죠 for ordinary questions. But -죠 suggests you expected or half-knew the answer. For new information, use a normal question; save -죠 for confirmation or shared facts."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "It's really hot today, isn't it?"`,tokens:["오늘","정말","덥죠?"],correct:"오늘 정말 덥죠?",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Minsu is a student, right?"',tokens:["민수","씨는","학생이지요?"],correct:"민수 씨는 학생이지요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"이름이 뭐죠? (when you truly do not know and are asking a stranger)",ok:!1},{text:"이름이 뭐예요? / 성함이 어떻게 되세요?",ok:!0}],explanation:"English tag questions are flexible, so learners overuse -죠 for ordinary questions. But -죠 suggests you expected or half-knew the answer. For new information, use a normal question; save -죠 for confirmation or shared facts."}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b6",chapterId:"chapter-35",index:5},{kind:"pattern",title:"문법 Grammar · V/A-거든요",cards:[{kind:"hunt",name:"V/A-거든요",sub:"Adding a Reason They Didn't Know",lines:[{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"만나요.",mid:"",post:"",hit:!1},{pre:"할",mid:"",post:"",hit:!1},{pre:"일이",mid:"",post:"",hit:!1},{pre:"많",mid:"거든요",post:".",hit:!0}],ko:"오늘은 못 만나요. 할 일이 많거든요.",en:"I can't meet today. I have a lot to do, you see.",romanization:"oneureun mot mannayo. hal iri mankeodeunyo."},{tokens:[{pre:"저",mid:"",post:"",hit:!1},{pre:"요즘",mid:"",post:"",hit:!1},{pre:"한국어",mid:"",post:"",hit:!1},{pre:"배워요.",mid:"",post:"",hit:!1},{pre:"한국",mid:"",post:"",hit:!1},{pre:"친구가",mid:"",post:"",hit:!1},{pre:"많",mid:"거든요",post:".",hit:!0}],ko:"저 요즘 한국어 배워요. 한국 친구가 많거든요.",en:"I'm learning Korean these days. I have a lot of Korean friends, you see.",romanization:"jeo yojeum hangugeo baewoyo. hanguk chinguga mankeodeunyo."}],rule:{name:"V/A-거든요",rows:[{when:"Any verb/adjective stem (present)",add:"-거든요",ex:"바쁘다 → 바쁘거든요, 가다 → 가거든요"},{when:"Past tense",add:"-았/었거든요",ex:"먹다 → 먹었거든요, 자다 → 잤거든요"},{when:"Noun + 이다",add:"-(이)거든요",ex:"학생이다 → 학생이거든요, 친구다 → 친구거든요"},{when:"Casual (반말)",add:"-거든",ex:"바쁘거든, 먹었거든"}]},more:{func:`Use -거든요 to give the listener new information — usually a reason or background fact they didn't know — often answering a spoken or silent "why?". It feels like "...you see" at the end.`,funcLead:`Use -거든요 to give the listener new information — usually a reason or background fact they didn't know — often answering a spoken or silent "why?".`,keyPoint:{label:"-거든요 vs. -아서/어서",body:"Both can give a reason, but -아서/어서 joins two clauses inside one sentence ('A여서 B'). -거든요 ends the sentence and tacks the reason on afterward as a fresh follow-up — it signals 'here's something you didn't know'. -아서/어서 doesn't carry that 'news' feeling."},pronunciation:"거든요 keeps each syllable clear: [거든뇨] in fast speech as the ㄴ and ㅛ glide together. Don't soften it to [거더요].",pitfall:{wrong:"일이 많거든요 못 만나요.",right:"오늘은 못 만나요. 일이 많거든요.",explanation:"-거든요 goes at the END of a sentence, not in the middle like English 'because'. Say your main point first, then add the reason as a separate sentence ending in -거든요."}}},{kind:"drill",prompt:"I went to bed early yesterday. I was so tired, you see.",sentence:"어제 일찍 잤어요. 너무 피곤했___.",options:[{text:"은데",ok:!1},{text:"ㄴ데",ok:!1},{text:"거든요",ok:!0}],explanation:"Past tense -었거든요 gives the reason for a past action."},{kind:"drill",prompt:"I brought an umbrella today. They said it would rain, you see.",sentence:"오늘 우산 가져왔어요. 비가 온다고 했___.",options:[{text:"거든요",ok:!0},{text:"은데",ok:!1},{text:"ㄴ데",ok:!1}],explanation:"Introduces a new fact that explains the action."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I can't meet today. I have a lot to do, you see."`,tokens:["오늘은","못","만나요.","할","일이","많거든요."],correct:"오늘은 못 만나요. 할 일이 많거든요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"일이 많거든요 못 만나요.",ok:!1},{text:"오늘은 못 만나요. 일이 많거든요.",ok:!0}],explanation:"-거든요 goes at the END of a sentence, not in the middle like English 'because'. Say your main point first, then add the reason as a separate sentence ending in -거든요."}],canDo:"Soften a reply and leave room to react with trailing -는데요",id:"chapter-35-b7",chapterId:"chapter-35",index:6},{kind:"pattern",title:"문법 Grammar · V/A-는데요",cards:[{kind:"hunt",name:"V/A-는데요",sub:"A Soft, Trailing Ending",lines:[{tokens:[{pre:"그건",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"모르",mid:"는데요",post:".",hit:!0}],ko:"그건 잘 모르는데요.",en:"Hmm, I don't really know that...",romanization:"geugeon jal moreunde-yo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"벌써",mid:"",post:"",hit:!1},{pre:"다",mid:"",post:"",hit:!1},{pre:"먹었",mid:"는데요",post:".",hit:!0}],ko:"저는 벌써 다 먹었는데요.",en:"But I already finished eating...",romanization:"jeoneun beolsseo da meogeonneunde-yo."}],rule:{name:"V/A-는데요",rows:[{when:"Action verb (present)",add:"-는데요",ex:"가다 → 가는데요, 먹다 → 먹는데요"},{when:"Adjective (present)",add:"-(으)ㄴ데요",ex:"바쁘다 → 바쁜데요, 작다 → 작은데요"},{when:"Past tense",add:"-았/었는데요",ex:"가다 → 갔는데요, 좋다 → 좋았는데요"},{when:"Noun + 이다",add:"인데요",ex:"학생이다 → 학생인데요"}]},more:{func:"Use sentence-final -는데요 to leave your statement gently open, inviting the other person to react or softening a reply. It often hints at an unspoken 'but...', which makes answers and mild objections sound polite instead of blunt.",funcLead:"Use sentence-final -는데요 to leave your statement gently open, inviting the other person to react or softening a reply.",keyPoint:{label:"-는데 vs. -는데요",body:"-는데 in the middle of a sentence sets up background for a following clause. -는데요 stands at the very END as a soft, open finish. Same shape, but here it's a complete reply that trails off, not a connector. The honorific 요 is what makes it a polite stand-alone ending."},pronunciation:"는데요 sounds like [는데요]; after a ㄷ/ㅅ/ㅈ-final stem the ㄴ-change still applies (먹었는데요 → [머건는데요]). Let the final 요 drift up slightly to keep the soft, open feel.",pitfall:{wrong:"지금 바빠요. (flat, can sound blunt when declining)",right:"지금 좀 바쁜데요.",explanation:"English speakers end a refusal with a plain -아요/어요, which can land too direct in Korean. Adding -는데요 leaves the sentence softly open, so a 'no' feels gentler and more polite."}}},{kind:"drill",prompt:"Um, someone's sitting here...",sentence:"여기 자리 있___.",options:[{text:"는데요",ok:!0},{text:"은데",ok:!1},{text:"ㄴ데",ok:!1}],explanation:"Softly tells someone a seat is taken without sounding harsh."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Hmm, I don't really know that..."`,tokens:["그건","잘","모르는데요."],correct:"그건 잘 모르는데요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "But I already finished eating..."',tokens:["저는","벌써","다","먹었는데요."],correct:"저는 벌써 다 먹었는데요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"지금 바빠요. (flat, can sound blunt when declining)",ok:!1},{text:"지금 좀 바쁜데요.",ok:!0}],explanation:"English speakers end a refusal with a plain -아요/어요, which can land too direct in Korean. Adding -는데요 leaves the sentence softly open, so a 'no' feels gentler and more polite."}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b8",chapterId:"chapter-35",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A team member brings up unfinished materials before a meeting starts.",lines:[{speaker:"민서",ko:"사실은 오늘 자료가 아직 다 안 끝났는데요.",en:"Actually, today's materials are not finished yet.",romanization:"sasireun oneul jaryoga ajik da an kkeunnanneundeyo."},{speaker:"지훈",ko:"그러니까 먼저 회의를 시작해도 된다는 말이죠?",en:"So you mean we can start the meeting first, right?",romanization:"geureonikka meonjeo hoeuireul sijakaedo doendaneun marijyo?"},{speaker:"민서",ko:"네. 어제 갑자기 일이 생겼거든요.",en:"Yes. Something suddenly came up yesterday, you see.",romanization:"ne. eoje gapjagi iri saenggyeotgeodeunyo."},{speaker:"지훈",ko:"알겠어요. 그런데 발표 전에 자료는 보내 줄 수 있어요?",en:"I understand. But can you send the materials before the presentation?",romanization:"algesseoyo. geureonde balpyo jeone jaryoneun bonae jul su isseoyo?"},{speaker:"민서",ko:"네, 그건 가능해요. 회의 시간이 짧잖아요.",en:"Yes, that is possible. The meeting time is short, you know.",romanization:"ne, geugeon ganeunghaeyo. hoeui sigani jjaljanhayo."},{speaker:"지훈",ko:"그럼 제가 먼저 배경을 설명할게요.",en:"Then I will explain the background first.",romanization:"geureom jega meonjeo baegyeongeul seolmyeonghalgeyo."}]},{kind:"order",prompt:"Build: 'Actually, the materials are late, you see.'",tokens:["사실은","자료가 늦었거든요"],correct:"사실은 자료가 늦었거든요",explanation:"사실은 prepares the listener for sensitive background. -거든요 explains new information rather than reminding them of something shared."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"알겠어요. 그런데 발표 전에 자료는 보내 줄 수 있어요?",options:[{text:"민서",ok:!1},{text:"지훈",ok:!0}],explanation:"I understand. But can you send the materials before the presentation?"},{kind:"drill",prompt:`무엇이 들어갈까요? · "Actually, today's materials are not finished yet."`,sentence:"___ 오늘 자료가 아직 다 안 끝났는데요.",options:[{text:"그러니까",ok:!1},{text:"사실은",ok:!0},{text:"부드럽게",ok:!1}],explanation:""}],canDo:"Lead with background before my real point using -(으)ㄴ/는데 (어제 못 왔는데...)",id:"chapter-35-b9",chapterId:"chapter-35",index:8},{kind:"reading",title:"읽기 Reading · 자료가 아직 안 끝났는데요",cards:[{kind:"read",title:"자료가 아직 안 끝났는데요",chunks:["팀 회의에서 자료가 늦어졌다면 바로 '못 했어요'라고만 말하면 조금 딱딱하게 들릴 수 있어요. 먼저 '사실은'으로 말을 꺼내고, '자료가 아직 안 끝났는데요'처럼 상황을 부드럽게 열어 주세요.","상대방이 모르는 이유를 설명할 때는 '어제 갑자기 일이 생겼거든요'가 자연스럽고, 이미 같이 아는 사실을 다시 짚을 때는 '회의 시간이 짧잖아요'가 자연스러워요. 그다음에는 '그런데 발표 전에 자료는 보내 줄 수 있어요?'처럼 다음 행동을 확인하면 대화가 멈추지 않아요."],translation:"If the materials are late in a team meeting, simply saying 'I did not do it' can sound stiff. Open the topic with 사실은, soften the situation with -는데요, use -거든요 for new background, and use -잖아요 for shared information. Then move the conversation to the next action.",qas:[{q:"자료가 늦어졌을 때 먼저 어떤 표현으로 말을 꺼낼 수 있어요?",a:"사실은으로 말을 꺼낼 수 있어요."},{q:"상대방이 모르는 이유를 설명할 때 어떤 표현이 자연스러워요?",a:"거든요가 자연스러워요."},{q:"이미 같이 아는 사실을 다시 짚을 때는 어떤 표현이 자연스러워요?",a:"잖아요가 자연스러워요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"팀 회의에서 ___가 늦어졌다면 바로 '못 했어요'라고만 말하면 조금 딱딱하게 들릴 수 있어요.",options:[{text:"분위기",ok:!1},{text:"근데",ok:!1},{text:"자료",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"먼저 '사실은'으로 말을 꺼내고, '자료가 아직 안 끝났는데요'처럼 상황을 ___ 열어 주세요.",options:[{text:"근데",ok:!1},{text:"그러니까",ok:!1},{text:"부드럽게",ok:!0}],explanation:""}],canDo:"Remind someone of something we both know with -잖아요 (시험이 있잖아요)",id:"chapter-35-b10",chapterId:"chapter-35",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"The listener does not know why the materials are late. Which ending fits best?",sentence:null,options:[{text:"어제 갑자기 일이 생겼거든요.",ok:!0},{text:"어제 갑자기 일이 생겼잖아요.",ok:!1},{text:"어제 갑자기 일이 생겼네요.",ok:!1}],explanation:"Use -거든요 for new background the listener does not know yet."},{kind:"drill",prompt:"Everyone knows the meeting time is short. Which sentence uses that shared fact naturally?",sentence:null,options:[{text:"회의 시간이 짧잖아요.",ok:!0},{text:"회의 시간이 짧거든요.",ok:!1},{text:"회의 시간이 짧네요.",ok:!1}],explanation:"Use -잖아요 when the reason is shared, visible, or already mentioned."},{kind:"drill",prompt:"Which sentence brings up bad news most softly?",sentence:null,options:[{text:"사실은 자료가 아직 안 끝났는데요.",ok:!0},{text:"자료 안 끝났습니다. 끝.",ok:!1},{text:"자료가 안 끝났잖아요, 왜 몰라요?",ok:!1}],explanation:"사실은 opens the topic and -는데요 leaves room for the next step."},{kind:"drill",prompt:"자료___ 아직 안 왔거든요. (The thing is, the materials have not arrived yet.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"자료 is the subject of not arriving, so it takes 가. 거든요 adds new background the listener may not know."},{kind:"drill",prompt:"You need to bring up bad news softly. Which opener is best?",sentence:null,options:[{text:"사실은 문제가 좀 있는데요.",ok:!0},{text:"문제 있어요.",ok:!1},{text:"문제입니다.",ok:!1}],explanation:"사실은 and -는데요 soften the approach. The shorter alternatives can sound abrupt in a sensitive conversation."}],canDo:"Add a reason they didn't know with -거든요 (감기에 걸렸거든요)",id:"chapter-35-b11",chapterId:"chapter-35",index:10}]},{id:"chapter-36",number:36,title:"V/A-더라고요 · V/A-더니",goal:"Use 가 보니까 and -더라고요 to report firsthand observations.",biteCount:8,bites:[{kind:"words",title:"단어 Words 1 · 보니까~",cards:[{kind:"guess",word:{ko:"보니까",romanization:"bonikka",en:"when I saw/tried/checked",pos:"expression",nuance:"보니까 is evidence-based. It sounds odd if you did not actually see, try, or check the thing."},sentence:{ko:"가 보니까 생각보다 괜찮더라고요.",en:"When I tried going, it was better than I expected."},target:"보니까",options:["when I saw/tried/checked","I noticed; it turned out","I observed X, and then Y happened"],note:"Experience leads into a firsthand observation."},{kind:"guess",word:{ko:"더라고요",romanization:"deoragoyo",en:"I noticed; it turned out",pos:"ending",nuance:"더라고요 is not just past tense. It carries the speaker's evidence and realization."},sentence:{ko:"생각보다 사람이 많더라고요.",en:"There were more people than I expected, I noticed."},target:"더라고요",options:["I observed X, and then Y happened","I noticed; it turned out","when I saw/tried/checked"],note:"Reports what the speaker personally saw."},{kind:"guess",word:{ko:"더니",romanization:"deoni",en:"I observed X, and then Y happened",pos:"ending",nuance:"Plain -더니 has an eyewitness feel. For your own action causing a result, -았/었더니 is usually the safer form."},sentence:{ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed."},target:"더니",options:["I noticed; it turned out","when I saw/tried/checked","I observed X, and then Y happened"],note:"Observed before-and-after change."},{kind:"guess",word:{ko:"생각보다",romanization:"saenggakboda",en:"more/less than expected",pos:"adverb",nuance:"생각보다 naturally pairs with 더라고요 because both talk about what you found after experience."},sentence:{ko:"음식이 생각보다 빨리 나오더라고요.",en:"The food came out faster than expected, I noticed."},target:"생각보다",options:["more/less than expected","when I saw/tried/checked","I noticed; it turned out"],note:"Expectation compared with real experience."},{kind:"guess",word:{ko:"처음에는",romanization:"cheoeumeneun",en:"at first",pos:"adverbial phrase",nuance:"처음에는 points to the first stage. It needs a later stage to feel complete."},sentence:{ko:"처음에는 조용하더니 금방 사람이 많아졌어요.",en:"It was quiet at first, and then there were quickly more people."},target:"처음에는",options:["at first","when I saw/tried/checked","I noticed; it turned out"],note:"Sets the first stage before a change."},{kind:"payoff",line:{speaker:"민서",ko:"어제 새 식당에 가 보니까 어땠어요?",en:"How was it when you tried going to the new restaurant yesterday?"},hl:"보니까"}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b1",chapterId:"chapter-36",index:0},{kind:"pattern",title:"문법 Grammar · V/A-더라고요",cards:[{kind:"hunt",name:"V/A-더라고요",sub:"reporting what I noticed firsthand",lines:[{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"영화",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"재미있",mid:"더라고요",post:".",hit:!0}],ko:"그 영화 정말 재미있더라고요.",en:"That movie was really fun (I saw for myself).",romanization:"geu yeonghwa jeongmal jaemiitdeoragoyo."},{tokens:[{pre:"어제",mid:"",post:"",hit:!1},{pre:"밖에",mid:"",post:"",hit:!1},{pre:"나갔는데",mid:"",post:"",hit:!1},{pre:"생각보다",mid:"",post:"",hit:!1},{pre:"춥",mid:"더라고요",post:".",hit:!0}],ko:"어제 밖에 나갔는데 생각보다 춥더라고요.",en:"I went outside yesterday, and it was colder than I thought.",romanization:"eoje bakke nagannneunde saenggakboda chupdeoragoyo."}],rule:{name:"V/A-더라고요",rows:[{when:"Verb stem (any ending)",add:"-더라고요",ex:"가다 → 가더라고요 / 먹다 → 먹더라고요"},{when:"Adjective stem (any ending)",add:"-더라고요",ex:"춥다 → 춥더라고요 / 좋다 → 좋더라고요"},{when:"Noun + 이다 / 아니다",add:"-더라고요",ex:"학생이다 → 학생이더라고요 / 아니다 → 아니더라고요"},{when:"Past tense (-았/었-)",add:"-더라고요",ex:"갔다 → 갔더라고요 / 끝났다 → 끝났더라고요"}]},more:{func:'Use -더라고요 to report something you personally saw, heard, or felt in the past, usually with a touch of mild surprise or fresh discovery. It means "I noticed / it turned out that..." — the information comes from your own direct experience, not from what someone else told you.',funcLead:"Use -더라고요 to report something you personally saw, heard, or felt in the past, usually with a touch of mild surprise or fresh discovery.",keyPoint:{label:"-더라고요 vs. plain -았/었어요",body:"Both talk about the past, but -았/었어요 just states a fact, while -더라고요 frames it as something YOU personally witnessed and are now reporting, often with mild surprise. '비가 왔어요' = it rained (fact); '비가 오더라고요' = I saw that it was raining."},pronunciation:"In casual speech -더라고요 is often written informally as -더라구요, but -더라고요 is the standard spelling. In 많더라고요, ㄶ combines with the following ㄷ and makes an aspirated ㅌ sound: [만터라고요].",pitfall:{wrong:"제가 어제 피곤하더라고요.",right:"제가 어제 피곤했어요. / (친구를 보고) 친구가 피곤해 보이더라고요.",explanation:"-더라고요 usually reports what you observe about OTHER people or the outside world, not your own feeling as you have it. For your own past feelings, use plain -았/었어요. (Your own feelings take -더라고요 only when you look back and 'notice' them as a discovery.)"}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "That movie was really fun (I saw for myself)."',tokens:["그","영화","정말","재미있더라고요."],correct:"그 영화 정말 재미있더라고요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I went outside yesterday, and it was colder than I thought." (어제 시작 · Start with 어제.)',tokens:["어제","밖에","나갔는데","생각보다","춥더라고요."],correct:"어제 밖에 나갔는데 생각보다 춥더라고요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"제가 어제 피곤했어요. / (친구를 보고) 친구가 피곤해 보이더라고요.",ok:!0},{text:"제가 어제 피곤하더라고요.",ok:!1}],explanation:"-더라고요 usually reports what you observe about OTHER people or the outside world, not your own feeling as you have it. For your own past feelings, use plain -았/었어요. (Your own feelings take -더라고요 only when you look back and 'notice' them as a discovery.)"}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b2",chapterId:"chapter-36",index:1},{kind:"words",title:"단어 Words 2 · 예전에는~",cards:[{kind:"guess",word:{ko:"예전에는",romanization:"yejeoneneun",en:"in the past; before",pos:"adverbial phrase",nuance:"예전에는 is broader than 어제 or 지난주. It points to an earlier period, not one exact moment."},sentence:{ko:"예전에는 사람이 적었다고 들었어요.",en:"I heard there used to be fewer people."},target:"예전에는",options:["when I saw/tried/checked","I noticed; it turned out","in the past; before"],note:"Sets up an earlier state."},{kind:"guess",word:{ko:"요즘은",romanization:"yojeumeun",en:"these days; nowadays",pos:"adverbial phrase",nuance:"요즘은 is not just today. It means the recent/current period."},sentence:{ko:"요즘은 분위기가 많이 달라졌더라고요.",en:"These days, the atmosphere has changed a lot, I noticed."},target:"요즘은",options:["when I saw/tried/checked","I noticed; it turned out","these days; nowadays"],note:"Current state after a change."},{kind:"guess",word:{ko:"붐비다",romanization:"bumbida",en:"to be crowded",pos:"verb",nuance:"붐비다 describes the place or route becoming crowded. 사람이 많다 describes the number of people more directly."},sentence:{ko:"점심시간이 되니까 식당이 붐비더라고요.",en:"When it became lunchtime, the restaurant got crowded, I noticed."},target:"붐비",options:["to become different; to change","to be crowded","to increase"],note:"Place-focused crowding."},{kind:"guess",word:{ko:"조용하다",romanization:"joyonghada",en:"quiet",pos:"adjective",nuance:"조용하다 is the opposite of 시끄럽다 and covers both a quiet PLACE/sound and a calm, reserved PERSONALITY (성격이 조용하다 = soft-spoken, low-key). As a 하다-adjective it conjugates regularly: 조용하다 → 조용해요 → 조용한 → 조용히(adverb, note the special 히 form) → 조용해서. The most useful distinction for English speakers is the adverb: 'be quiet!' is 조용히 해! (using 조용히), not 조용하게 — Koreans overwhelmingly use 조용히 here, so memorize it as a set phrase. The near-synonym 고요하다 is more literary/poetic and means a deep, serene stillness (고요한 밤 'a serene night'), whereas 조용하다 is the everyday neutral word you'd actually speak. Pitfall: writing 조용하요 instead of the contracted 조용해요, and reaching for 조용하게 when 조용히 is the natural adverb. Register is neutral and extremely common."},sentence:{ko:"처음에는 식당이 조용하더라고요.",en:"At first, the restaurant was quiet, I noticed."},target:"조용하",options:["quiet","when I saw/tried/checked","I noticed; it turned out"],note:"Good first state before -더니."},{kind:"guess",word:{ko:"금방",romanization:"geumbang",en:"soon; quickly; in a moment",pos:"adverb",nuance:"금방 is a two-faced time word: with a FUTURE verb it means 'in a moment / very soon' (금방 올게요 'I'll be right back'), and with a PAST verb it means 'just now / a moment ago' (금방 갔어요 'left just now'). The tense of the verb decides which reading you get, so the same word swings both ways around the present — that's the thing to internalize. The sharp contrast is 금방 vs 방금: 방금 'just now' is strictly PAST (방금 도착했어요 'I just arrived') and cannot mean 'soon', whereas 금방 covers both directions. Origin-wise 금방 is Sino-Korean 今方 'now-just', and it's thoroughly casual, everyday speech. The classic English-speaker error is forcing 방금 into a future sentence or assuming 금방 only means 'soon' and missing its 'a moment ago' use. It takes no particle, sits before the verb, and habitually pairs with 오다/가다, 되다 ('be ready'), and 끝나다."},sentence:{ko:"처음에는 조용하더니 금방 사람이 많아졌어요.",en:"It was quiet at first, and then there were quickly more people."},target:"금방",options:["when I saw/tried/checked","soon; quickly; in a moment","I noticed; it turned out"],note:"Marks a fast change."},{kind:"payoff",line:{speaker:"지훈",ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed."},hl:"붐비"}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b3",chapterId:"chapter-36",index:2},{kind:"pattern",title:"문법 Grammar · V/A-더니",cards:[{kind:"hunt",name:"V/A-더니",sub:"I saw X happen, and then Y followed",lines:[{tokens:[{pre:"동생이",mid:"",post:"",hit:!1},{pre:"아까",mid:"",post:"",hit:!1},{pre:"울",mid:"더니",post:"",hit:!0},{pre:"지금은",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"놀아요.",mid:"",post:"",hit:!1}],ko:"동생이 아까 울더니 지금은 잘 놀아요.",en:"My little brother was crying earlier, and now he's playing happily.",romanization:"dongsaengi akka uldeoni jigeumeun jal norayo."},{tokens:[{pre:"아침에는",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"오",mid:"더니",post:"",hit:!0},{pre:"오후에는",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋아요.",mid:"",post:"",hit:!1}],ko:"아침에는 비가 오더니 오후에는 날씨가 좋아요.",en:"It was raining in the morning, but in the afternoon the weather is nice.",romanization:"achimeneun biga odeoni ohueneun nalssiga joayo."}],rule:{name:"V/A-더니",rows:[{when:"Verb stem (any ending)",add:"-더니",ex:"울다 → 울더니 / 먹다 → 먹더니"},{when:"Adjective stem (any ending)",add:"-더니",ex:"덥다 → 덥더니 / 좋다 → 좋더니"},{when:"Noun + 이다",add:"-더니",ex:"학생이다 → 학생이더니"},{when:"After a completed first action (-았/었-), often I-subject",add:"-더니",ex:"먹었다 → 먹었더니 / 갔다 → 갔더니"}]},more:{func:"Use -더니 to link two things you personally watched: 'I noticed X (in the past), and then Y happened.' The second part is often a change, a result, or a contrast that grows out of the first. The subject of the first part is usually someone else, not you.",funcLead:"Use -더니 to link two things you personally watched: 'I noticed X (in the past), and then Y happened.' The second part is often a change, a result, or a contrast…",keyPoint:{label:"-더니 vs. -았/었더니",body:"Plain -더니 reports what you watched someone else (or the world) do, then a follow-up. -았/었더니 usually has 'I' as the subject who finished an action, leading to a result you then found: '제가 밥을 먹었더니 졸려요' (I ate, and now I'm sleepy). Rule of thumb: 더니 → 'they...', 았/었더니 → 'I did..., and then...'."},pronunciation:"In -더니 the 더 is said clearly as [더], with no blending into the next part. With past -었더니, 었더 sounds like [얻떠] with a light tense ㄷ.",pitfall:{wrong:"제가 친구를 만나더니 기분이 좋았어요.",right:"제가 친구를 만났더니 기분이 좋았어요. / 친구가 저를 만나더니 반가워했어요.",explanation:"When 'I' am the one who finished the first action, use -았/었더니, not plain -더니. Plain -더니 is for watching someone else (or the world), so its first subject is usually NOT 'I.'"}}},{kind:"drill",prompt:"My friend ate way too much, and now says his stomach hurts.",sentence:"친구가 밥을 너무 많이 먹___ 배가 아프대요.",options:[{text:"더니",ok:!0},{text:"더라고요",ok:!1}],explanation:"The watched first part causes the second — a natural cause and effect with -더니."},{kind:"drill",prompt:"My brother studied hard, and so he did well on the test.",sentence:"동생이 열심히 공부하___ 시험을 잘 봤어요.",options:[{text:"더라고요",ok:!1},{text:"더니",ok:!0}],explanation:"-더니 shows the result naturally following the effort you witnessed."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My little brother was crying earlier, and now he's playing happily."`,tokens:["동생이","아까","울더니","지금은","잘","놀아요."],correct:"동생이 아까 울더니 지금은 잘 놀아요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "It was raining in the morning, but in the afternoon the weather is nice." (아침에는 시작 · Start with 아침에는.)',tokens:["아침에는","비가","오더니","오후에는","날씨가","좋아요."],correct:"아침에는 비가 오더니 오후에는 날씨가 좋아요.",explanation:""}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b4",chapterId:"chapter-36",index:3},{kind:"words",title:"단어 Words 3 · 달라지다~",cards:[{kind:"guess",word:{ko:"달라지다",romanization:"dallajida",en:"to become different; to change",pos:"verb",nuance:"달라지다 spotlights the before-and-after gap: something is now clearly unlike how it used to be, which makes it the everyday verb for noticing change in a person's looks, mood, or a situation. It's the inchoative of the adjective 다르다 (to be different) — 다르 + -아지다 'become' — and that origin is the #1 pitfall: 다르다 states a static difference between two things (A는 B와 달라요 = A is different from B), while 달라지다 is the dynamic act of becoming different over time (분위기가 달라졌어요 = the mood changed). It overlaps with 변하다 and 바뀌다, but the dividing line is focus: 달라지다 = 'the result looks different now,' 변하다 = 'the inner nature transformed,' 바뀌다 = 'one thing got swapped for another.' Both 달라지다 and the thing changing take 이/가; the form 달라져요 comes from -지다 verbs taking 어 in the 요-form (지+어 → 져)."},sentence:{ko:"요즘은 분위기가 많이 달라졌더라고요.",en:"These days, the atmosphere has changed a lot, I noticed."},target:"달라졌",options:["to be crowded","to become different; to change","to observe"],note:"Useful for before-now observations."},{kind:"guess",word:{ko:"늘다",romanization:"neulda",en:"to increase",pos:"verb",nuance:"늘다 means an amount, number, or ability grows bigger, and it is the everyday word for skills improving — 실력이 늘다 is THE phrase for 'getting better at something'. It is a ㄹ-irregular verb: the final ㄹ drops before endings beginning with ㄴ, ㅂ, or ㅅ, which is why the formal present is 늡니다 (not *늘습니다) — the ㄹ vanishes before -ㅂ니다. Watch the synonym split: 늘다 is intransitive (the thing increases by itself — 실력이 늘어요), while its causative twin 늘리다 is transitive (you increase a thing on purpose — 시간을 늘려요 = I extend the time). Compare also 증가하다, the stiff Sino-Korean 'increase' used in reports and statistics (인구가 증가했다); 늘다 is the warm spoken equivalent. The English-speaker pitfall is two-fold: first, forgetting the ㄹ-drop and saying *늘습니다; second, saying 'I improved my Korean' as if you act on it — Koreans say 한국어가 늘었어요 (Korean increased) with the skill as the subject, not as an object you operate on."},sentence:{ko:"요즘은 사람이 많이 늘었더라고요.",en:"These days, the number of people has increased a lot, I noticed."},target:"늘었",options:["to be crowded","to increase","to observe"],note:"A natural observed-change verb."},{kind:"guess",word:{ko:"줄다",romanization:"julda",en:"to decrease",pos:"verb",nuance:"줄다 is the exact opposite of 늘다 — it means an amount, number, or size gets smaller — and the two are learned as a pair (늘다/줄다). Like 늘다 it is a ㄹ-irregular verb, so the ㄹ drops before -ㅂ니다, giving the formal 줍니다 (not *줄습니다). The crucial synonym contrast is 줄다 vs 줄이다: 줄다 is intransitive — the thing shrinks by itself (소리가 줄었어요 = the sound got quieter on its own), while 줄이다 is the causative — you deliberately reduce something (소리를 줄였어요 = I turned the sound down). Its formal report-style synonym is 감소하다 (Sino-Korean 減少, 'reduce-decrease'), used for statistics; 줄다 is the natural conversational word. The English-speaker pitfall mirrors 늘다: don't say *줄습니다 (the ㄹ drops to make 줍니다), and don't put an object with 줄다. 'I reduced my spending' needs the transitive 줄이다 (지출을 줄였어요); 'my spending decreased' uses 줄다 with the subject particle (지출이 줄었어요)."},sentence:{ko:"요즘은 기다리는 시간이 줄었더라고요.",en:"These days, the waiting time has decreased, I noticed."},target:"줄었",options:["to be crowded","to decrease","to observe"],note:"Opposite of 늘다 for observed change."},{kind:"guess",word:{ko:"알게 되다",romanization:"alge doeda",en:"to come to know; to find out",pos:"phrase",nuance:"알게 되다 emphasizes the process of finding out. 알다 simply states that you know."},sentence:{ko:"직접 가 보니까 왜 유명한지 알게 됐어요.",en:"After going there myself, I found out why it is famous."},target:"알게 됐",options:["to come to know; to find out","when I saw/tried/checked","I observed X, and then Y happened"],note:"Discovery through experience."},{kind:"guess",word:{ko:"관찰하다",romanization:"gwanchalhada",en:"to observe",pos:"verb",nuance:"관찰하다 is useful for deliberate observation. For a casual visit, 가 보니까 or 보니까 often sounds more natural."},sentence:{ko:"일주일 동안 분위기가 어떻게 변하는지 관찰했어요.",en:"I observed how the atmosphere changed over a week."},target:"관찰했",options:["to be crowded","to become different; to change","to observe"],note:"More deliberate than casually noticing."}],canDo:"Contrast before and after with 예전에는 / 요즘은",id:"chapter-36-b5",chapterId:"chapter-36",index:4},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A friend asks about a new restaurant after someone visited it.",lines:[{speaker:"민서",ko:"어제 새 식당에 가 보니까 어땠어요?",en:"How was it when you tried going to the new restaurant yesterday?",romanization:"eoje sae sikdange ga bonikka eottaesseoyo?"},{speaker:"지훈",ko:"처음에는 조용하더니 금방 붐비더라고요.",en:"It was quiet at first, and then it quickly got crowded, I noticed.",romanization:"cheoeumeneun joyonghadeoni geumbang bumbideoragoyo."},{speaker:"민서",ko:"음식은 어땠어요?",en:"How was the food?",romanization:"eumsigeun eottaesseoyo?"},{speaker:"지훈",ko:"생각보다 빨리 나오고 맛도 괜찮더라고요.",en:"It came out faster than expected, and the taste was good too.",romanization:"saenggakboda ppalli naogo matdo gwaenchandeoragoyo."},{speaker:"민서",ko:"예전에는 사람이 적었다고 들었는데요.",en:"I heard there used to be fewer people.",romanization:"yejeoneneun sarami jeogeotdago deureonneundeyo."},{speaker:"지훈",ko:"맞아요. 요즘은 분위기가 많이 달라졌더라고요.",en:"Right. These days, the atmosphere has changed a lot, I noticed.",romanization:"majayo. yojeumeun bunwigiga mani dallajyeotdeoragoyo."}]},{kind:"order",prompt:"Build: 'When I tried going there, it was quieter than expected.'",tokens:["가 보니까","생각보다 조용하더라고요"],correct:"가 보니까 생각보다 조용하더라고요",explanation:"가 보니까 sets up what you learned by trying it yourself. -더라고요 reports the firsthand observation."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"맞아요. 요즘은 분위기가 많이 달라졌더라고요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"Right. These days, the atmosphere has changed a lot, I noticed."},{kind:"drill",prompt:'무엇이 들어갈까요? · "How was it when you tried going to the new restaurant yesterday?"',sentence:"어제 새 식당에 가 ___ 어땠어요?",options:[{text:"보니까",ok:!0},{text:"더라고요",ok:!1},{text:"더니",ok:!1}],explanation:""}],canDo:"Report something I personally saw or felt, with mild surprise, using -더라고요 (붐비더라고요)",id:"chapter-36-b6",chapterId:"chapter-36",index:5},{kind:"reading",title:"읽기 Reading · 가 보니까 생각보다 괜찮더라고요",cards:[{kind:"read",title:"가 보니까 생각보다 괜찮더라고요",chunks:["새 식당이나 카페에 다녀온 뒤에는 그냥 '좋았어요'라고 말할 수도 있지만, 직접 보고 느낀 느낌을 살리려면 '-더라고요'가 훨씬 자연스러워요. '가 보니까 생각보다 조용하더라고요'라고 하면 내가 직접 가서 알게 된 정보라는 느낌이 들어요. 시간이 지나면서 변한 모습을 말할 때는 '-더니'가 좋아요.","예를 들어 '처음에는 조용하더니 금방 붐비더라고요'라고 하면 처음 상태와 나중 상태가 한 장면처럼 이어져요. 하지만 내 행동 때문에 생긴 결과라면 '많이 먹었더니 졸렸어요'처럼 '-았/었더니'를 써야 해요."],translation:"After visiting a restaurant or cafe, -더라고요 lets you report what you personally noticed. -더니 links an observed first state to a later change. For the result of your own action, use -았/었더니 instead.",qas:[{q:"직접 보고 느낀 내용을 말할 때 어떤 표현이 자연스러워요?",a:"-더라고요가 자연스러워요."},{q:"처음 상태와 나중 상태를 이어 말할 때 어떤 표현이 좋아요?",a:"-더니가 좋아요."},{q:"내 행동 때문에 생긴 결과에는 어떤 형태를 써야 해요?",a:"-았/었더니를 써야 해요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"새 식당이나 카페에 다녀온 뒤에는 그냥 '좋았어요'라고 말할 수도 있지만, 직접 보고 느낀 느낌을 살리려면 '-___'가 훨씬 자연스러워요.",options:[{text:"예전에는",ok:!1},{text:"더라고요",ok:!0},{text:"요즘은",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"시간이 지나면서 변한 모습을 말할 때는 '-___'가 좋아요.",options:[{text:"예전에는",ok:!1},{text:"요즘은",ok:!1},{text:"더니",ok:!0}],explanation:""}],canDo:"Link 'I noticed X, and then Y followed' with -더니 (늘더니 붐비더라고요)",id:"chapter-36-b7",chapterId:"chapter-36",index:6},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"You visited the restaurant yourself and noticed it was crowded. Which sentence fits best?",sentence:null,options:[{text:"사람이 많더라고요.",ok:!0},{text:"사람이 많대요.",ok:!1},{text:"사람이 많기로 했어요.",ok:!1}],explanation:"-더라고요 reports a firsthand observation."},{kind:"drill",prompt:"Which sentence shows an observed change over time?",sentence:null,options:[{text:"처음에는 조용하더니 금방 붐비더라고요.",ok:!0},{text:"처음에는 조용하기 위해 금방 붐볐어요.",ok:!1},{text:"처음에는 조용할 뿐이더라고요.",ok:!1}],explanation:"-더니 connects the observed first state with the later change."},{kind:"drill",prompt:"You ate a lot, so you became sleepy. Which form is correct?",sentence:null,options:[{text:"많이 먹었더니 졸렸어요.",ok:!0},{text:"많이 먹더니 졸렸어요.",ok:!1},{text:"많이 먹더라고요 졸렸어요.",ok:!1}],explanation:"Use -았/었더니 for your own action leading to a result."},{kind:"drill",prompt:"그 식당___ 가 보니까 생각보다 조용하더라고요. (When I tried going to that restaurant...)",sentence:null,options:[{text:"에",ok:!0},{text:"에서",ok:!1},{text:"를",ok:!1}],explanation:"가 보다 is movement/trying a place, so the destination takes 에. 에서 would mark an action happening at the place."},{kind:"drill",prompt:"You saw a shop get crowded over time. Which sentence fits?",sentence:null,options:[{text:"처음에는 조용하더니 금방 사람이 많아졌어요.",ok:!0},{text:"제가 조용하더니 사람이 많아졌어요.",ok:!1},{text:"조용할 리가 없어요.",ok:!1}],explanation:"-더니 fits the observed change from quiet to crowded. The other choices either misuse the subject or switch to a different grammar."}],canDo:"Contrast before and after with 예전에는 / 요즘은",id:"chapter-36-b8",chapterId:"chapter-36",index:7}]},{id:"chapter-37",number:37,title:"V/A-다고 했어요 · V/A-냐고 물어봤어요",goal:"Report statements with -다고 했어요 and recognize the spoken contraction -대요.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 다고 했어요~",cards:[{kind:"guess",word:{ko:"다고 했어요",romanization:"dago haesseoyo",en:"said that...",pos:"reported-speech ending",nuance:"다고 했어요 reports a statement, not a question or command. Match the inner ending to the sentence type."},sentence:{ko:"선생님이 금요일에 본다고 하셨어요.",en:"The teacher said we will take it on Friday."},target:"다고",options:["said that...","asked whether/if...","whether; what/when/where... inside a sentence"],note:"Reports a statement."},{kind:"guess",word:{ko:"냐고 물어봤어요",romanization:"nyago mureobwasseoyo",en:"asked whether/if...",pos:"reported-question ending",nuance:"냐고 is for reported questions. Do not switch to -다고 just because the whole sentence now ends like a statement."},sentence:{ko:"친구가 몇 시에 만나냐고 물어봤어요.",en:"My friend asked what time we are meeting."},target:"냐고 물어봤어요",options:["asked whether/if...","said that...","to tell someone to..."],note:"Reports a question."},{kind:"guess",word:{ko:"는지",romanization:"neunji",en:"whether; what/when/where... inside a sentence",pos:"embedded-question ending",nuance:"는지 is not reported speech by itself. It embeds a question so verbs like 알다, 모르다, 확인하다, and 궁금하다 can use it."},sentence:{ko:"시험이 언제인지 알아요?",en:"Do you know when the exam is?"},target:"인지",options:["said that...","to tell someone to...","whether; what/when/where... inside a sentence"],note:"Embeds a question inside 알다."},{kind:"guess",word:{ko:"라고 하다",romanization:"rago hada",en:"to tell someone to...",pos:"reported-command ending",nuance:"라고 하다 for instructions is separate from noun +(이)라고 하다, as in 학생이라고 했어요."},sentence:{ko:"선생님이 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework."},target:"라고 하셨",options:["said that...","asked whether/if...","to tell someone to..."],note:"Reports an instruction."},{kind:"guess",word:{ko:"대요",romanization:"daeyo",en:"they say; I heard that",pos:"contracted reported ending",nuance:"대요 is common, but first learn what it expands from so you do not mix statements with questions."},sentence:{ko:"선생님이 시험은 금요일에 본대요.",en:"The teacher says the exam is on Friday."},target:"대요",options:["they say; I heard that","asked whether/if...","whether; what/when/where... inside a sentence"],note:"Spoken contraction of 본다고 해요."},{kind:"payoff",line:{speaker:"지훈",ko:"몇 시에 만나냐고 물어봤어요.",en:"They asked what time we are meeting."},hl:"냐고 물어봤어요"}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b1",chapterId:"chapter-37",index:0},{kind:"pattern",title:"문법 Grammar · V/A-다고 했어요",cards:[{kind:"hunt",name:"V/A-다고 했어요",sub:"Reporting what someone said",lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"내일",mid:"",post:"",hit:!1},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"온",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"친구가 내일 학교에 안 온다고 했어요.",en:"My friend said he won't come to school tomorrow.",romanization:"chinguga naeil hakgyoe an ondago haesseoyo."},{tokens:[{pre:"엄마가",mid:"",post:"",hit:!1},{pre:"밥을",mid:"",post:"",hit:!1},{pre:"다",mid:"",post:"",hit:!1},{pre:"먹었",mid:"다고",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"엄마가 밥을 다 먹었다고 했어요.",en:"Mom said she finished eating.",romanization:"eommaga babeul da meogeottago haesseoyo."}],rule:{name:"V/A-다고 했어요",rows:[{when:"Action verb, present — stem ends in a vowel",add:"-ㄴ다고 했어요",ex:"가다 → 간다고 했어요"},{when:"Action verb, present — stem ends in a 받침",add:"-는다고 했어요",ex:"먹다 → 먹는다고 했어요"},{when:"Adjective, present",add:"-다고 했어요",ex:"바쁘다 → 바쁘다고 했어요 / 좋다 → 좋다고 했어요"},{when:"Any verb/adjective, past",add:"-았/었다고 했어요",ex:"먹었다 → 먹었다고 했어요 / 갔다 → 갔다고 했어요"},{when:"Noun + 이다",add:"N(이)라고 했어요",ex:"학생 → 학생이라고 했어요 / 친구 → 친구라고 했어요"}]},more:{func:'Use -다고 했어요 to report a statement someone made, like English "said that …". You report the meaning, not the exact words, so you drop the original ending (요/-어) and attach -다고 to the plain stem.',funcLead:'Use -다고 했어요 to report a statement someone made, like English "said that …".',keyPoint:{label:"Verbs vs. adjectives in the present",body:"Only action verbs add -ㄴ다고/-는다고 (간다고, 먹는다고). Adjectives, and all past forms, just add -다고 (바쁘다고, 먹었다고). The common slips are 먹다고 (should be 먹는다고) and 바쁜다고 (should be 바쁘다고)."},pronunciation:"In 먹는다고 the ㄱ before ㄴ turns into an ㅇ sound, so it comes out [멍는다고].",pitfall:{wrong:"친구가 학교에 안 오다고 했어요.",right:"친구가 학교에 안 온다고 했어요.",explanation:`In English you just add "that," so it's tempting to glue -다고 onto the dictionary form 오다. But present-tense action verbs need -ㄴ다고/-는다고: 오다 → 온다고.`}}},{kind:"drill",prompt:"The teacher said Korean isn't hard.",sentence:"선생님이 한국어가 안 어렵___.",options:[{text:"이라고 했어요",ok:!1},{text:"다고 했어요",ok:!0}],explanation:"어렵다 is an adjective, so just -다고 — no -ㄴ-/-는-."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My friend said he won't come to school tomorrow." (친구가 시작 · Start with 친구가.)`,tokens:["친구가","내일","학교에","안","온다고","했어요."],correct:"친구가 내일 학교에 안 온다고 했어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Mom said she finished eating."',tokens:["엄마가","밥을","다","먹었다고","했어요."],correct:"엄마가 밥을 다 먹었다고 했어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 학교에 안 오다고 했어요.",ok:!1},{text:"친구가 학교에 안 온다고 했어요.",ok:!0}],explanation:`In English you just add "that," so it's tempting to glue -다고 onto the dictionary form 오다. But present-tense action verbs need -ㄴ다고/-는다고: 오다 → 온다고.`}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b2",chapterId:"chapter-37",index:1},{kind:"words",title:"단어 Words 2 · 물어보다~",cards:[{kind:"guess",word:{ko:"물어보다",romanization:"mureoboda",en:"to ask; to ask and find out",pos:"verb phrase",nuance:"묻다 is the dictionary/base verb. 물어보다 is often the natural spoken choice for asking someone."},sentence:{ko:"친구한테 시험이 언제인지 물어봤어요.",en:"I asked my friend when the exam is."},target:"물어봤",options:["to say again; to repeat","to ask; to ask and find out","said that..."],note:"Everyday spoken verb for asking."},{kind:"guess",word:{ko:"다시 말하다",romanization:"dasi malhada",en:"to say again; to repeat",pos:"verb phrase",nuance:"다시 말하다 is not just the adverb 다시. It is a practical repair phrase when reported information is unclear."},sentence:{ko:"잘 못 들었으면 다시 말해 달라고 해요.",en:"If you did not hear it well, ask them to say it again."},target:"다시 말해",options:["to ask; to ask and find out","said that...","to say again; to repeat"],note:"Useful repair phrase when reported information is unclear."},{kind:"guess",word:{ko:"숙제",romanization:"sukje",en:"homework",pos:"noun",nuance:"숙제 is Sino-Korean 宿題 — 宿 'lodging/stay overnight' + 題 'topic/problem', literally a 'problem to take home overnight', i.e. work a teacher assigns to be done outside class. The verb is locked: Koreans say 숙제를 하다 'do homework', and 숙제를 내다 means a student turns it in (while a teacher 내다 a 숙제 means 'assign/set' it — context decides). Contrast 숙제 with 공부(工夫, 'study') and 과제(課題, 'assignment/coursework'): 공부하다 is the broad act of studying anything, whereas 숙제 is a specific assigned task, and 과제 is the more formal university word for a project or paper. The big English-speaker pitfall is translating 'do my homework' as 숙제를 만들다 'make homework' (✗ — that sounds like you created the assignment) or 숙제를 공부하다 (✗); the only natural pairing is 숙제를 하다."},sentence:{ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"They told us to submit the homework by tomorrow."},target:"숙제",options:["exam","homework","content; details"],note:"Classroom reporting content."},{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"시험이 언제인지 알아요?",en:"Do you know when the exam is?"},target:"시험",options:["exam","homework","content; details"],note:"Natural embedded question noun."},{kind:"guess",word:{ko:"제출하다",romanization:"jechulhada",en:"to submit",pos:"verb",nuance:"제출하다 is Sino-Korean 提出 — 提 'lift/raise up' + 出 'out' — so 'put forward, hand out', i.e. formally submit a document, application, or assignment to an authority. Its register is the key point: 제출하다 is the formal, official word, while everyday speech often just uses 내다 'to put out/hand in' — students say 숙제를 냈어요 casually but write 과제를 제출했습니다 formally. The opposite side of the transaction is 받다 'to receive'/접수하다 'to accept (a submission)'. The English-speaker pitfall: 'submit TO the office' tempts an English-style structure, but the destination simply takes 에 (사무실에 제출하다) and the document is a direct object (서류를 제출하다). As a noun+하다 verb it conjugates on 하다 (제출해요, 제출했어요, formal 제출합니다); negative/impossible split the noun (제출 안 해요, 제출 못 해요). Note pronunciation [제출하다] is straightforward, but watch the polite request form 제출해 주세요."},sentence:{ko:"숙제를 제출했냐고 물어봤어요.",en:"They asked whether I submitted the homework."},target:"제출했",options:["to convey; to pass on","to submit","said that..."],note:"A practical school/work verb for reported questions."},{kind:"payoff",line:{speaker:"지훈",ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework by tomorrow."},hl:"숙제"}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b3",chapterId:"chapter-37",index:2},{kind:"pattern",title:"문법 Grammar · V/A-냐고 물어봤어요",cards:[{kind:"hunt",name:"V/A-냐고 물어봤어요",sub:"Reporting a question",lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"저한테",mid:"",post:"",hit:!1},{pre:"밥",mid:"",post:"",hit:!1},{pre:"먹었",mid:"냐고",post:"",hit:!0},{pre:"",mid:"물어봤어요",post:".",hit:!0}],ko:"친구가 저한테 밥 먹었냐고 물어봤어요.",en:"My friend asked me whether I'd eaten.",romanization:"chinguga jeohante bap meogeonnyago mureobwasseoyo."},{tokens:[{pre:"선생님이",mid:"",post:"",hit:!1},{pre:"학생들한테",mid:"",post:"",hit:!1},{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"냐고",post:"",hit:!0},{pre:"",mid:"물어봤어요",post:".",hit:!0}],ko:"선생님이 학생들한테 시간이 있냐고 물어봤어요.",en:"The teacher asked the students whether they had time.",romanization:"seonsaengnimi haksaengdeulhante sigani innyago mureobwasseoyo."}],rule:{name:"V/A-냐고 물어봤어요",rows:[{when:"Verb or adjective, present",add:"-냐고 물어봤어요",ex:"가다 → 가냐고 / 좋다 → 좋냐고 물어봤어요"},{when:"Any verb/adjective, past",add:"-았/었냐고 물어봤어요",ex:"먹었다 → 먹었냐고 / 갔다 → 갔냐고 물어봤어요"},{when:"Noun + 이다",add:"N(이)냐고 물어봤어요",ex:"학생 → 학생이냐고 / 친구 → 친구냐고 물어봤어요"},{when:"With a question word (누구/언제/어디 …)",add:"keep the question word + -냐고",ex:"어디 가다 → 어디 가냐고 물어봤어요"}]},more:{func:'Use -냐고 물어봤어요 (or 물었어요) to report a question someone asked — "someone asked whether/what …". The reported part ends in -냐고 no matter how polite the original question was.',funcLead:'Use -냐고 물어봤어요 (or 물었어요) to report a question someone asked — "someone asked whether/what …".',keyPoint:{label:"-다고 vs. -냐고",body:"Statements use -다고 했어요; questions use -냐고 물어봤어요. The following verb is your clue: 했어요/말했어요 (said) for statements, 물어봤어요/물었어요 (asked) for questions."},pronunciation:"In 먹었냐고 the ㅆ받침 before ㄴ becomes an ㄴ sound, so it links as [머건냐고].",pitfall:{wrong:"친구가 밥 먹었다고 물어봤어요.",right:"친구가 밥 먹었냐고 물어봤어요.",explanation:"Learners reuse the statement ending -다고 with 물어봤어요. But a reported question has to end in -냐고; -다고 only goes with 했어요/말했어요."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My friend asked me whether I'd eaten." (친구가 시작 · Start with 친구가.)`,tokens:["친구가","저한테","밥","먹었냐고","물어봤어요."],correct:"친구가 저한테 밥 먹었냐고 물어봤어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The teacher asked the students whether they had time." (선생님이 시작 · Start with 선생님이.)',tokens:["선생님이","학생들한테","시간이","있냐고","물어봤어요."],correct:"선생님이 학생들한테 시간이 있냐고 물어봤어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 밥 먹었냐고 물어봤어요.",ok:!0},{text:"친구가 밥 먹었다고 물어봤어요.",ok:!1}],explanation:"Learners reuse the statement ending -다고 with 물어봤어요. But a reported question has to end in -냐고; -다고 only goes with 했어요/말했어요."}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b4",chapterId:"chapter-37",index:3},{kind:"words",title:"단어 Words 3 · 확인하다~",cards:[{kind:"guess",word:{ko:"확인하다",romanization:"hwaginhada",en:"to check",pos:"verb",nuance:"확인하다 (確認하다, 確 'certain/firm' + 認 'recognize') means to check, verify, or confirm that something is correct or true — facts, times, reservations, messages — making sure reality matches what you expect. The crucial contrast is with 찾다, which English 'check' can blur: 찾다 is 'to look FOR / search' something not yet located (열쇠를 찾다, 'look for the keys'), whereas 확인하다 is 'to verify' something you can already see (열쇠가 있는지 확인하다, 'check whether the keys are there'). It also differs from 알아보다 ('look into/inquire to find out', 가격을 알아보다). It's a regular noun+하다 verb: 확인하 + 여요 → 확인해요, past 확인했어요, with 안/못 splitting before 하다 (확인 안 해요, 확인 못 해요). English-speaker pitfall: 'check the box' or 'check off' is NOT 확인하다 — ticking a box is 체크하다/표시하다; and 'check out a book/check out (a hotel)' uses 빌리다 or 체크아웃하다, not 확인하다, which strictly means 'verify/confirm'."},sentence:{ko:"몇 시에 만나는지 확인해 주세요.",en:"Please check what time we are meeting."},target:"확인해",options:["to check","to convey; to pass on","said that..."],note:"Often follows an embedded question."},{kind:"guess",word:{ko:"내용",romanization:"naeyong",en:"content; details",pos:"noun",nuance:"내용 (內容, 內 'inside' + 容 'contain') is the substance or gist inside something — a book, message, lecture, contract — as opposed to its outer form. The sharp contrast is 내용 (what it says) vs 형식 (the form/format): a report can have weak 내용 but proper 형식. Don't confuse it with a physical container either; the box itself is 상자/봉투, while 내용물 specifically means the physical 'contents' (items) inside a package. Typical partners: 내용을 이해하다/정리하다/확인하다, 내용이 어렵다/풍부하다, 회의 내용, 문자 내용. The English-speaker pitfall is particle choice driven by the adjective: 'the content is hard' becomes 내용이 어렵다 ✓, not 내용을 어렵다 ✗ — 를/을 attaches only to action verbs like 이해하다, never to descriptive 어렵다."},sentence:{ko:"메시지 내용을 확인했어요.",en:"I checked the message content."},target:"내용",options:["content; details","homework","exam"],note:"What was said or written."},{kind:"guess",word:{ko:"전하다",romanization:"jeonhada",en:"to convey; to pass on",pos:"verb",nuance:"전하다 (Sino-Korean 傳, 'transmit/hand down') means relaying something from a sender to a receiver: a message, regards, an item, news, or even a feeling, so the receiver takes 에게/한테 or honorific 께 while the thing passed takes 을/를. The nearest rival is 말하다, but 말하다 is you simply saying something yourself, whereas 전하다 stresses that you are the go-between carrying someone else's words or goods to a third party — '사장님이 잘했다고 전하래요' (the boss told me to tell you 'well done'). Everyday set phrases include 안부를 전하다 (send one's regards), 말씀 전해 주세요 (please pass on the message), and 소식을 전하다 (deliver news). The big English-speaker trap is hearing 전 and thinking 전화하다 ('to make a phone call'): they share the 전 syllable but are unrelated, so '전해 주세요' is 'please relay it', not 'please call them'."},sentence:{ko:"제가 친구한테 내용을 전할게요.",en:"I will pass the details on to my friend."},target:"전할",options:["to convey; to pass on","to submit","to check"],note:"The communication job of reported speech."}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b5",chapterId:"chapter-37",index:4},{kind:"pattern",title:"문법 Grammar · V-는지 / A-(으)ㄴ지 / N인지",cards:[{kind:"hunt",name:"V-는지 / A-(으)ㄴ지 / N인지",sub:'"whether / what / where …" inside a sentence',lines:[{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"어디",mid:"",post:"",hit:!1},{pre:"사",mid:"는지",post:"",hit:!0},{pre:"몰라요.",mid:"",post:"",hit:!1}],ko:"친구가 어디 사는지 몰라요.",en:"I don't know where my friend lives.",romanization:"chinguga eodi saneunji mollayo."},{tokens:[{pre:"저",mid:"",post:"",hit:!1},{pre:"사람이",mid:"",post:"",hit:!1},{pre:"누구",mid:"인지",post:"",hit:!0},{pre:"아세요?",mid:"",post:"",hit:!1}],ko:"저 사람이 누구인지 아세요?",en:"Do you know who that person is?",romanization:"jeo sarami nuguinji aseyo?"}],rule:{name:"V-는지 / A-(으)ㄴ지 / N인지",rows:[{when:"Action verb, present",add:"-는지",ex:"가다 → 가는지 / 먹다 → 먹는지 모르겠어요"},{when:"Adjective, present",add:"-(으)ㄴ지",ex:"좋다 → 좋은지 / 바쁘다 → 바쁜지 모르겠어요"},{when:"Any verb/adjective, past",add:"-았/었는지",ex:"먹었다 → 먹었는지 / 갔다 → 갔는지 모르겠어요"},{when:"Noun + 이다",add:"N인지",ex:"학생 → 학생인지 / 누구 → 누구인지 모르겠어요"}]},more:{func:`Use -는지/-(으)ㄴ지/-인지 to tuck a question inside a bigger sentence — "I don't know whether/what/where …", "Do you know if …?". It turns the question into a clause that then connects to verbs like 알다, 모르다, 궁금하다.`,funcLead:`Use -는지/-(으)ㄴ지/-인지 to tuck a question inside a bigger sentence — "I don't know whether/what/where …", "Do you know if …?".`,keyPoint:{label:"Adjective -(으)ㄴ지 vs. verb -는지",body:"In the present, adjectives take -(으)ㄴ지 (좋은지, 바쁜지) and action verbs take -는지 (가는지, 먹는지). In the past, both use -았/었는지 (좋았는지, 갔는지), so the split only matters in the present."},pronunciation:"먹는지 comes out [멍는지] (ㄱ → ㅇ before ㄴ); in 좋은지 the ㅎ drops, so it sounds like [조은지].",pitfall:{wrong:"이 영화가 재미있은지 궁금해요.",right:"이 영화가 재미있는지 궁금해요.",explanation:"재미있다/맛있다/없다 look like adjectives, but the 있/없 part acts like a verb and takes -는지, not -(으)ㄴ지. So it's 재미있는지, 맛있는지, 없는지."}}},{kind:"drill",prompt:"I wonder whether this movie is good.",sentence:"이 영화가 재미있___ 궁금해요.",options:[{text:"는지",ok:!0},{text:"인지",ok:!1}],explanation:"재미있다 takes -는지 (not -(으)ㄴ지) because of the 있다 part."},{kind:"drill",prompt:"I'm not sure whether he finished eating.",sentence:"밥을 다 먹었___ 모르겠어요.",options:[{text:"는지",ok:!0},{text:"인지",ok:!1}],explanation:`Past → -었는지. 모르겠어요 sounds softer than 몰라요, more like "I'm not sure."`},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't know where my friend lives."`,tokens:["친구가","어디","사는지","몰라요."],correct:"친구가 어디 사는지 몰라요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Do you know who that person is?"',tokens:["저","사람이","누구인지","아세요?"],correct:"저 사람이 누구인지 아세요?",explanation:""}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b6",chapterId:"chapter-37",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A classmate passes along what the teacher said after class.",lines:[{speaker:"민서",ko:"선생님이 뭐라고 하셨어요?",en:"What did the teacher say?",romanization:"seonsaengnimi mworago hasyeosseoyo?"},{speaker:"지훈",ko:"내일까지 숙제를 제출하라고 하셨어요.",en:"The teacher told us to submit the homework by tomorrow.",romanization:"naeilkkaji sukjereul jechulharago hasyeosseoyo."},{speaker:"민서",ko:"시험이 언제인지도 말씀하셨어요?",en:"Did the teacher also say when the exam is?",romanization:"siheomi eonjeinjido malsseumhasyeosseoyo?"},{speaker:"지훈",ko:"네, 금요일에 본다고 하셨어요.",en:"Yes, the teacher said we will take it on Friday.",romanization:"ne, geumyoire bondago hasyeosseoyo."},{speaker:"민서",ko:"친구는 뭐라고 물어봤어요?",en:"What did your friend ask?",romanization:"chinguneun mworago mureobwasseoyo?"},{speaker:"지훈",ko:"몇 시에 만나냐고 물어봤어요.",en:"They asked what time we are meeting.",romanization:"myeot sie mannanyago mureobwasseoyo."}]},{kind:"order",prompt:"Build: 'My friend asked what time we meet.'",tokens:["친구가","몇 시에 만나냐고","물어봤어요"],correct:"친구가 몇 시에 만나냐고 물어봤어요",explanation:"Reported questions use -냐고 물어봤어요. The embedded question keeps 몇 시에 inside the reported content."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"내일까지 숙제를 제출하라고 하셨어요.",options:[{text:"민서",ok:!1},{text:"지훈",ok:!0}],explanation:"The teacher told us to submit the homework by tomorrow."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Did the teacher also say when the exam is?"',sentence:"___이 언제인지도 말씀하셨어요?",options:[{text:"숙제",ok:!1},{text:"내용",ok:!1},{text:"시험",ok:!0}],explanation:""}],canDo:"Pass along what someone said with -다고 했어요 (어렵다고 했어요)",id:"chapter-37-b7",chapterId:"chapter-37",index:6},{kind:"reading",title:"읽기 Reading · 선생님이 뭐라고 하셨어요?",cards:[{kind:"read",title:"선생님이 뭐라고 하셨어요?",chunks:["수업이 끝난 뒤 친구에게 내용을 전할 때는 원래 문장이 어떤 종류였는지 먼저 봐야 해요. 선생님이 '금요일에 시험을 봐요'라고 말한 내용은 '금요일에 본다고 하셨어요'로 전할 수 있어요. 질문을 전할 때는 '-냐고'를 써요.","그래서 '몇 시에 만나요?'는 '몇 시에 만나냐고 물어봤어요'가 돼요. 하지만 누가 질문한 것이 아니라 내가 답을 알고 싶은 상황이면 '-는지'가 자연스러워요. '시험이 언제인지 알아요?'처럼 큰 문장 안에 질문을 넣는 거예요."],translation:"When passing along class information, first identify the original sentence type. Statements use -다고 했어요, questions use -냐고 물어봤어요, and embedded questions use -는지 inside verbs like know, not know, or check.",qas:[{q:"원래 문장이 statement이면 어떤 표현을 써요?",a:"-다고 했어요를 써요."},{q:"질문을 전할 때는 어떤 표현을 써요?",a:"-냐고 물어봤어요를 써요."},{q:"큰 문장 안에 질문을 넣을 때는 어떤 표현을 써요?",a:"-는지를 써요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"수업이 끝난 뒤 친구에게 내용을 전할 때는 원래 문장이 어떤 종류였___ 먼저 봐야 해요.",options:[{text:"는지",ok:!0},{text:"다고 했어요",ok:!1},{text:"라고 하다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"선생님이 '금요일에 ___을 봐요'라고 말한 내용은 '금요일에 본다고 하셨어요'로 전할 수 있어요.",options:[{text:"숙제",ok:!1},{text:"다고 했어요",ok:!1},{text:"시험",ok:!0}],explanation:""}],canDo:"Relay an order with -(으)라고 하다 (제출하라고 했어요)",id:"chapter-37-b8",chapterId:"chapter-37",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"The teacher said, '금요일에 시험을 봐요.' Which report is correct?",sentence:null,options:[{text:"금요일에 본다고 하셨어요.",ok:!0},{text:"금요일에 보냐고 하셨어요.",ok:!1},{text:"금요일에 보라고 하셨어요.",ok:!1}],explanation:"The original is a statement, so use -다고 하셨어요."},{kind:"drill",prompt:"Your friend asked, '몇 시에 만나요?' Which report is correct?",sentence:null,options:[{text:"몇 시에 만나냐고 물어봤어요.",ok:!0},{text:"몇 시에 만난다고 물어봤어요.",ok:!1},{text:"몇 시에 만나라고 물어봤어요.",ok:!1}],explanation:"The original is a question, so use -냐고 물어봤어요."},{kind:"drill",prompt:"Choose the embedded question form.",sentence:null,options:[{text:"시험이 언제인지 알아요?",ok:!0},{text:"시험이 언제냐고 알아요?",ok:!1},{text:"시험이 언제라고 알아요?",ok:!1}],explanation:"알다 takes the embedded question form -는지/-인지."},{kind:"drill",prompt:"선생님___ 숙제를 제출하라고 하셨어요. (The teacher told us to submit homework.)",sentence:null,options:[{text:"께서",ok:!0},{text:"께",ok:!1},{text:"를",ok:!1}],explanation:"선생님 is the respected subject who gave the instruction, so use 께서. 께 would mark a recipient instead."},{kind:"drill",prompt:"Which is the spoken short form of 선생님이 내일 시험이 있다고 했어요?",sentence:null,options:[{text:"내일 시험이 있대요.",ok:!0},{text:"내일 시험이 있냐고요.",ok:!1},{text:"내일 시험이 있으라고요.",ok:!1}],explanation:"-대요 is the common spoken contraction for “they say that.” 있냐고요 would report or repeat a question."}],canDo:"Report a question someone asked with -냐고 물어봤어요",id:"chapter-37-b9",chapterId:"chapter-37",index:8}]},{id:"chapter-38",number:38,title:"Stacked Noun Modifiers: Packing a Clause Before a Noun · Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",goal:"Unpack long noun phrases such as 어제 올라온 공지 and 변경된 일정.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 올라온 공지~",cards:[{kind:"guess",word:{ko:"올라온 공지",romanization:"ollaon gongji",en:"a notice that was posted",pos:"noun phrase",nuance:"올라온 is not a separate full sentence here. It sits before 공지 and tells you which notice."},sentence:{ko:"어제 올라온 공지를 확인했어요.",en:"I checked the notice that was posted yesterday."},target:"올라온 공지",options:["a notice that was posted","to be read / to make someone read","to be seen / to be visible"],note:"A compact noun phrase: 올라온 tells you which 공지."},{kind:"guess",word:{ko:"변경된 일정",romanization:"byeongyeongdoen iljeong",en:"a changed schedule",pos:"noun phrase",nuance:"변경된 focuses on the resulting state. It sounds natural in notices, emails, and announcements."},sentence:{ko:"변경된 일정이 공지에 나왔어요.",en:"The changed schedule appeared in the notice."},target:"변경된 일정",options:["a changed schedule","to be read / to make someone read","to be seen / to be visible"],note:"변경된 focuses on the resulting state."},{kind:"guess",word:{ko:"제출할 보고서",romanization:"jechulhal bogoseo",en:"a report to submit",pos:"noun phrase",nuance:"제출할 points forward. It differs from 제출한 보고서, a report that was already submitted."},sentence:{ko:"내일 제출할 보고서를 다시 검토했어요.",en:"I reviewed the report I will submit tomorrow."},target:"제출할 보고서",options:["to be read / to make someone read","a report to submit","to be seen / to be visible"],note:"제출할 marks a future action attached to 보고서."},{kind:"guess",word:{ko:"읽히다",romanization:"ilkida",en:"to be read / to make someone read",pos:"verb",nuance:"With texts, 읽히다 often describes how easily something is read or understood."},sentence:{ko:"이 책은 초급 수업에서 자주 읽혀요.",en:"This book is often read in beginner classes."},target:"읽혀",options:["to be read / to make someone read","to be seen / to be visible","to be sold"],note:"Passive reading: the book is the subject."},{kind:"guess",word:{ko:"보이다",romanization:"boida",en:"to be seen / to be visible",pos:"verb",nuance:"보이다 is the passive/spontaneous counterpart of 보다 (to look): something enters your field of vision on its own, so the thing seen takes 이/가 (산이 보여요 = 'the mountain is visible'), NOT 을/를. The 요-form contracts 보이-+-어요 → 보여요 (past 보였어요). The sharp contrast learners need is 보이다 vs 보다: 보다 is an active choice ('I look at / watch'), 보이다 is involuntary ('it is seen / comes into view'). A second, very frequent meaning is 'to look/seem' — adjective stem + 보이다 (행복해 보여요 'you look happy'; 비싸 보여요 'it looks expensive'); here English 'looks' maps cleanly. With 주다 it flips to active 'show' (보여 주다). The English-speaker pitfall: saying 산을 보여요 to mean 'I see the mountain' — that is wrong; use 산이 보여요 (it is visible) or 산을 봐요 (I look at it)."},sentence:{ko:"멀리서 바다가 보여요.",en:"The sea is visible from far away."},target:"보여",options:["to be read / to make someone read","to be sold","to be seen / to be visible"],note:"The thing visible becomes the subject."},{kind:"payoff",line:{speaker:"민서",ko:"어제 올라온 공지 봤어요?",en:"Did you see the notice posted yesterday?"},hl:"올라온 공지"}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b1",chapterId:"chapter-38",index:0},{kind:"pattern",title:"문법 Grammar · Stacked Noun Modifiers: Packing a Clause Before a Noun",cards:[{kind:"teach",name:"Stacked Noun Modifiers: Packing a Clause Before a Noun",sub:"",rows:[{when:"Past action (verb)",add:"-(으)ㄴ",ex:"읽다 → 읽은 (책) / 주다 → 친구가 준 (선물)"},{when:"Present / ongoing (verb)",add:"-는",ex:"먹다 → 먹는 (사람) / 보다 → 내가 보는 (영화)"},{when:"Future / not-yet (verb)",add:"-(으)ㄹ",ex:"가다 → 갈 (곳) / 만나다 → 내일 만날 (친구)"},{when:"Adjective describing a noun",add:"-(으)ㄴ",ex:"예쁘다 → 예쁜 (꽃) / 비싸다 → 비싼 (가방)"}],examples:[{ko:"어제 친구가 준 책을 다 읽었어요.",en:"I finished reading the book my friend gave me yesterday.",romanization:"eoje chinguga jun chaegeul da ilgeosseoyo.",note:'준 (past modifier of 주다) packs "my friend gave" in front of 책.'},{ko:"제가 자주 가는 카페가 문을 닫았어요.",en:"The cafe I often go to closed down.",romanization:"jega jaju ganeun kapega muneul dadasseoyo.",note:"가는 (present modifier of 가다) shows an ongoing, habitual action before 카페. 문을 닫다 = to close down."}],more:{func:'In Korean a whole clause can describe a noun, but it always comes BEFORE the noun, and the verb changes into a modifier form ending in -ㄴ/-은/-는/-(으)ㄹ. So "the book my friend gave me yesterday" becomes 어제 친구가 준 책 — everything piles up in front of 책.',funcLead:"In Korean a whole clause can describe a noun, but it always comes BEFORE the noun, and the verb changes into a modifier form ending in -ㄴ/-은/-는/-(으)ㄹ.",keyPoint:{label:"Past vs. present vs. future modifier",body:"The modifier ending carries the TIME, so the final verb of the sentence can stay simple: 친구가 준 책 (already gave), 친구가 주는 책 (is giving), 친구가 줄 책 (will give). Pick the wrong one and the meaning of the whole noun phrase changes."},pronunciation:"읽은 sounds like [일근] — the ㄺ cluster splits and ㄱ links to 은. 많아요 sounds like [마나요], with the ㅎ in ㄶ dropping out.",pitfall:{wrong:"책 친구가 어제 준",right:"어제 친구가 준 책",explanation:'English puts the describing clause AFTER the noun ("the book that my friend gave"), so learners often leave 책 first. In Korean the whole clause comes before the noun, and the verb must take a modifier ending — never a sentence-ending form like 줬어요 right in front of the noun.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I finished reading the book my friend gave me yesterday."',tokens:["어제","친구가","준","책을","다","읽었어요."],correct:"어제 친구가 준 책을 다 읽었어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The cafe I often go to closed down."',tokens:["제가","자주","가는","카페가","문을","닫았어요."],correct:"제가 자주 가는 카페가 문을 닫았어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"책 친구가 어제 준",ok:!1},{text:"어제 친구가 준 책",ok:!0}],explanation:'English puts the describing clause AFTER the noun ("the book that my friend gave"), so learners often leave 책 first. In Korean the whole clause comes before the noun, and the verb must take a modifier ending — never a sentence-ending form like 줬어요 right in front of the noun.'}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b2",chapterId:"chapter-38",index:1},{kind:"words",title:"단어 Words 2 · 팔리다~",cards:[{kind:"guess",word:{ko:"팔리다",romanization:"pallida",en:"to be sold",pos:"verb",nuance:"Use 팔리다 when the seller is not important or not known."},sentence:{ko:"인기 상품이 하루 만에 다 팔렸어요.",en:"The popular item sold out in one day."},target:"팔렸",options:["to be read / to make someone read","to be sold","to be seen / to be visible"],note:"The product is the subject; the seller is not important."},{kind:"guess",word:{ko:"잡히다",romanization:"japida",en:"to be caught / to be set",pos:"verb",nuance:"잡히다 is natural for appointments, schedules, reservations, and plans."},sentence:{ko:"회의 일정이 다음 주로 잡혔어요.",en:"The meeting schedule was set for next week."},target:"잡혔",options:["to be caught / to be set","to be read / to make someone read","to be seen / to be visible"],note:"For schedules, 잡히다 means it has been fixed/set."},{kind:"guess",word:{ko:"닫히다",romanization:"datida",en:"to be closed",pos:"verb",nuance:"Use 닫히다 when you care about the closed state/result more than the person closing it."},sentence:{ko:"문이 자동으로 닫혔어요.",en:"The door closed automatically."},target:"닫혔",options:["to be closed","to be read / to make someone read","to be seen / to be visible"],note:"The door is the subject; the closing result is highlighted."},{kind:"guess",word:{ko:"먹이다",romanization:"meogida",en:"to feed / make someone eat",pos:"verb",nuance:"The subject is the causer, not the person eating."},sentence:{ko:"엄마가 아이에게 약을 먹였어요.",en:"The mother made the child take medicine."},target:"먹였",options:["to be seen / to be visible","to be sold","to feed / make someone eat"],note:"Causative: someone causes another person to eat/take something."},{kind:"guess",word:{ko:"앉히다",romanization:"anjhida",en:"to seat someone",pos:"verb",nuance:"앉다 is what the person does; 앉히다 is what someone else does to seat them."},sentence:{ko:"직원이 손님을 창가 자리에 앉혔어요.",en:"The employee seated the guest by the window."},target:"앉혔",options:["to seat someone","to be seen / to be visible","to be sold"],note:"Causative: someone makes/lets another person sit."}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b3",chapterId:"chapter-38",index:2},{kind:"pattern",title:"문법 Grammar · Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",cards:[{kind:"teach",name:"Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",sub:"",rows:[{when:"add -이-",add:"보다→보이다, 놓다→놓이다, 쌓다→쌓이다",ex:"산이 보여요. (You can see the mountain.)"},{when:"add -히-",add:"닫다→닫히다, 막다→막히다, 잡다→잡히다",ex:"문이 닫혔어요. (The door got closed.)"},{when:"add -리-",add:"열다→열리다, 듣다→들리다, 팔다→팔리다",ex:"음악이 들려요. (You can hear music.)"},{when:"add -기-",add:"끊다→끊기다, 쫓다→쫓기다, 안다→안기다",ex:"전화가 끊겼어요. (The call got cut off.)"}],examples:[{ko:"문이 갑자기 닫혔어요.",en:"The door suddenly closed.",romanization:"muni gapjagi dachyeosseoyo.",note:"닫히다 (passive of 닫다) — nobody is named as the one closing it; we just see the result."},{ko:"여기에서 바다가 잘 보여요.",en:"You can see the sea well from here.",romanization:"yeogieseo badaga jal boyeoyo.",note:'보이다 (passive of 보다) means "is visible," focusing on what shows up, not who looks.'}],more:{func:"Passive verbs describe what HAPPENS to something without saying who did it — the focus moves to the result or the affected thing. You build them by adding -이-, -히-, -리-, or -기- inside certain action verbs: 열다 (to open) → 열리다 (to be opened / to open on its own).",funcLead:"Passive verbs describe what HAPPENS to something without saying who did it — the focus moves to the result or the affected thing.",keyPoint:{label:"Active vs. passive subject marking",body:"In an active sentence the doer takes 이/가 and the thing takes 을/를: 제가 문을 열었어요. In the passive, the affected thing becomes the 이/가 subject and the doer usually drops out: 문이 열렸어요. If you do keep the doer, it takes 에 or 한테/에게: 문이 바람에 열렸어요 (The door opened from the wind)."},pronunciation:"닫히다 sounds like [다치다] — ㄷ and ㅎ blend into ㅊ. 막히다 sounds like [마키다], where ㄱ and ㅎ blend into ㅋ.",pitfall:{wrong:"문이 닫아졌어요 (over-using -아/어지다 for everything)",right:"문이 닫혔어요",explanation:`English has one passive ("be + past participle"), so learners reach for -아/어지다 every time. But verbs in the 이/히/리/기 group already have their own passive form, and that is the natural choice. Save -아/어지다 mainly for verbs that don't have such a form.`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The door suddenly closed."',tokens:["문이","갑자기","닫혔어요."],correct:"문이 갑자기 닫혔어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "You can see the sea well from here." (여기에서 시작 · Start with 여기에서.)',tokens:["여기에서","바다가","잘","보여요."],correct:"여기에서 바다가 잘 보여요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"문이 닫아졌어요 (over-using -아/어지다 for everything)",ok:!1},{text:"문이 닫혔어요",ok:!0}],explanation:`English has one passive ("be + past participle"), so learners reach for -아/어지다 every time. But verbs in the 이/히/리/기 group already have their own passive form, and that is the natural choice. Save -아/어지다 mainly for verbs that don't have such a form.`}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b4",chapterId:"chapter-38",index:3},{kind:"words",title:"단어 Words 3 · 입히다~",cards:[{kind:"guess",word:{ko:"입히다",romanization:"ipida",en:"to dress someone / put clothes on someone",pos:"verb",nuance:"입다 is wear; 입히다 is dress someone else."},sentence:{ko:"아버지가 아기에게 코트를 입혔어요.",en:"The father put a coat on the baby."},target:"입혔",options:["to be seen / to be visible","to be sold","to dress someone / put clothes on someone"],note:"Causative pair with 입다."},{kind:"guess",word:{ko:"알리다",romanization:"allida",en:"to inform / let know",pos:"verb",nuance:"알리다 is the causative of 알다 ('to know'), so literally 'to make (someone) know' — you give a piece of information to a person, who takes 에게/한테, while the fact taught takes 을/를. The form you will reach for ten times a day is 알려 주세요 ('please let me know'), used to ask for an address, a time, a price, or any update. The near-synonym 가르치다 also means 'let know', but 가르치다 leans toward teaching a skill or directions ('역으로 가는 길 좀 가르쳐 주세요'), while 알리다 is just transmitting a fact ('결과를 알려 주세요'). The classic learner error is using plain 알다: 알아요 means 'I know' (a state), and you cannot make a request with it — you must use the causative 알려 주세요 to mean 'inform me'. Beyond person-to-person, 알리다 also covers public announcing — '진실을 세상에 알리다' (reveal the truth to the world)."},sentence:{ko:"안내 문자가 변경 사항을 알려 줬어요.",en:"The 안내 text message informed me of the changes."},target:"알려",options:["to be read / to make someone read","to be seen / to be visible","to inform / let know"],note:"Causative-like lexical verb: make information known."},{kind:"guess",word:{ko:"문장",romanization:"munjang",en:"sentence",pos:"noun",nuance:"문장(文章)은 '글월 문 + 글 장'으로, 주어와 서술어를 갖춰 생각을 완결되게 표현하는 한 덩어리의 말이에요. 비슷해 보이는 '글'은 문장이 여러 개 모인 더 큰 글덩이(에세이·기사 전체)를 뜻하고, '문구'는 짧은 어구나 문장 한 토막을 가리켜서 범위가 달라요. 또 '단어/낱말'은 더 작은 단위라, 낱말 하나만으로는 '문장'이 되지 않아요. 영어 화자는 sentence를 무조건 '문장'으로 옮기지만, 표지판의 'No smoking' 같은 짧은 문구는 한국어로 '문구'가 더 자연스러울 때가 있어요. 또 sentence에 '형(刑)을 선고하다'라는 뜻도 있는데 그건 한국어 '문장'과 전혀 무관하니 직역하면 안 돼요. '문장을 만들다/짓다/외우다/읽다'와 잘 어울립니다."},sentence:{ko:"긴 문장은 먼저 명사구를 찾아서 읽어요.",en:"For long sentences, first find the noun phrases."},target:"문장",options:["news article / report","sentence","a notice that was posted"],note:"This chapter is about unpacking compressed sentence structure."},{kind:"guess",word:{ko:"기사",romanization:"gisa",en:"news article / report",pos:"noun",nuance:"기사 (記事, 記 'record/write down' + 事 'matter, event') means a news article or report — a single written piece of journalism in a newspaper, magazine, or online; the hanja literally means 'a written record of an event'. Distinguish it carefully from neighbors: 언론 is the press as an institution, 보도 (報道) is the ACT of reporting, and 기사 is the concrete written unit of content that results. A crucial English-speaker pitfall is the homonym trap: 기사 is also a completely separate word meaning 'driver' (司機/운전기사) — and historically 'knight' (騎士) — so 택시 기사 is 'taxi driver', not 'taxi article'; only context tells which 기사 is meant. Natural collocations: 기사를 쓰다, 기사가 나다, 신문 기사, 기사를 검색하다. Don't reach for 기사 when you mean the abstract media institution — that is 언론."},sentence:{ko:"기사에는 변경된 일정과 새 규칙이 함께 나왔어요.",en:"The article included the changed schedule and the new rule together."},target:"기사",options:["sentence","a notice that was posted","news article / report"],note:"News prose often uses noun modification and passive/result forms."},{kind:"payoff",line:{speaker:"지훈",ko:"저는 그 문장이 처음에 잘 안 읽혔어요.",en:"At first, that sentence did not read clearly to me."},hl:"문장"}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b5",chapterId:"chapter-38",index:4},{kind:"pattern",title:"문법 Grammar · Causative Verbs (이/히/리/기/우): Making or Helping Someone Do Something",cards:[{kind:"teach",name:"Causative Verbs (이/히/리/기/우): Making or Helping Someone Do Something",sub:"",rows:[{when:"add -이-",add:"먹다→먹이다, 보다→보이다, 죽다→죽이다",ex:"아기에게 밥을 먹여요. (I feed the baby rice.)"},{when:"add -히-",add:"입다→입히다, 앉다→앉히다, 읽다→읽히다",ex:"아이에게 옷을 입혀요. (I dress the child.)"},{when:"add -리-",add:"울다→울리다, 살다→살리다, 알다→알리다",ex:"동생을 울렸어요. (I made my sibling cry.)"},{when:"add -기-/-우-",add:"웃다→웃기다, 자다→재우다, 타다→태우다",ex:"아기를 재웠어요. (I put the baby to sleep.)"}],examples:[{ko:"엄마가 아기에게 밥을 먹여요.",en:"The mom feeds the baby rice.",romanization:"eommaga agiege babeul meogyeoyo.",note:"먹이다 (causative of 먹다) = make the baby eat; the eater takes 에게/한테."},{ko:"아이에게 따뜻한 옷을 입혔어요.",en:"I dressed the child in warm clothes.",romanization:"aiege ttatteutan oseul iphyeosseoyo.",note:"입히다 (causative of 입다) — the parent makes the child wear the clothes."}],more:{func:"Causative verbs say that the subject CAUSES another person or thing to do or undergo the action. You build them by adding -이-, -히-, -리-, -기-, or -우- inside the verb: 먹다 (to eat) → 먹이다 (to feed = make someone eat).",funcLead:"Causative verbs say that the subject CAUSES another person or thing to do or undergo the action.",keyPoint:{label:"Causative vs. plain verb — who acts",body:"Plain 자다 means the subject sleeps (아기가 자요 = the baby sleeps). Causative 재우다 means the subject makes someone else sleep (엄마가 아기를 재워요 = Mom puts the baby to sleep). The original doer (the baby) moves from the 이/가 subject to a 을/를 (or 에게) slot — the new subject is the cause."},pronunciation:"입히다 sounds like [이피다] — ㅂ and ㅎ blend into ㅍ. 읽히다 sounds like [일키다], where the ㄱ in the ㄺ cluster joins ㅎ to make ㅋ.",pitfall:{wrong:"엄마가 아기를 먹게 해요 (always using -게 하다)",right:"엄마가 아기에게 밥을 먹여요",explanation:'English forces "make/let someone do" with a separate verb, so learners default to -게 하다 for everything. When a verb HAS a built-in causative (먹이다, 입히다, 재우다), that one-word form sounds far more natural for concrete, physical actions like feeding, dressing, and putting to sleep.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The mom feeds the baby rice." (엄마가 시작 · Start with 엄마가.)',tokens:["엄마가","아기에게","밥을","먹여요."],correct:"엄마가 아기에게 밥을 먹여요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I dressed the child in warm clothes." (아이에게 시작 · Start with 아이에게.)',tokens:["아이에게","따뜻한","옷을","입혔어요."],correct:"아이에게 따뜻한 옷을 입혔어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"엄마가 아기에게 밥을 먹여요",ok:!0},{text:"엄마가 아기를 먹게 해요 (always using -게 하다)",ok:!1}],explanation:'English forces "make/let someone do" with a separate verb, so learners default to -게 하다 for everything. When a verb HAS a built-in causative (먹이다, 입히다, 재우다), that one-word form sounds far more natural for concrete, physical actions like feeding, dressing, and putting to sleep.'}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b6",chapterId:"chapter-38",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Minseo reads a school portal notice and explains the changed presentation schedule to Jihoon.",lines:[{speaker:"민서",ko:"어제 올라온 공지 봤어요?",en:"Did you see the notice posted yesterday?",romanization:"eoje ollaon gongji bwasseoyo?"},{speaker:"지훈",ko:"네, 발표 시간이 다음 주로 잡혔더라고요.",en:"Yes, the presentation time was set for next week.",romanization:"ne, balpyo sigani daeum juro japhyeotdeoragoyo."},{speaker:"민서",ko:"변경된 일정이 표 아래에 작게 쓰여 있었어요.",en:"The changed schedule was written in small print below the table.",romanization:"byeongyeongdoen iljeongi pyo araee jakge sseuyeo isseosseoyo."},{speaker:"지훈",ko:"저는 그 문장이 처음에 잘 안 읽혔어요.",en:"At first, that sentence did not read clearly to me.",romanization:"jeoneun geu munjangi cheoeume jal an ilkhyeosseoyo."},{speaker:"민서",ko:"담당자가 학생들을 앞자리에 앉힌다는 내용도 있었어요.",en:"It also said the staff would seat students in the front rows.",romanization:"damdangjaga haksaengdeureul apjarie anjhindaneun naeyongdo isseosseoyo."},{speaker:"지훈",ko:"이런 공지는 누가 했는지보다 뭐가 바뀌었는지가 중요하네요.",en:"For notices like this, what changed matters more than who did it.",romanization:"ireon gongjineun nuga haenneunjiboda mwoga bakkwieonneunjiga jungyohaneyo."}]},{kind:"order",prompt:"Build: 'the schedule changed today' as a noun phrase",tokens:["오늘","변경된","일정"],correct:"오늘 변경된 일정",explanation:"Korean packs the description before the noun. 변경된 comes before 일정 to make one noun phrase."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"이런 공지는 누가 했는지보다 뭐가 바뀌었는지가 중요하네요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"For notices like this, what changed matters more than who did it."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Did you see the notice posted yesterday?"',sentence:"어제 ___ 봤어요?",options:[{text:"올라온 공지",ok:!0},{text:"읽히다",ok:!1},{text:"보이다",ok:!1}],explanation:""}],canDo:"Pack a whole clause before a noun to describe it (어제 올라온 공지, 변경된 일정)",id:"chapter-38-b7",chapterId:"chapter-38",index:6},{kind:"reading",title:"읽기 Reading · 어제 올라온 공지에서 변경된 일정 보기",cards:[{kind:"read",title:"어제 올라온 공지에서 변경된 일정 보기",chunks:["학교나 회사 공지는 짧아 보여도 정보가 압축되어 있는 경우가 많아요. '어제 올라온 공지'는 '공지가 어제 올라왔어요'라는 문장을 명사 앞에 붙인 표현이고, '변경된 일정'은 이미 바뀐 결과를 일정 앞에 붙인 표현이에요. 이런 문장을 읽을 때는 끝에 있는 명사를 먼저 찾으세요.","공지인지, 일정인지, 문장인지, 내용인지 확인한 다음 앞에 붙은 말을 풀어 보면 훨씬 잘 읽혀요. 또 '발표 시간이 다음 주로 잡혔어요'처럼 피동형이 쓰이면 누가 정했는지보다 결과가 중요하다는 뜻으로 읽으면 됩니다."],translation:"Notices often compress information into noun phrases. First find the final noun, then unpack the words before it. Passive/result forms like 잡히다 focus on the result, not on who caused it.",qas:[{q:"긴 명사구를 읽을 때 무엇을 먼저 찾아야 해요?",a:"끝에 있는 명사를 먼저 찾아야 해요."},{q:"변경된 일정은 어떤 뜻이에요?",a:"이미 바뀐 일정이라는 뜻이에요."},{q:"잡혔어요 같은 피동형은 무엇을 더 강조해요?",a:"누가 했는지보다 결과를 더 강조해요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"'어제 ___'는 '공지가 어제 올라왔어요'라는 문장을 명사 앞에 붙인 표현이고, '변경된 일정'은 이미 바뀐 결과를 일정 앞에 붙인 표현이에요.",options:[{text:"읽히다",ok:!1},{text:"보이다",ok:!1},{text:"올라온 공지",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"이런 ___을 읽을 때는 끝에 있는 명사를 먼저 찾으세요.",options:[{text:"문장",ok:!0},{text:"기사",ok:!1},{text:"제출할 보고서",ok:!1}],explanation:""}],canDo:"Describe what happens to something with passive verbs (바뀌다, 닫히다, 팔리다)",id:"chapter-38-b8",chapterId:"chapter-38",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which phrase means “the notice posted yesterday”?",sentence:null,options:[{text:"어제 올라온 공지",ok:!0},{text:"어제 올리는 공지",ok:!1},{text:"어제 올라갈 공지",ok:!1}],explanation:"올라온 is a completed-action modifier attached to 공지."},{kind:"drill",prompt:"Which sentence focuses on the schedule being set, not who set it?",sentence:null,options:[{text:"발표 시간이 다음 주로 잡혔어요.",ok:!0},{text:"발표 시간이 다음 주를 잡았어요.",ok:!1},{text:"발표 시간을 다음 주가 잡았어요.",ok:!1}],explanation:"잡히다 makes the schedule the subject and highlights the result."},{kind:"drill",prompt:"Which sentence uses a causative verb naturally?",sentence:null,options:[{text:"직원이 손님을 창가 자리에 앉혔어요.",ok:!0},{text:"직원이 손님이 창가 자리에 앉았어요.",ok:!1},{text:"직원이 손님을 창가 자리에 앉았어요.",ok:!1}],explanation:"앉히다 means someone causes another person to sit."},{kind:"drill",prompt:"공지___ 올라왔어요. (The notice was posted.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"올라오다 describes the notice appearing or being posted, so 공지 is the subject. 를 would make it an object of someone else’s action."},{kind:"drill",prompt:"Which sentence uses a causative verb naturally?",sentence:null,options:[{text:"직원이 손님을 자리에 앉혔어요.",ok:!0},{text:"손님이 자리에 앉혔어요.",ok:!1},{text:"자리가 손님을 앉았어요.",ok:!1}],explanation:"앉히다 means to seat someone or make/help someone sit. 손님 is the person being seated."}],canDo:"Say someone makes/lets another do something with causatives (알리다, 먹이다)",id:"chapter-38-b9",chapterId:"chapter-38",index:8}]},{id:"chapter-39",number:39,title:"V-(으)ㄹ 수밖에 없다 · V-(으)ㄹ 리가 없다",goal:"Use -(으)ㄹ 수밖에 없다 for a no-choice situation.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 수밖에 없다~",cards:[{kind:"guess",word:{ko:"수밖에 없다",romanization:"subakke eopda",en:"to have no choice but to",pos:"bound expression",nuance:"수밖에 없다 is resignation to the only remaining option, not inability."},sentence:{ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late."},target:"수밖에 없어",options:["to have no choice but to","there is no way that","it cannot be helped"],note:"No-choice situation caused by a real constraint."},{kind:"guess",word:{ko:"리가 없다",romanization:"riga eopda",en:"there is no way that",pos:"bound expression",nuance:"리가 없다 carries confidence or emotional conviction. It is not a neutral maybe-not."},sentence:{ko:"지금 포기할 리가 없어요.",en:"There is no way we would give up now."},target:"리가 없어",options:["to have no choice but to","there is no way that","to be only; nothing but"],note:"Strong disbelief, not a soft guess."},{kind:"guess",word:{ko:"뿐이다",romanization:"ppunida",en:"to be only; nothing but",pos:"bound expression",nuance:"뿐이다 closes the scope. It differs from 뿐만 아니라, which opens the sentence to an additional point."},sentence:{ko:"남은 건 이 방법뿐이에요.",en:"The only thing left is this method."},target:"뿐이",options:["there is no way that","it cannot be helped","to be only; nothing but"],note:"Limits the situation to one option."},{kind:"guess",word:{ko:"어쩔 수 없죠",romanization:"eojjeol su eopsjyo",en:"it cannot be helped",pos:"expression",nuance:"Casual-polite phrase for gracefully accepting something outside your control — a verbal shrug built from 어찌하다 ('to do how/what') contracted to 어쩌다 → 어쩔 수 없다 ('there's no way to do anything about it'). The -죠 softens the inevitability with 'right? / don't you agree?' — making the resignation feel communal rather than bitter. The closest near-synonym is 할 수 없죠, nearly interchangeable in most situations. The sharper contrast is with 포기하다 ('to give up'): 어쩔 수 없죠 is passive ACCEPTANCE of a situation that was never in your hands, while 포기하다 is an ACTIVE choice to stop something you could have continued. Tone is everything: said calmly it reads as mature and easygoing; said with a sharp sigh or flat affect, it tips into passive-aggressive 'fine, whatever.' The adverb variant 어쩔 수 없이 is a separate form that modifies verbs ('I unavoidably went') and cannot substitute for the standalone phrase."},sentence:{ko:"마감이 오늘이면 어쩔 수 없죠.",en:"If the deadline is today, it cannot be helped."},target:"어쩔 수 없죠",options:["to have no choice but to","there is no way that","it cannot be helped"],note:"Accepts the constraint."},{kind:"guess",word:{ko:"마감",romanization:"magam",en:"deadline; closing date",pos:"noun",nuance:"마감 is a native Korean noun (from the verb 막다 'to block/close off') meaning the point at which something is sealed shut: a report's due date, an application cutoff, a shop's last order, even a magazine going to press. The near-synonym confusion is with 기한 and 데드라인: 기한 (期限) is the dry, official 'time limit/term' you see on documents (제출 기한), while 마감 feels more like the live moment things close, and 데드라인 is a borrowed buzzword. Its signature collocation is the idiom 마감에 쫓기다 (chased by the deadline), the universal way to describe last-minute panic. The English-speaker pitfall is mapping 'meet a deadline' onto 만나다 ('meet a person'): you do NOT 마감을 만나다 — you 마감을 지키다 (keep/protect it). Note 지키다 is the same verb used for keeping a promise (약속을 지키다), which is the right mental image."},sentence:{ko:"마감이 오늘이라서 선택지가 별로 없어요.",en:"The deadline is today, so there are not many choices."},target:"마감",options:["deadline; closing date","method; way","situation; circumstances"],note:"The pressure that creates the no-choice frame."},{kind:"payoff",line:{speaker:"민서",ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late."},hl:"마감"}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b1",chapterId:"chapter-39",index:0},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 수밖에 없다",cards:[{kind:"teach",name:"V-(으)ㄹ 수밖에 없다",sub:"to have no choice but to",rows:[{when:"Verb stem ends in a consonant (받침 O)",add:"-을 수밖에 없다",ex:"먹다 → 먹을 수밖에 없다 (have no choice but to eat)"},{when:"Verb stem ends in a vowel (받침 X)",add:"-ㄹ 수밖에 없다",ex:"가다 → 갈 수밖에 없다 (have no choice but to go)"},{when:"Verb stem ends in ㄹ (ㄹ stays, just add 수밖에 없다)",add:"-ㄹ 수밖에 없다",ex:"살다 → 살 수밖에 없다 (have no choice but to live)"},{when:"Adjectives work too (= it can only be / it's bound to be)",add:"-(으)ㄹ 수밖에 없다",ex:"비싸다 → 비쌀 수밖에 없다 (it's bound to be expensive)"}],examples:[{ko:"버스가 없어서 걸어갈 수밖에 없었어요.",en:"There was no bus, so I had no choice but to walk.",romanization:"beoseu-ga eopseoseo georeogal su-bakke eopseosseoyo.",note:"A reason clause (없어서) plus this pattern is the most common shape: cause, then forced result."},{ko:"시간이 없어서 택시를 탈 수밖에 없어요.",en:"I don't have time, so I have no choice but to take a taxi.",romanization:"sigani eopseoseo taeksi-reul tal su-bakke eopseoyo.",note:"탈 from 타다 (vowel stem) just adds -ㄹ. Shows the everyday 'I'm forced into it' feeling."}],more:{func:`Use this to say there's no other option, so you end up doing the action whether you want to or not. It often sounds a little reluctant: "There's nothing else I can do, so I just do this."`,funcLead:"Use this to say there's no other option, so you end up doing the action whether you want to or not.",keyPoint:{label:"수밖에 없다 vs. -아/어야 하다",body:"-아/어야 하다 means you 'have to / should' do something (a duty, but other choices might still exist). V-(으)ㄹ 수밖에 없다 means every other option is gone, so you do it even if you'd rather not. '공부해야 해요' = I should study; '공부할 수밖에 없어요' = I've got no other choice but to study. (You'll meet -아/어야 하다 in its own lesson.)"},pronunciation:"수밖에 sounds like [수바께]: the ㄲ of 밖 links into 에 and stays tense. So 수밖에 없다 comes out as [수바께 업따].",pitfall:{wrong:"걸어갈 수밖에 있어요.",right:"걸어갈 수밖에 없어요.",explanation:"밖에 ('other than / except') always pairs with a negative, so the ending is always 없다, never 있다. 'There's nothing other than walking' = 없다. Saying 있어요 here flips the meaning and just sounds broken to a Korean ear."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "There was no bus, so I had no choice but to walk." (버스가 시작 · Start with 버스가.)',tokens:["버스가","없어서","걸어갈","수밖에","없었어요."],correct:"버스가 없어서 걸어갈 수밖에 없었어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't have time, so I have no choice but to take a taxi." (시간이 시작 · Start with 시간이.)`,tokens:["시간이","없어서","택시를","탈","수밖에","없어요."],correct:"시간이 없어서 택시를 탈 수밖에 없어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"걸어갈 수밖에 없어요.",ok:!0},{text:"걸어갈 수밖에 있어요.",ok:!1}],explanation:"밖에 ('other than / except') always pairs with a negative, so the ending is always 없다, never 있다. 'There's nothing other than walking' = 없다. Saying 있어요 here flips the meaning and just sounds broken to a Korean ear."}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b2",chapterId:"chapter-39",index:1},{kind:"words",title:"단어 Words 2 · 야근하다~",cards:[{kind:"guess",word:{ko:"야근하다",romanization:"yageunhada",en:"to work overtime; work late",pos:"verb",nuance:"야근하다 is the verb every Korean office worker knows: to stay and work into the evening, past regular hours. The hanja 夜勤 is 夜 'night' + 勤 'work/service' (the same 勤 as in 근무), literally 'night-work'. Its form is neutral, but in real use it almost always carries a tired, faintly complaining tone, because overtime is a charged feature of Korean work culture; the noun 야근 anchors a whole vocabulary of grievance — 야근 수당 (OT pay), 야근 잦아요 (lots of overtime), 칼퇴 (leaving right on time, the dream). The sharp boundary is against 야간근무: 야근 is staying late on an otherwise daytime job, whereas 야간근무 is a scheduled night shift (nurses, security, factory lines). Don't equate it with English 'overtime' as a contractual category either — that abstract concept is 초과근무 / 시간 외 근무. And for an all-nighter it escalates to 밤샘. Habitual collocations: 야근하다, 야근 수당, 야근이 잦다, 야근 안 하다."},sentence:{ko:"오늘은 야근할 수밖에 없어요.",en:"Today I have no choice but to work late."},target:"야근할",options:["to have no choice but to","to work overtime; work late","there is no way that"],note:"A common work-life no-choice sentence."},{kind:"guess",word:{ko:"포기하다",romanization:"pogihada",en:"to give up",pos:"verb",nuance:"포기하다 = to give up, abandon, or relinquish a goal, plan, claim, or even a person. The hanja 抛棄 is vivid: 抛 'to throw/hurl away' + 棄 'to discard, abandon', so the image is hurling something aside and walking off — a decisive letting-go, not a gentle fade. Contrast 포기하다 (stop pursuing a goal entirely) with 그만두다 (stop/quit an ongoing activity — a job, a habit) and with 단념하다 (a more bookish 'resign oneself to abandoning hope'); in speech 포기하다 is the everyday choice. Grammar: it pairs with 을/를 (목표를 포기하다) or with 는 거 / 는 걸 (사는 걸 포기하다 = 'give up on buying'). Culturally the word is loaded: N포세대, the 'give-up generation', names young Koreans said to have surrendered dating, marriage, and kids to economic pressure. English-speaker pitfall: the negative is 포기 안 해 / 포기 못 해 (noun + 안/못 + 해), NOT 안 포기해."},sentence:{ko:"지금 포기할 리가 없어요.",en:"There is no way we would give up now."},target:"포기할",options:["to have no choice but to","there is no way that","to give up"],note:"Natural with -ㄹ 리가 없다."},{kind:"guess",word:{ko:"방법",romanization:"bangbeop",en:"method; way",pos:"noun",nuance:"방법 is Sino-Korean (方法, 方 'direction/manner' + 法 'rule/method'), the 'way', 'method', or 'means' of doing something — the procedure or approach to reach a goal. Compare it with 방식 (方式, 'style/mode/manner'): 방법 is the concrete how-to ('a method to fix it'), while 방식 is the overall style or fashion in which something is done (생활 방식 = lifestyle, 사고방식 = way of thinking) — you wouldn't say 사고방법. Also distinguish 수단 (手段, 'means/instrument', often the tool or even an unscrupulous means: 교통수단 = means of transport, 수단과 방법을 가리지 않다 = by any means necessary). Register-neutral, very common. Core collocations: 방법이 있다/없다, 방법을 찾다/알다/모르다/바꾸다, [동사]~는 방법 (a way to do ~), 해결 방법 (solution), 사용 방법 (how to use). The English-speaker pitfall is the 'a way to do X' frame: it's [verb in ~는 form] + 방법, e.g. 'a way to study' is 공부하는 방법, NOT 공부 방법 in spoken contexts (though 공부 방법 as a fixed noun-noun compound is fine for 'study method'). Don't say 방법으로 어떻게 when you just mean 어떻게 ('how') — 방법 is the noun 'method', not the question word 'how'."},sentence:{ko:"남은 건 이 방법뿐이에요.",en:"The only thing left is this method."},target:"방법",options:["deadline; closing date","method; way","situation; circumstances"],note:"Pairs naturally with 뿐이다."},{kind:"guess",word:{ko:"가능하다",romanization:"ganeunghada",en:"to be possible",pos:"adjective",nuance:"가능하다 (可能, 可 'can/permissible' + 能 'ability') means 'possible / doable / available', and it is wonderfully practical for daily service questions — 예약 가능해요? ('Is a reservation possible?'), 카드 가능해요? ('Can I pay by card?'). In these, a noun sits directly before it and it neatly replaces a longer '-ㄹ 수 있다' clause, sounding crisp and businesslike. The softener 가능하면 ('if possible') makes requests polite, and the fixed frame 가능한 한 + adjective/adverb means 'as ~ as possible' (가능한 한 빨리 'as soon as possible') — note this is different from 가능한 N ('a possible N'). Its antonym is 불가능하다. One pitfall: while 가능하다 and '-ㄹ 수 있다' both render English 'can', '-ㄹ 수 있다' attaches to a verb stem describing an action you're able to do (갈 수 있어요 'I can go'), whereas 가능하다 attaches to a noun or stands alone judging feasibility — don't merge them into 갈 가능해요."},sentence:{ko:"오늘 안에 가능해요?",en:"Is it possible within today?"},target:"가능해",options:["to be possible","to have no choice but to","there is no way that"],note:"Plain possibility, not no-choice."},{kind:"guess",word:{ko:"불가능하다",romanization:"bulganeunghada",en:"to be impossible",pos:"adjective",nuance:"불가능하다 (不可能, the prefix 不 'not/un-' on 가능 'possible') is the direct antonym of 가능하다: 불 flips it to 'cannot be done, impossible'. The 不-prefix pattern recurs across Sino-Korean adjectives (불편하다 'uncomfortable', 불확실하다 'uncertain'), so recognising 불- as a negator unlocks many words. In service settings 불가능하다 is a firm but polite way to refuse, and Koreans habitually cushion it with 좀 ('a bit') or pair it with a 'but...' offer (환불은 불가능하지만 교환은 가능해요) to soften the blow. For an everyday personal 'I can't', the '-ㄹ 수 없다' pattern (갈 수 없어요 'I can't go') is more natural than forcing 불가능하다, which leans toward declaring something infeasible in principle. As a 하다-adjective the pre-noun is 불가능한, never 불가능하는."},sentence:{ko:"지금 방식으로는 거의 불가능해요.",en:"With the current method, it is almost impossible."},target:"불가능해",options:["to be impossible","to have no choice but to","there is no way that"],note:"Useful contrast with -ㄹ 리가 없다."},{kind:"payoff",line:{speaker:"지훈",ko:"결국 남은 건 이 방법뿐이에요.",en:"In the end, this method is the only thing left."},hl:"방법"}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b3",chapterId:"chapter-39",index:2},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 리가 없다",cards:[{kind:"teach",name:"V-(으)ㄹ 리가 없다",sub:"there's no way that's true",rows:[{when:"Verb/Adjective stem ends in a consonant (받침 O)",add:"-을 리가 없다",ex:"먹다 → 먹을 리가 없다 (there's no way he'd eat it)"},{when:"Verb/Adjective stem ends in a vowel (받침 X)",add:"-ㄹ 리가 없다",ex:"오다 → 올 리가 없다 (there's no way it'll come / he'll come)"},{when:"Past meaning (it already happened)",add:"-았/었을 리가 없다",ex:"가다 → 갔을 리가 없다 (there's no way he went)"},{when:"Noun + 이다",add:"일 리가 없다",ex:"학생 → 학생일 리가 없다 (there's no way he's a student)"}],examples:[{ko:"그 친구가 거짓말을 했을 리가 없어요.",en:"There's no way that friend lied.",romanization:"geu chinguga geojinmareul haesseul liga eopseoyo.",note:"Past form 했을 리가 없다 rejects that a past action happened. Very common with 거짓말."},{ko:"지금 밤 12시인데 학생들이 학교에 있을 리가 없어요.",en:"It's midnight now, so there's no way the students are at school.",romanization:"jigeum bam yeoldu-si-inde haksaengdeuri hakgyo-e isseul liga eopseoyo.",note:"A known fact (it's the middle of the night) makes the idea impossible. The typical 'fact + 리가 없다' shape."}],more:{func:`Use this to say you really don't believe something: you're sure it can't be the case because it makes no sense. It's the Korean way of saying "There's no way…" or "It can't possibly be that…"`,funcLead:"Use this to say you really don't believe something: you're sure it can't be the case because it makes no sense.",keyPoint:{label:"-(으)ㄹ 리가 없다 vs. -(으)ㄹ 수 없다",body:"-(으)ㄹ 수 없다 is about real ability: 'can't do it' (갈 수 없어요 = I'm not able to go). -(으)ㄹ 리가 없다 is about your certainty that a claim is false: 'there's no way that's true' (갔을 리가 없어요 = no way he went). The first is about being able; the second is about believing."},pronunciation:"없어요 sounds like [업써요]: the ㅅ of the 없- cluster slides onto the next syllable and goes tense, while ㅂ stays as a stop. So 리가 없어요 comes out as [리가 업써요].",pitfall:{wrong:"저는 오늘 갈 리가 없어요. (meaning: I can't go today)",right:"저는 오늘 못 가요. / 갈 수 없어요.",explanation:"English 'there's no way' covers both 'I'm unable to' and 'I don't believe it.' But 리가 없다 only means disbelief about a fact, and it sounds odd about your own plans. For 'I can't go,' use 못 가요 or 갈 수 없어요. Save 갈 리가 없어요 for 'there's no way he'd go.'"}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "There's no way that friend lied."`,tokens:["그","친구가","거짓말을","했을","리가","없어요."],correct:"그 친구가 거짓말을 했을 리가 없어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 오늘 갈 리가 없어요. (meaning: I can't go today)",ok:!1},{text:"저는 오늘 못 가요. / 갈 수 없어요.",ok:!0}],explanation:"English 'there's no way' covers both 'I'm unable to' and 'I don't believe it.' But 리가 없다 only means disbelief about a fact, and it sounds odd about your own plans. For 'I can't go,' use 못 가요 or 갈 수 없어요. Save 갈 리가 없어요 for 'there's no way he'd go.'"}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b4",chapterId:"chapter-39",index:3},{kind:"words",title:"단어 Words 3 · 상황~",cards:[{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation; circumstances",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"이런 상황에서는 다시 확인할 수밖에 없어요.",en:"In this situation, we have no choice but to check again."},target:"상황",options:["deadline; closing date","method; way","situation; circumstances"],note:"The noun that explains why there is no other option."},{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"materials; data; documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"자료가 틀렸을 리가 없어요.",en:"There is no way the data is wrong."},target:"자료",options:["deadline; closing date","materials; data; documents","situation; circumstances"],note:"Work/study content that can be checked or revised."},{kind:"guess",word:{ko:"설명",romanization:"seolmyeong",en:"explanation",pos:"noun",nuance:"설명(說明) is Sino-Korean — 說 'to tell/speak' + 明 'clear, bright' — literally 'to make clear by telling,' i.e. an explanation of how or why something works. Distinguish it from 설득(說得) 'persuasion' (talking someone INTO agreeing, sharing the 說 root) and from 묘사(描寫) 'description' (depicting what something looks/feels like); 설명 is about clarifying and informing, not convincing or portraying. As a noun it becomes the verb with 하다: 설명하다, very often softened to 설명해 주세요/주시겠어요 'please explain for me.' Collocations: 설명을 하다/듣다, 자세한 설명, 설명이 부족하다/이해가 안 되다, 설명서 'instruction manual.' The English-speaker pitfall: English 'explain to me' tempts learners to mark the listener with 를 (저를 설명하다 ✗, which would mean 'explain ME'); the listener takes 한테/에게 (저한테 설명해 주세요), and what you explain takes 을/를. Bare 설명 can't be the verb — use 설명하다. Don't confuse 설명 with the look-alike 설탕 'sugar.'"},sentence:{ko:"설명은 다시 쓸 수밖에 없어요.",en:"We have no choice but to rewrite the explanation."},target:"설명",options:["deadline; closing date","explanation","method; way"],note:"A realistic repair action under a deadline."},{kind:"payoff",line:{speaker:"민서",ko:"자료는 맞지만 설명은 다시 쓸 수밖에 없어요.",en:"The data is right, but we have no choice but to rewrite the explanation."},hl:"자료"}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b5",chapterId:"chapter-39",index:4},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 뿐이다 / N뿐이다",cards:[{kind:"teach",name:"V-(으)ㄹ 뿐이다 / N뿐이다",sub:"only, nothing more",rows:[{when:"Verb/Adjective stem + 받침 O",add:"-을 뿐이다",ex:"믿다 → 믿을 뿐이다 (I just believe it, that's all)"},{when:"Verb/Adjective stem + 받침 X",add:"-ㄹ 뿐이다",ex:"기다리다 → 기다릴 뿐이다 (I'm only waiting)"},{when:"Past meaning",add:"-았/었을 뿐이다",ex:"하다 → 했을 뿐이다 (I just did it, nothing more)"},{when:"Noun (no -(으)ㄹ; 뿐 attaches straight to the noun)",add:"N + 뿐이다",ex:"물 → 물뿐이다 (there's only water)"}],examples:[{ko:"저는 사실대로 말했을 뿐이에요.",en:"I only told the truth, that's all.",romanization:"jeoneun sasildaero malhaesseul ppunieyo.",note:"Past 말했을 뿐이다 is the classic 'I just did X, so don't blame me' use."},{ko:"그냥 농담했을 뿐이에요. 화내지 마세요.",en:"I was just joking, nothing more. Don't be mad.",romanization:"geunyang nongdamhaesseul ppunieyo. hwanaeji maseyo.",note:"그냥 ('just') goes naturally with 뿐이다 to play an action down."}],more:{func:"Use this to limit things to just one: 'that's all there is, nothing else.' With verbs/adjectives it means 'only does / is only'; attached straight to a noun, 뿐이다 means 'only that, and nothing else.'",funcLead:"Use this to limit things to just one: 'that's all there is, nothing else.' With verbs/adjectives it means 'only does / is only'; attached straight to a noun, 뿐…",keyPoint:{label:"-(으)ㄹ 뿐이다, N뿐이다, and N일 뿐이다",body:"After a verb or adjective, use the -(으)ㄹ form: 기다릴 뿐이에요. N뿐이다 means 'only N / N is all there is': 물뿐이에요. N일 뿐이다 is also grammatical, but it classifies or plays down the noun: 물일 뿐이에요 = 'it is merely water.' The two noun patterns answer different questions, so do not treat either one as universally wrong."},pronunciation:"뿐이에요 links smoothly as [뿌니에요]: the ㄴ of 뿐 slides onto 이. With a noun like 물, 물뿐이에요 sounds like [물뿌니에요].",pitfall:{wrong:"물뿐이에요 and 물일 뿐이에요 always mean exactly the same thing.",right:"냉장고에는 물뿐이에요. (Only water is there.) / 이건 물일 뿐이에요. (This is merely water.)",explanation:"N뿐이다 limits what exists or is available. N일 뿐이다 says that something is merely N and nothing more. Both are grammatical; choose the structure that matches the intended message."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I only told the truth, that's all."`,tokens:["저는","사실대로","말했을","뿐이에요."],correct:"저는 사실대로 말했을 뿐이에요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I was just joking, nothing more. Don't be mad."`,tokens:["그냥","농담했을","뿐이에요.","화내지","마세요."],correct:"그냥 농담했을 뿐이에요. 화내지 마세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"냉장고에는 물뿐이에요. (Only water is there.) / 이건 물일 뿐이에요. (This is merely water.)",ok:!0},{text:"물뿐이에요 and 물일 뿐이에요 always mean exactly the same thing.",ok:!1}],explanation:"N뿐이다 limits what exists or is available. N일 뿐이다 says that something is merely N and nothing more. Both are grammatical; choose the structure that matches the intended message."}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b6",chapterId:"chapter-39",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A team handles a deadline where there is no realistic choice left.",lines:[{speaker:"민서",ko:"마감이 오늘이라서 야근할 수밖에 없어요.",en:"The deadline is today, so we have no choice but to work late.",romanization:"magami oneuriraseo yageunhal subakke eopseoyo."},{speaker:"지훈",ko:"그래도 지금 포기할 리가 없죠.",en:"Still, there is no way we would give up now.",romanization:"geuraedo jigeum pogihal riga eopsjyo."},{speaker:"민서",ko:"자료는 맞지만 설명은 다시 쓸 수밖에 없어요.",en:"The data is right, but we have no choice but to rewrite the explanation.",romanization:"jaryoneun matjiman seolmyeongeun dasi sseul subakke eopseoyo."},{speaker:"지훈",ko:"결국 남은 건 이 방법뿐이에요.",en:"In the end, this method is the only thing left.",romanization:"gyeolguk nameun geon i bangbeopppunieyo."}]},{kind:"order",prompt:"Build: 'There is no way that person will give up.'",tokens:["그 사람이","포기할 리가 없어요"],correct:"그 사람이 포기할 리가 없어요",explanation:"-(으)ㄹ 리가 없어요 strongly rejects a possibility. 포기할 리가 없어요 means giving up is not plausible."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"자료는 맞지만 설명은 다시 쓸 수밖에 없어요.",options:[{text:"지훈",ok:!1},{text:"민서",ok:!0}],explanation:"The data is right, but we have no choice but to rewrite the explanation."},{kind:"drill",prompt:'무엇이 들어갈까요? · "The deadline is today, so we have no choice but to work late."',sentence:"___이 오늘이라서 야근할 수밖에 없어요.",options:[{text:"마감",ok:!0},{text:"방법",ok:!1},{text:"상황",ok:!1}],explanation:""}],canDo:"Say I have no other option with -(으)ㄹ 수밖에 없다 (야근할 수밖에 없어요)",id:"chapter-39-b7",chapterId:"chapter-39",index:6},{kind:"reading",title:"읽기 Reading · 마감이라서 할 수밖에 없어요",cards:[{kind:"read",title:"마감이라서 할 수밖에 없어요",chunks:["마감이 가까우면 선택지가 줄어들어요. 이때 '할 수 없어요'라고 말하면 능력이 없거나 불가능하다는 뜻이 되지만, '할 수밖에 없어요'라고 말하면 하기 싫어도 그 방법밖에 없다는 뜻이 돼요. 반대로 '포기할 리가 없어요'는 포기할 가능성을 강하게 부정하는 말이에요.","그리고 '남은 건 이 방법뿐이에요'는 다른 선택이 없고 이 방법만 남았다는 뜻이에요. 세 표현은 모두 한계와 관련이 있지만, 각각 no choice, no way, only one이라는 다른 느낌을 가지고 있어요."],translation:"When a deadline is close, choices shrink. 할 수밖에 없어요 means there is no choice but to do it, not that you cannot do it. 리가 없어요 strongly rejects a possibility, and 뿐이에요 limits the situation to only one remaining option.",qas:[{q:"할 수 없어요와 할 수밖에 없어요는 어떻게 달라요?",a:"할 수 없어요는 불가능, 할 수밖에 없어요는 다른 선택이 없다는 뜻이에요."},{q:"포기할 리가 없어요는 어떤 느낌이에요?",a:"포기할 가능성을 강하게 부정하는 느낌이에요."},{q:"이 방법뿐이에요는 무엇을 뜻해요?",a:"이 방법만 남았다는 뜻이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___이 가까우면 선택지가 줄어들어요.",options:[{text:"상황",ok:!1},{text:"자료",ok:!1},{text:"마감",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"이때 '할 수 없어요'라고 말하면 능력이 없거나 ___는 뜻이 되지만, '할 수밖에 없어요'라고 말하면 하기 싫어도 그 방법밖에 없다는 뜻이 돼요.",options:[{text:"불가능하다",ok:!0},{text:"수밖에 없다",ok:!1},{text:"리가 없다",ok:!1}],explanation:""}],canDo:"Reject something as impossible with -(으)ㄹ 리가 없다 (끝날 리가 없어요)",id:"chapter-39-b8",chapterId:"chapter-39",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence means “I have no choice but to work late”?",sentence:null,options:[{text:"야근할 수밖에 없어요.",ok:!0},{text:"야근할 수 없어요.",ok:!1},{text:"야근할지도 몰라요.",ok:!1}],explanation:"수밖에 없다 means the situation leaves no other option."},{kind:"drill",prompt:"Which sentence strongly rejects a possibility?",sentence:null,options:[{text:"포기할 리가 없어요.",ok:!0},{text:"포기할 수도 있어요.",ok:!1},{text:"포기할 뿐만 아니라.",ok:!1}],explanation:"-ㄹ 리가 없다 means there is no way that possibility is true."},{kind:"drill",prompt:"Which sentence means only one method remains?",sentence:null,options:[{text:"남은 건 이 방법뿐이에요.",ok:!0},{text:"남은 건 이 방법뿐만 아니라예요.",ok:!1},{text:"남은 건 이 방법일 리가 없어요.",ok:!1}],explanation:"N뿐이다 limits the situation to only that noun."},{kind:"drill",prompt:"마감___ 있어서 야근할 수밖에 없어요. (Because there is a deadline...)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"있다 takes 이/가 for the thing that exists. 마감이 있어서 gives the reason before the no-choice result."},{kind:"drill",prompt:"Only one realistic option remains. Which sentence fits?",sentence:null,options:[{text:"이 방법뿐이에요.",ok:!0},{text:"이 방법보다 더예요.",ok:!1},{text:"이 방법일걸요.",ok:!1}],explanation:"뿐이에요 means only this and nothing more. The other options compare or guess rather than limit the options."}],canDo:"Limit things to just one with -(으)ㄹ 뿐이다 / N뿐이다 (이것뿐이에요)",id:"chapter-39-b9",chapterId:"chapter-39",index:8}]},{id:"chapter-40",number:40,title:"-(으)ㄹ걸요 · -(으)면 좋겠어요",goal:"Use -ㄹ걸요 for a soft but fairly confident guess.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 걸요~",cards:[{kind:"guess",word:{ko:"걸요",romanization:"geolyo",en:"probably; I think...",pos:"sentence ending",nuance:"걸요 is softer than a plain statement, but it is not as open-ended as 글쎄요. The speaker still has a hunch."},sentence:{ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"걸요",options:["I hope; it would be good if...","probably; I think...","if; supposing that"],note:"Linked to word-ext-ch40-geolyo."},{kind:"guess",word:{ko:"좋겠어요",romanization:"jokesseoyo",en:"I hope; it would be good if...",pos:"wish expression",nuance:"좋겠어요 is useful when you want to express a hope or suggestion without sounding like an order."},sentence:{ko:"메시지를 남겨 두면 좋겠어요.",en:"It would be good to leave a message."},target:"좋겠어요",options:["probably; I think...","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-jokesseoyo."},{kind:"guess",word:{ko:"다면",romanization:"damyeon",en:"if; supposing that",pos:"conditional ending",nuance:"다면 often feels more hypothetical or careful than plain -(으)면."},sentence:{ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message."},target:"다면",options:["probably; I think...","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-damyeon."},{kind:"guess",word:{ko:"것 같아요",romanization:"geot gatayo",en:"I think; it seems like",pos:"hedging expression",nuance:"것 같아요 is not the same as 같다 meaning 'same.' Here it softens the whole statement."},sentence:{ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first."},target:"것 같아요",options:["I think; it seems like","I hope; it would be good if...","if; supposing that"],note:"Linked to word-ext-ch40-geot-gatayo."},{kind:"guess",word:{ko:"겠",romanization:"get",en:"inference or intention marker",pos:"modal marker",nuance:"겠 is not one English word. It can be intention, inference, or a set response depending on context."},sentence:{ko:"제가 조심스럽게 물어보겠습니다.",en:"I will ask carefully."},target:"겠",options:["inference or intention marker","probably; I think...","I hope; it would be good if..."],note:"Linked to word-ext-ch40-get."},{kind:"guess",word:{ko:"조심스럽게",romanization:"josimseureopge",en:"carefully; cautiously",pos:"adverb",nuance:"조심스럽게 is about tone and risk. It is not just physical carefulness."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"조심스럽게",options:["probably","by any chance","carefully; cautiously"],note:"Linked to word-ext-ch40-josimseureopge."},{kind:"guess",word:{ko:"아마",romanization:"ama",en:"probably",pos:"adverb",nuance:"아마 means 'probably / perhaps,' expressing the speaker's reasonable guess, and its grammar is almost inseparable: it is normally completed by a conjecture ending — most often -ㄹ/을 거예요 ('will probably'), or -ㄹ 것 같다, -겠-, -ㄹ걸요. The bare statement 아마 비가 와요 sounds unfinished; you want 아마 비가 올 거예요. A near-synonym is 아마도, which is just a softer, slightly more deliberative version of 아마 (interchangeable; 아마도 can feel a touch more written or musing). Distinguish the certainty scale: 아마 is a fairly confident guess (~maybe 70-80%), 어쩌면/혹시 lean toward 'possibly, by any chance' (lower, more tentative), and 분명히/틀림없이 mean 'surely/definitely' (high certainty). The English-speaker pitfall is using 아마 with a flat present/past as if it were the English adverb that can float anywhere ('he's probably home'): in Korean the verb itself must carry the guessing form, so 'he's probably home' = 아마 집에 있을 거예요, not 아마 집에 있어요. Also avoid 아마 with established facts — 아마 물은 H2O일 거예요 sounds odd because you're hedging a certainty. Place 아마 near the front of the clause, and let the sentence-final ending do the conjecture work."},sentence:{ko:"아마 담당자가 알걸요.",en:"The person in charge probably knows."},target:"아마",options:["carefully; cautiously","probably","by any chance"],note:"Linked to dictionary card word-ext-1242."},{kind:"payoff",line:{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},hl:"걸요"}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b1",chapterId:"chapter-40",index:0},{kind:"pattern",title:"문법 Grammar · -(으)ㄹ걸요",cards:[{kind:"teach",name:"-(으)ㄹ걸요",sub:"A Soft but Confident Guess",rows:[{when:"Verb/adjective stem ends in a vowel",add:"-ㄹ걸요",ex:"가다 → 갈걸요; 비싸다 → 비쌀걸요"},{when:"Verb/adjective stem ends in a consonant",add:"-을걸요",ex:"먹다 → 먹을걸요; 작다 → 작을걸요"},{when:"Stem ends in ㄹ",add:"drop ㄹ, then add -ㄹ걸요",ex:"살다 → 살걸요; 멀다 → 멀걸요"},{when:"Past (any stem)",add:"-았/었을걸요",ex:"가다 → 갔을걸요; 먹다 → 먹었을걸요"},{when:"Noun (guess about a fact)",add:"N일걸요",ex:"학생 → 학생일걸요"}],examples:[{ko:"친구는 지금 집에 있을걸요.",en:"My friend is probably home right now.",romanization:"chinguneun jigeum jibe isseulgeolyo.",note:"A guess you're fairly sure of, softened so it doesn't sound like a flat claim."},{ko:"그 영화 재미있을걸요.",en:"That movie's probably good.",romanization:"geu yeonghwa jaemiisseulgeolyo.",note:"있다 ends in a consonant, so it takes -을걸요."}],more:{func:`Use -(으)ㄹ걸요 when you make a guess you're fairly sure about, but want to sound gentle instead of flat-out telling someone. It feels like "I'd say..." or "probably..." based on what you know.`,funcLead:"Use -(으)ㄹ걸요 when you make a guess you're fairly sure about, but want to sound gentle instead of flat-out telling someone.",keyPoint:{label:"-(으)ㄹ걸요 vs. -(으)ㄹ 거예요",body:`Both say something is likely. -(으)ㄹ 거예요 sounds like a plain prediction; -(으)ㄹ걸요 adds a softer "I'd guess" feeling, often when the other person might be thinking otherwise. Save the finer back-vowel rules for later — just match vowel vs. consonant stems for now.`},pronunciation:"걸요 sounds like [거료], so 갈걸요 comes out [갈꺼료] — the ㄱ tenses and the ㄹ links smoothly into 요.",pitfall:{wrong:"내일 비가 올 거 같을걸요.",right:"내일 비가 올걸요.",explanation:`English speakers stack "probably" on top of another guess word. -(으)ㄹ걸요 already means "probably," so don't combine it with -(으)ㄹ 것 같다. Attach it straight to the plain stem: 올걸요.`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "My friend is probably home right now." (친구는 시작 · Start with 친구는.)',tokens:["친구는","지금","집에","있을걸요."],correct:"친구는 지금 집에 있을걸요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "That movie's probably good."`,tokens:["그","영화","재미있을걸요."],correct:"그 영화 재미있을걸요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"내일 비가 올 거 같을걸요.",ok:!1},{text:"내일 비가 올걸요.",ok:!0}],explanation:`English speakers stack "probably" on top of another guess word. -(으)ㄹ걸요 already means "probably," so don't combine it with -(으)ㄹ 것 같다. Attach it straight to the plain stem: 올걸요.`}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b2",chapterId:"chapter-40",index:1},{kind:"words",title:"단어 Words 2 · 글쎄요~",cards:[{kind:"guess",word:{ko:"글쎄요",romanization:"geulsseyo",en:"Hmm, I'm not sure",pos:"expression",nuance:"글쎄요 is the classic Korean verbal hedge — a non-committal 'hmm, well, I'm not sure' that lets you avoid both 'yes' and 'no.' It buys time, signals reluctance or uncertainty, and very often functions as a soft pre-refusal or a polite way to withhold agreement without contradicting the other person. The 요 makes it polite; 글쎄 alone is 반말 and can also mean 'we'll see' or even an insistent 'I told you…' depending on tone. Register: 글쎄요 polite, 글쎄 casual. The dividing line from 모르겠어요 ('I don't know') is intent: 모르겠어요 states genuine lack of knowledge, while 글쎄요 is a strategic hedge — you may well have an opinion but are choosing not to commit, so it's softer and more diplomatic for declining or dodging. The English-speaker trap is hearing 글쎄요 as a real 'I don't know' and re-explaining or pressing for an answer; in many cases it politely means 'eh, probably not' or 'I'd rather not say', and pushing is impolite. Another error is overusing it as a filler the way English uses 'well' — too many 글쎄요s can read as evasive or wishy-washy. Pair it with 잘 모르겠는데요 ('I'm not really sure') or 생각해 봐야겠어요 ('I'd have to think') to extend the hedge gracefully. Crucially, recognize it from the other side: when a Korean answers your request with 글쎄요, treat it as a likely soft 'no', not an invitation to argue your case."},sentence:{ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work."},target:"글쎄요",options:["in my opinion; I think","I hope; it would be good if...","Hmm, I'm not sure"],note:"Linked to dictionary card expr-327."},{kind:"guess",word:{ko:"제 생각에는",romanization:"je saenggageneun",en:"in my opinion; I think",pos:"expression",nuance:"제 생각에는 is the standard polite opener that signals 'this is just my view, not a command or fact'. 제 is the humble form of 나 ('my'), and 에는 sets up a frame — literally 'as for within my thinking'. It works with anyone: strangers, seniors, classmates, colleagues, customers. To go casual with a close friend, swap to 내 생각에는; for a more considered, slightly formal feel use 제 생각으로는 (the -으로는 particle stresses the viewpoint angle). The nearest alternative is 제가 보기에는 — the dividing line is thinking vs observing: 제 생각에는 comes from your internal reasoning, while 제가 보기에는 is based on what you see or sense from evidence. The classic English-speaker mistake is calquing 'in my opinion' literally as 제 의견에는, which is bookish and rare in spoken Korean. A second trap: dropping the particle entirely (제 생각 좋아요) — without 에는 or 엔 the opener is ungrammatical."},sentence:{ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first."},target:"제 생각에는",options:["Hmm, I'm not sure","in my opinion; I think","I hope; it would be good if..."],note:"Linked to dictionary card expr-567."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"의견을 조심스럽게 말하는 게 좋겠어요.",en:"It would be good to state the opinion carefully."},target:"의견",options:["opinion","burden; pressure","meeting"],note:"Linked to dictionary card word-ext-2048."},{kind:"guess",word:{ko:"확실하다",romanization:"hwaksilhada",en:"to be certain; sure",pos:"adjective",nuance:"확실하다 (確實, 確 'firm/sure' + 實 'real/true') expresses certainty and confidence — you're sure something is true, settled, or reliable. The adverb 확실히 ('certainly, definitely, for sure') is very common when answering or confirming (확실히 그래요 'that's definitely so'). The sharp contrast is with 분명하다: 확실하다 centres on the speaker's subjective confidence ('I'm sure of it'), while 분명하다 centres on a thing being objectively obvious/unambiguous — so 나는 확실해 ('I'm certain') but 증거가 분명해 ('the evidence is clear-cut'). It also brushes against 틀림없다 ('there's no mistake / definitely'), which is even more emphatic. Crucially, 확실하다 is for certainty, not possibility: to say 'maybe' you need 아마 ('probably') or '-ㄹ지도 몰라요' ('might'), not 확실하다. The natural adverb is 확실히 in everyday speech (확실하게 is a touch stiffer)."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"확실하",options:["probably; I think...","I hope; it would be good if...","to be certain; sure"],note:"Linked to dictionary card word-ext-1254."},{kind:"guess",word:{ko:"부담",romanization:"budam",en:"burden; pressure",pos:"noun",nuance:"부담 is essential for navigating Korean social give-and-take, where accepting too much puts you in someone's debt. It is Sino-Korean 負擔 (負 'to carry on the back' + 擔 'to shoulder'), literally 'a load you shoulder', and it covers both a *financial* weight (rent, a pricey gift) and an *emotional* one (expectations, obligation). When a host says 부담 갖지 마세요, they are pre-emptively lifting that load off you; when you call a gesture 부담스러워요, you are politely signaling 'this is too generous, I'd feel indebted.' The contrast to learn is 부담 (mental/social pressure or weight) vs 짐 (a literal piece of luggage, or a metaphorical 'I'm a burden to you' = 짐이 되다). The English-speaker trap is translating it only as 'burden' and missing the warm 'please don't trouble yourself' social move, and confusing the formal verb 부담하다 (to bear a *cost*, as in 비용을 부담하다) with feeling pressure, for which you want 부담스럽다 or 부담이 되다."},sentence:{ko:"이렇게 말하면 좀 부담스러운 것 같아요.",en:"If we say it this way, I think it feels a bit pressuring."},target:"부담",options:["burden; pressure","opinion","meeting"],note:"Linked to dictionary card word-ext-733."},{kind:"guess",word:{ko:"혹시",romanization:"hoksi",en:"by any chance",pos:"adverb",nuance:"혹시 is the Sino-Korean 或是 (或 'perhaps' + 是 'be so') and lives at the FRONT of a question to soften it, exactly like English 'by any chance' or 'do you happen to': it signals you are unsure and refuse to assume, so requests and guesses land politely rather than pushily. Do not confuse it with 만약 (萬若, 'if / supposing'): 만약 sets up a conditional clause and pairs with -면 (만약 비가 오면 = if it rains), whereas 혹시 colors a whole question with tentativeness and does NOT need -면. The big English-speaker trap is dropping 혹시 into a flat statement; it belongs with a question or with the set phrase 혹시 몰라서 / 혹시 모르니까 ('just in case'). It also collocates with 혹시나 (an even softer, more anxious variant) and with 혹시 ~ 거 아니에요? for a worried hunch."},sentence:{ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message."},target:"혹시",options:["by any chance","carefully; cautiously","already"],note:"Linked to dictionary card word-ext-646."},{kind:"guess",word:{ko:"이미",romanization:"imi",en:"already",pos:"adverb",nuance:"이미 means 'already,' emphasizing that an action or state is completed and now fixed — often colored by 'and there's no changing it now.' The sharp contrast every learner needs is 이미 vs 벌써. Both translate as 'already,' but 이미 is neutral and factual ('it is already done, that's just the situation'), while 벌써 adds emotional surprise that it happened so fast or so soon ('already?! that quick?'). 이미 끝났어요 = a calm statement of fact; 벌써 끝났어요?! = 'it's over already?!' with raised eyebrows. So choose 이미 when calmly noting that the moment/deadline has passed, and 벌써 when reacting to unexpected speed. 이미 is native Korean and is also future-blind: it only describes things already done, never things about to happen. It pairs naturally with completed clauses and with -더라고요, -았/었- past forms."},sentence:{ko:"이미 퇴근했을 수도 있어요.",en:"They may have already left work."},target:"이미",options:["already","carefully; cautiously","probably"],note:"Linked to dictionary card word-ext-983."},{kind:"payoff",line:{speaker:"지훈",ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work."},hl:"글쎄요"}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b3",chapterId:"chapter-40",index:2},{kind:"pattern",title:"문법 Grammar · -(으)면 좋겠어요",cards:[{kind:"hunt",name:"-(으)면 좋겠어요",sub:"A Hope or Gentle Wish",lines:[{tokens:[{pre:"내일",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋",mid:"으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"내일 날씨가 좋으면 좋겠어요.",en:"I hope the weather's nice tomorrow.",romanization:"naeil nalssiga joeumyeon jokesseoyo."},{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"있",mid:"으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"시간이 좀 더 있으면 좋겠어요.",en:"I wish I had a little more time.",romanization:"sigani jom deo isseumyeon jokesseoyo."}],rule:{name:"-(으)면 좋겠어요",rows:[{when:"Stem ends in a vowel",add:"-면 좋겠어요",ex:"오다 → 오면 좋겠어요; 싸다 → 싸면 좋겠어요"},{when:"Stem ends in a consonant",add:"-으면 좋겠어요",ex:"먹다 → 먹으면 좋겠어요; 많다 → 많으면 좋겠어요"},{when:"Stem ends in ㄹ",add:"-면 좋겠어요 (keep ㄹ)",ex:"살다 → 살면 좋겠어요"},{when:"Wish about now / something not true",add:"-았/었으면 좋겠어요",ex:"오다 → 왔으면 좋겠어요; 있다 → 있었으면 좋겠어요"},{when:"Noun",add:"N(이)면 좋겠어요",ex:"주말 → 주말이면 좋겠어요"}]},more:{func:`Use -(으)면 좋겠어요 to say "I hope..." or "I wish...". It literally means "it'd be nice if...," and it's the everyday way to say what you'd like to happen.`,funcLead:'Use -(으)면 좋겠어요 to say "I hope..." or "I wish...".',keyPoint:{label:"-(으)면 좋겠어요 vs. -고 싶어요",body:`-고 싶어요 means "I want to (do it myself)." -(으)면 좋겠어요 means "I hope (it happens)," so it can be about other people, the weather, or things you don't control. The contrary-to-fact nuance of the -았/었으면 form gets fuller treatment in a later chapter.`},pronunciation:"좋겠어요 sounds like [조케써요]: ㅎ + ㄱ blend into an aspirated [ㅋ], and 겠 tenses the next ㅅ into [써].",pitfall:{wrong:"한국에 가고 싶으면 좋겠어요.",right:"한국에 가면 좋겠어요.",explanation:`Don't slip 싶다 in. "I hope I go to Korea" is just 가면 좋겠어요. Adding 싶다 doubles the wanting and sounds off. Keep 가고 싶어요 for a plain "I want to go."`}}},{kind:"drill",prompt:"I hope this test is easy.",sentence:"이번 시험이 쉬웠___.",options:[{text:"이면 좋겠어요",ok:!1},{text:"으면 좋겠어요",ok:!0}],explanation:"The -었으면 form here makes the hope feel stronger, even though the test hasn't happened yet."},{kind:"drill",prompt:"I wish our place were closer to school.",sentence:"우리 집이 학교에서 가까웠___.",options:[{text:"이면 좋겠어요",ok:!1},{text:"으면 좋겠어요",ok:!0}],explanation:"A wish about how things are now; 가깝다 is ㅂ-irregular, so 가까웠으면."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I hope the weather's nice tomorrow."`,tokens:["내일","날씨가","좋으면","좋겠어요."],correct:"내일 날씨가 좋으면 좋겠어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I wish I had a little more time."',tokens:["시간이","좀","더","있으면","좋겠어요."],correct:"시간이 좀 더 있으면 좋겠어요.",explanation:""}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b4",chapterId:"chapter-40",index:3},{kind:"words",title:"단어 Words 3 · 아직~",cards:[{kind:"guess",word:{ko:"아직",romanization:"ajik",en:"still; yet",pos:"adverb",nuance:"아직 covers both 'still' and 'not yet', and which one surfaces depends on polarity: with a POSITIVE verb it means 'still' (아직 자요 'still sleeping'), and with a NEGATIVE verb it means 'not yet' (아직 안 잤어요 'haven't slept yet'). It is the natural counterpart to 벌써/이미 — 아직 안 끝났어요 ('not finished yet') is the mirror of 벌써 끝났어요 ('already finished'). It often rides with the ongoing form -고 있다 to stress an action in progress (아직 자고 있어요 'still sleeping right now') and shows up in fixed phrases like 아직 멀었어요 ('still a long way off'). Register-neutral. The English-speaker pitfall is the 아직/벌써 confusion and the negation logic: because English 'yet' lives in questions/negatives, learners forget that Korean 아직 itself flips meaning with the verb's polarity — pair 아직 with 안/못 to say 'not yet', and use it with a plain positive verb to say 'still'."},sentence:{ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"아직",options:["still; yet","carefully; cautiously","probably"],note:"Linked to dictionary card word-ext-285."},{kind:"guess",word:{ko:"회의",romanization:"hoeui",en:"meeting",pos:"noun",nuance:"회의 (漢字 會議, 會 'gather' + 議 'discuss') is a formal, work-style meeting where people gather to discuss and decide something — a board meeting, a team sync, a planning session. The near-synonym learners reach for is 모임, but 모임 is a social get-together (a dinner, a club, friends meeting up) with no agenda, so calling drinks with friends a 회의 sounds robotic; conversely calling a budget review a 모임 sounds too loose. It pairs naturally with 회의를 하다 (hold), 회의에 들어가다 (go into), 회의가 길어지다 (run long). The English-speaker pitfall is the particle: you are *in* a meeting as a location, so the action takes 회의에서, but you *enter* a meeting with 회의에 들어가다 — and never confuse 회의 with the look-alike 회사 (company) or 회비 (membership fee)."},sentence:{ko:"아직 회의 중일걸요.",en:"They are probably still in a meeting."},target:"회의",options:["meeting","opinion","burden; pressure"],note:"Linked to dictionary card word-ext-121."},{kind:"guess",word:{ko:"메시지",romanization:"mesiji",en:"message",pos:"noun",nuance:"메시지 is the loanword from English 'message' and covers chat/app messages broadly (a KakaoTalk message, a DM); the everyday near-synonym 문자 (literally 文字 'letters/characters') specifically means an SMS text, so '문자 보내' = 'text me' while '메시지' is the wider term. There's also 카톡, the verb-able brand shorthand for a KakaoTalk message, used constantly in real life (카톡 보낼게 'I'll Kakao you'). The English-speaker pitfall is twofold: first, the recipient is marked with 한테/에게 ('to a person'), not the English bare object — 친구한테 메시지를 보내다, where 친구한테 = 'to my friend' and 메시지를 is the thing sent; second, the message arriving uses intransitive 오다 with 이/가 (메시지가 오다), but you sending it uses 보내다 with 을/를 (메시지를 보내다). Don't carry the English 'send him a message' double-object pattern straight over."},sentence:{ko:"메시지를 남겨 두면 좋겠어요.",en:"It would be good to leave a message."},target:"메시지",options:["burden; pressure","message","meeting"],note:"Linked to dictionary card word-ext-167."},{kind:"guess",word:{ko:"퇴근하다",romanization:"toegeunhada",en:"to leave work",pos:"verb",nuance:"퇴근하다 is Sino-Korean 退勤 — 退 'withdraw/retreat' + 勤 'duty' — literally 'withdraw from your duty', i.e. finish the workday and head home. It is the precise mirror of 출근하다 (出勤). Don't confuse it with 끝나다 'to end' or 쉬다 'to rest': 퇴근하다 specifically means YOU leave the workplace, whereas 일이 끝나다 means the work is finished and 쉬다 means to take a break. As a noun+하다 verb it conjugates entirely on 하다: 퇴근해요, 퇴근했어요, formal 퇴근합니다. The English-speaker pitfall is the same family of splits — the negative is 퇴근 안 해요 and the impossible form 퇴근 못 해요, never 안 퇴근해요. A second trap: English 'get off work' tempts learners to invent a particle, but 퇴근하다 takes no object at all; the time is enough — 여섯 시에 퇴근해요. Beware the very common slang 칼퇴근(하다), 'knife clock-out', meaning you leave at the exact end time without a second of overtime."},sentence:{ko:"이미 퇴근했을 수도 있어요.",en:"They may have already left work."},target:"퇴근했",options:["to guess; to infer","probably; I think...","to leave work"],note:"Linked to dictionary card word-verb-485."},{kind:"guess",word:{ko:"물어보다",romanization:"mureoboda",en:"to ask; to ask and find out",pos:"verb phrase",nuance:"묻다 is the dictionary/base verb. 물어보다 is often the natural spoken choice for asking someone."},sentence:{ko:"확실하지 않으니까 조심스럽게 물어볼게요.",en:"Since I am not sure, I will ask carefully."},target:"물어볼",options:["probably; I think...","to ask; to ask and find out","I hope; it would be good if..."],note:"Linked to dictionary card word-ext-ch37-mureoboda."},{kind:"guess",word:{ko:"가능성",romanization:"ganeungseong",en:"possibility; chance",pos:"noun",nuance:"가능성 is a noun, so it pairs with 있다, 없다, 높다, and 낮다. It is a little more formal than just saying -ㄹ지도 몰라요."},sentence:{ko:"그럴 가능성도 있는 것 같아요.",en:"I think there is also a possibility of that."},target:"가능성",options:["opinion","possibility; chance","burden; pressure"],note:"Linked to dictionary card word-ext-ch26-ganeungseong."},{kind:"guess",word:{ko:"추측하다",romanization:"chucheukhada",en:"to guess; to infer",pos:"verb",nuance:"추측하다 is more explicit than -나 봐요. In conversation, the pattern often does the work, and 추측하다 names the thinking process."},sentence:{ko:"확실하지 않을 때는 너무 단정하지 말고 조심스럽게 추측해요.",en:"When you are not sure, do not state it too firmly; guess carefully."},target:"추측해",options:["to leave work","to guess; to infer","probably; I think..."],note:"Linked to dictionary card word-ext-ch26-chucheukhada."},{kind:"payoff",line:{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting."},hl:"아직"}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b5",chapterId:"chapter-40",index:4},{kind:"pattern",title:"문법 Grammar · -겠-",cards:[{kind:"teach",name:"-겠-",sub:"Intention, a Good Guess, or a Set Polite Phrase",rows:[{when:'Intention (your own plan, "I")',add:"stem + -겠-",ex:"하다 → 하겠어요; 먹다 → 먹겠습니다"},{when:"Guess (about something you can see/know)",add:"stem + -겠-",ex:"맛있다 → 맛있겠어요; 춥다 → 춥겠어요"},{when:"Guess about the past",add:"-았/었겠-",ex:"힘들다 → 힘들었겠어요"},{when:"Set polite phrases",add:"fixed forms",ex:"알겠어요 (got it); 모르겠어요 (I don't know); 잘 먹겠습니다"},{when:"Noun + guess",add:"N(이)겠-",ex:"학생 → 학생이겠어요"}],examples:[{ko:"제가 내일 다시 오겠습니다.",en:"I'll come back tomorrow.",romanization:"jega naeil dasi ogesseumnida.",note:"Your own plan; -겠습니다 sounds firm and polite, common when serving someone or in formal speech."},{ko:"이 음식 정말 맛있겠어요!",en:"This food looks so good!",romanization:"i eumsik jeongmal masitgesseoyo!",note:"A guess from what you see — you haven't tasted it yet, but you can tell it must be good."}],more:{func:`-겠- does three everyday jobs: stating your own plan ("I'll..."), making a guess about a situation ("that must be..."), and forming a few set polite phrases. You read which one it is from the context and the subject.`,funcLead:`-겠- does three everyday jobs: stating your own plan ("I'll..."), making a guess about a situation ("that must be..."), and forming a few set polite phrases.`,keyPoint:{label:"Intention -겠- vs. Guess -겠-",body:`With "I" as the subject and an action verb, -겠- usually means a plan ("I'll"). With someone else, or with an adjective describing a situation, it means a guess ("must be / looks like"). The subject and the kind of verb tell you which. The polite "future" feel of -겠- in set phrases comes later.`},pronunciation:"-겠- tenses the next consonant: 먹겠어요 → [먹께써요], 맛있겠어요 → [마싣께써요].",pitfall:{wrong:"그 사람 학생이에요? — said as 그 사람 학생이겠어요?",right:"그 사람 학생이에요?",explanation:`Don't use -겠- for a plain yes/no question. -겠- adds "must be / I'm guessing," so 학생이겠어요? asks "I suppose he's a student?" To simply ask whether someone is a student, use 학생이에요?`}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'll come back tomorrow."`,tokens:["제가","내일","다시","오겠습니다."],correct:"제가 내일 다시 오겠습니다.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This food looks so good!"',tokens:["이","음식","정말","맛있겠어요!"],correct:"이 음식 정말 맛있겠어요!",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"그 사람 학생이에요? — said as 그 사람 학생이겠어요?",ok:!1},{text:"그 사람 학생이에요?",ok:!0}],explanation:`Don't use -겠- for a plain yes/no question. -겠- adds "must be / I'm guessing," so 학생이겠어요? asks "I suppose he's a student?" To simply ask whether someone is a student, use 학생이에요?`}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b6",chapterId:"chapter-40",index:5},{kind:"pattern",title:"문법 Grammar · -다면 / N(이)라면",cards:[{kind:"hunt",name:"-다면 / N(이)라면",sub:"If That Were the Case",lines:[{tokens:[{pre:"돈이",mid:"",post:"",hit:!1},{pre:"많",mid:"다면",post:"",hit:!0},{pre:"큰",mid:"",post:"",hit:!1},{pre:"집을",mid:"",post:"",hit:!1},{pre:"사고",mid:"",post:"",hit:!1},{pre:"싶어요.",mid:"",post:"",hit:!1}],ko:"돈이 많다면 큰 집을 사고 싶어요.",en:"If I had a lot of money, I'd want to buy a big house.",romanization:"doni mantamyeon keun jibeul sago sipeoyo."},{tokens:[{pre:"내가",mid:"",post:"",hit:!1},{pre:"너",mid:"라면",post:"",hit:!0},{pre:"그",mid:"",post:"",hit:!1},{pre:"사람한테",mid:"",post:"",hit:!1},{pre:"전화할",mid:"",post:"",hit:!1},{pre:"거예요.",mid:"",post:"",hit:!1}],ko:"내가 너라면 그 사람한테 전화할 거예요.",en:"If I were you, I'd call him.",romanization:"naega neoramyeon geu saramhante jeonhwahal geoyeyo."}],rule:{name:"-다면 / N(이)라면",rows:[{when:"Verb stem",add:"-ㄴ/는다면",ex:"가다 → 간다면; 먹다 → 먹는다면"},{when:"Adjective stem",add:"-다면",ex:"바쁘다 → 바쁘다면; 많다 → 많다면"},{when:"Past (any stem)",add:"-았/었다면",ex:"왔다면; 먹었다면"},{when:"Noun ending in a consonant",add:"N이라면",ex:"학생 → 학생이라면"},{when:"Noun ending in a vowel",add:"N라면",ex:"부자 → 부자라면; 의사 → 의사라면"}]},more:{func:`Use -다면 / N(이)라면 to set up a "what if" — an imagined or supposed situation, often one you don't really expect or that isn't true right now: "if (let's say)...".`,funcLead:`Use -다면 / N(이)라면 to set up a "what if" — an imagined or supposed situation, often one you don't really expect or that isn't true right now: "if (let's say)...".`,keyPoint:{label:"-다면 vs. -(으)면",body:'-(으)면 is the all-purpose "if/when," fine for real, likely things (밥 먹으면 = when/if I eat). -다면 puts more weight on "just supposing," so it suits imagined or unlikely cases. For everyday real conditions, -(으)면 is still your default. The full -았/었다면 "would have" pattern is explored more later.'},pronunciation:"많다면 sounds like [만타면]: the ㅎ in 많 blends with the following ㄷ into an aspirated [ㅌ].",pitfall:{wrong:"학생다면 할인을 받아요.",right:"학생이라면 할인을 받아요.",explanation:"After a noun, you can't just add -다면. Nouns use (이)라면: 학생이라면 (if you're a student), 부자라면 (if you're rich). Only verb and adjective stems take -다면 directly."}}},{kind:"drill",prompt:"If you happen to have time, let's catch a movie.",sentence:"시간이 있___ 같이 영화 봐요.",options:[{text:"다면",ok:!0},{text:"라면",ok:!1}],explanation:"있다 takes -다면; here it frames a supposed condition before a suggestion."},{kind:"drill",prompt:"If we'd left early back then, we wouldn't have been late.",sentence:"그때 일찍 출발했___ 안 늦었을 거예요.",options:[{text:"라면",ok:!1},{text:"으ㄹ걸요",ok:!1},{text:"다면",ok:!0}],explanation:"-았/었다면 looks back at something that didn't happen — a regret about the past."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If I had a lot of money, I'd want to buy a big house."`,tokens:["돈이","많다면","큰","집을","사고","싶어요."],correct:"돈이 많다면 큰 집을 사고 싶어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If I were you, I'd call him." (내가 시작 · Start with 내가.)`,tokens:["내가","너라면","그","사람한테","전화할","거예요."],correct:"내가 너라면 그 사람한테 전화할 거예요.",explanation:""}],canDo:"Hedge and leave room with trailing -(으)ㄴ/는데요 and 아마 / 글쎄요",id:"chapter-40-b7",chapterId:"chapter-40",index:6},{kind:"pattern",title:"문법 Grammar · -(으)ㄴ/는데요",cards:[{kind:"hunt",name:"-(으)ㄴ/는데요",sub:"Softening and Leaving Room",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"매운",mid:"",post:"",hit:!1},{pre:"거",mid:"",post:"",hit:!1},{pre:"잘",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"먹",mid:"는데요",post:".",hit:!0}],ko:"저는 매운 거 잘 못 먹는데요.",en:"I'm not so good with spicy food, actually...",romanization:"jeoneun maeun geo jal mot meongneundeyo."},{tokens:[{pre:"어제는",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"왔",mid:"는데요",post:".",hit:!0}],ko:"어제는 비가 왔는데요.",en:"It rained yesterday, though...",romanization:"eojeneun biga watneundeyo."}],rule:{name:"-(으)ㄴ/는데요",rows:[{when:"Action verb (present)",add:"-는데요",ex:"가다 → 가는데요; 먹다 → 먹는데요"},{when:"Adjective, vowel stem (present)",add:"-ㄴ데요",ex:"바쁘다 → 바쁜데요; 크다 → 큰데요"},{when:"Adjective, consonant stem (present)",add:"-은데요",ex:"좋다 → 좋은데요; 작다 → 작은데요"},{when:"Past (any stem)",add:"-았/었는데요",ex:"가다 → 갔는데요; 먹다 → 먹었는데요"},{when:"Noun (present)",add:"N인데요",ex:"학생 → 학생인데요"}]},more:{func:`Ending a sentence with -(으)ㄴ/는데요 softens it. Instead of a hard statement, it sets something up and leaves the door open — for the other person to react, for a "but...," or for a gentle pushback. It's one of the most common ways Koreans avoid sounding too direct.`,funcLead:"Ending a sentence with -(으)ㄴ/는데요 softens it.",keyPoint:{label:"-(으)ㄴ/는데요 vs. a plain -아/어요 ending",body:`좀 바빠요 just states "I'm busy." 좀 바쁜데요 says the same thing but trails off, inviting the other person to fill in the rest — softer and less final. Use it to hedge, hint, or set up a contrast. Its longer use for connecting two clauses ("~는데, …") comes in a separate point.`},pronunciation:"In 먹는데요, the ㄱ before ㄴ turns nasal: it sounds like [멍는데요]. 좋은데요 sounds like [조은데요], with the ㅎ dropping out.",pitfall:{wrong:"저 지금 바쁜데요 그래서 못 가요.",right:"저 지금 바쁜데요. (and let the meaning land on its own)",explanation:`English speakers spell out the whole "so I can't go." The point of -(으)ㄴ/는데요 is to leave that part unsaid and let the listener get it. Tacking on the blunt conclusion undoes the softening the ending is there to create.`}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm not so good with spicy food, actually..."`,tokens:["저는","매운","거","잘","못","먹는데요."],correct:"저는 매운 거 잘 못 먹는데요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "It rained yesterday, though..."',tokens:["어제는","비가","왔는데요."],correct:"어제는 비가 왔는데요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저 지금 바쁜데요 그래서 못 가요.",ok:!1},{text:"저 지금 바쁜데요. (and let the meaning land on its own)",ok:!0}],explanation:`English speakers spell out the whole "so I can't go." The point of -(으)ㄴ/는데요 is to leave that part unsaid and let the listener get it. Tacking on the blunt conclusion undoes the softening the ending is there to create.`}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b8",chapterId:"chapter-40",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two coworkers need to contact someone, but they are not sure whether that person is still available.",lines:[{speaker:"민서",ko:"그분은 아직 회의 중일걸요.",en:"They are probably still in a meeting.",romanization:"geubuneun ajik hoeui jungilgeolyo."},{speaker:"지훈",ko:"글쎄요, 이미 퇴근했을 수도 있어요.",en:"Hmm, they may have already left work.",romanization:"geulsseyo, imi toegeunhaesseul sudo isseoyo."},{speaker:"민서",ko:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",en:"If they already left, it would be good to leave a message.",romanization:"hoksi imi nagatdamyeon mesijireul namgyeo dumyeon jokesseoyo."},{speaker:"지훈",ko:"네, 확실하지 않으니까 조심스럽게 물어볼게요.",en:"Yes, since I am not sure, I will ask carefully.",romanization:"ne, hwaksilhaji aneunikka josimseureopge mureobolgeyo."},{speaker:"민서",ko:"제 생각에는 먼저 물어보는 게 좋을 것 같아요.",en:"In my opinion, I think it would be good to ask first.",romanization:"je saenggageneun meonjeo mureoboneun ge joeul geot gatayo."}]},{kind:"order",prompt:"Build: 'If that is the case, let's ask first.'",tokens:["그렇다면","먼저 물어봐요"],correct:"그렇다면 먼저 물어봐요",explanation:"그렇다면 opens a hypothetical path from the previous idea. 먼저 물어봐요 gives the suggested next step."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"혹시 이미 나갔다면 메시지를 남겨 두면 좋겠어요.",options:[{text:"민서",ok:!0},{text:"지훈",ok:!1}],explanation:"If they already left, it would be good to leave a message."},{kind:"drill",prompt:'무엇이 들어갈까요? · "They are probably still in a meeting."',sentence:"그분은 아직 회의 중일___.",options:[{text:"좋겠어요",ok:!1},{text:"다면",ok:!1},{text:"걸요",ok:!0}],explanation:""}],canDo:"Offer a soft but confident guess with -(으)ㄹ걸요 (괜찮을걸요)",id:"chapter-40-b9",chapterId:"chapter-40",index:8},{kind:"reading",title:"읽기 Reading · 확실하지 않을 때 말하는 법",cards:[{kind:"read",title:"확실하지 않을 때 말하는 법",chunks:["회사 단톡방에서 누가 아직 회의 중인지, 이미 퇴근했는지 모를 때가 있어요. 이때 한국어는 한 가지 'I think'만 쓰지 않아요. 기억이나 상황을 보고 짐작하면 '아직 회의 중일걸요'라고 말할 수 있고, 가능성을 열어 두고 싶으면 '이미 나갔다면 메시지를 남겨 두면 좋겠어요'처럼 말해요.","내 의견을 조심스럽게 말할 때는 '제 생각에는 먼저 물어보는 게 좋을 것 같아요'가 자연스러워요. 중요한 건 약하게 말하는 것이 아니라, 내가 아는 정도에 맞게 문장을 고르는 거예요."],translation:"In a work chat, you may not know whether someone is still in a meeting or already left work. Korean does not use one single 'I think' for every case. Use -ㄹ걸요 for a hunch, -다면 for a hypothetical, 좋겠어요 for a hoped-for or gentle next step, and 것 같아요 to soften your own opinion. The point is not to be weak; it is to match the sentence to how much you actually know.",qas:[{q:"회의 중인지 확실하지 않을 때 어떤 표현을 쓸 수 있어요?",a:"아직 회의 중일걸요."},{q:"이미 나갔을 가능성을 열어 둘 때 어떤 연결을 썼어요?",a:"이미 나갔다면"},{q:"내 의견을 조심스럽게 말할 때 왜 것 같아요를 써요?",a:"의견을 너무 단정적으로 들리지 않게 부드럽게 만들기 위해서예요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"회사 단톡방에서 누가 아직 회의 중인지, ___ 퇴근했는지 모를 때가 있어요.",options:[{text:"아마",ok:!1},{text:"혹시",ok:!1},{text:"이미",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"기억이나 상황을 보고 짐작하면 '아직 회의 중일걸요'라고 말할 수 있고, 가능성을 열어 두고 싶으면 '이미 나갔다면 메시지를 남겨 두면 ___'처럼 말해요.",options:[{text:"아마",ok:!1},{text:"글쎄요",ok:!1},{text:"좋겠어요",ok:!0}],explanation:""}],canDo:"Express a hope or wish with -(으)면 좋겠어요 (괜찮으면 좋겠어요)",id:"chapter-40-b10",chapterId:"chapter-40",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence gives a soft but fairly confident guess?",sentence:null,options:[{text:"아직 회의 중일걸요.",ok:!0},{text:"아직 회의 중이라면요.",ok:!1},{text:"아직 회의 중이면 좋겠어요.",ok:!1}],explanation:"-ㄹ걸요 marks a careful guess based on what the speaker thinks."},{kind:"drill",prompt:"Which sentence opens a hypothetical before suggesting the next step?",sentence:null,options:[{text:"이미 나갔다면 메시지를 남겨 두면 좋겠어요.",ok:!0},{text:"이미 나갔을걸요 메시지를 남겨요.",ok:!1},{text:"이미 나간 것 같아요 회의 중이에요.",ok:!1}],explanation:"-다면 sets up the condition, and -으면 좋겠어요 gives a gentle suggestion."},{kind:"drill",prompt:"Which reply is the standard, fixed way to say you understood a request?",sentence:null,options:[{text:"네, 알겠어요.",ok:!0},{text:"네, 알 것 같아요.",ok:!1},{text:"네, 알걸요.",ok:!1}],explanation:"알겠어요 is a set response meaning 'I understand / okay.'"},{kind:"drill",prompt:"제 생각___ 먼저 물어보는 게 좋아요. (In my opinion...)",sentence:null,options:[{text:"에는",ok:!0},{text:"을",ok:!1},{text:"에서",ok:!1}],explanation:"제 생각에는 frames the statement as your opinion. 을 and 에서 do not make the opinion-frame expression."},{kind:"drill",prompt:"Which response is the cautious “Hmm, I am not sure”?",sentence:null,options:[{text:"글쎄요.",ok:!0},{text:"좋겠어요.",ok:!1},{text:"그렇다면요.",ok:!1}],explanation:"글쎄요 is the natural cautious hesitation. 좋겠어요 is a wish, and 그렇다면요 depends on a hypothetical."}],canDo:"Read -겠- as intention, a guess, or a set phrase (알 수 있겠죠)",id:"chapter-40-b11",chapterId:"chapter-40",index:10}]},{id:"chapter-41",number:41,title:"ㅂ Irregular: 춥다 → 추워요 · ㄷ Irregular: 듣다 → 들어요",goal:"Match high-frequency dictionary forms with their real polite forms.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 춥다~",cards:[{kind:"guess",word:{ko:"춥다",romanization:"chupda",en:"cold (weather)",pos:"adjective",nuance:"춥다 is the ㅂ-irregular adjective for ambient air being unpleasantly cold — winter, a chilly room, a draft. The crucial contrast for English speakers is 춥다 vs 차갑다: 춥다 is how the WEATHER/AIR feels to your whole body, while 차갑다 is how a cold OBJECT feels to your hand (차가운 물 'cold water', 차가운 손 'cold hands'). Never say 추운 물 — water is 차갑다. As a ㅂ-irregular it conjugates 춥다 → 추워요 → 추운 → 추우니까 → 추워서, so writing 춥어요 or 춥은 (the regular pattern) is the classic beginner slip. It is register-neutral and universal. The matching noun is 추위, and 추위를 타다 means 'to be cold-sensitive,' the exact mirror of 더위를 타다."},sentence:{ko:"오늘 너무 추워요.",en:"It is so cold today."},target:"추워",options:["to be spicy","cold (weather)","to be difficult"],note:"Linked to dictionary card word-ext-266."},{kind:"guess",word:{ko:"덥다",romanization:"deopda",en:"hot (weather)",pos:"adjective",nuance:"덥다 is the ㅂ-irregular adjective for FELT air temperature being unpleasantly high — hot weather, a stuffy room, a sweaty body. The key English-speaker trap is that English 'hot' covers four different Korean words: use 덥다 ONLY for ambient air/weather. A hot object you touch is 뜨겁다 (뜨거운 커피, never 더운 커피), spicy food is 맵다, and pleasant warmth is 따뜻하다. Because it is ㅂ-irregular, the ㅂ becomes 우 before a vowel: 덥다 → 더워요(polite) → 더운(modifier) → 더우니까(reason) → 더워서. Beginners constantly write 덥어요 or 덥은 by treating it as regular — that is the number-one error. It is neutral in register and used by everyone; the related noun is 더위 ('the heat'), and people say 더위를 먹다 to mean 'suffer heatstroke.'"},sentence:{ko:"어제는 정말 더웠어요.",en:"Yesterday was really hot."},target:"더웠",options:["hot (weather)","to be spicy","to be difficult"],note:"Linked to dictionary card word-ext-265."},{kind:"guess",word:{ko:"맵다",romanization:"maepda",en:"to be spicy",pos:"adjective",nuance:"맵다 is ㅂ irregular: 매워요, 매운 음식. It is especially useful for food restrictions, because 매운 음식은 못 먹어요 is a survival sentence."},sentence:{ko:"이 떡볶이는 많이 매워요.",en:"This tteokbokki is very spicy."},target:"매워",options:["cold (weather)","to be spicy","hot (weather)"],note:"Linked to dictionary card word-adjective-035."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"이 문제는 너무 어려워요.",en:"This problem is too difficult."},target:"어려워",options:["to be difficult","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-adjective-037."},{kind:"guess",word:{ko:"쉽다",romanization:"swipda",en:"to be easy",pos:"adjective",nuance:"쉽다 is ㅂ irregular: 쉬워요, 쉬운. It helps learners talk about difficulty level, but the opposite 어렵다 is often needed in the same lesson."},sentence:{ko:"생각보다 쉬워요.",en:"It is easier than I thought."},target:"쉬워",options:["to be easy","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-adjective-036."},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"저는 아침마다 음악을 들어요.",en:"I listen to music every morning."},target:"들어",options:["to walk","to ask","to listen"],note:"Linked to dictionary card word-verb-013."}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b1",chapterId:"chapter-41",index:0},{kind:"pattern",title:"문법 Grammar · ㅂ Irregular: 춥다 → 추워요",cards:[{kind:"teach",name:"ㅂ Irregular: 춥다 → 추워요",sub:"",rows:[{when:"Stem ends in ㅂ, before a vowel ending (-아/어요, -았/었-, -으니까)",add:"ㅂ → 우, then add 어요 (우+어 = 워)",ex:"춥다 → 추+우+어요 → 추워요"},{when:"Stem ends in ㅂ, before a consonant ending (-고, -지만, -습니다)",add:"no change, ㅂ stays",ex:"춥다 → 춥고, 춥지만"},{when:"돕다 / 곱다 only",add:"ㅂ → 오 (오+아 = 와)",ex:"돕다 → 도+오+아요 → 도와요"}],examples:[{ko:"오늘 날씨가 너무 추워요.",en:"The weather is so cold today.",romanization:"oneul nalssiga neomu chuwoyo.",note:"춥다 + 아/어요: ㅂ turns to 우, then 우+어 joins into 워."},{ko:"이 가방은 정말 가벼워요.",en:"This bag is really light.",romanization:"i gabangeun jeongmal gabyeowoyo.",note:"가볍다 follows the same ㅂ → 우 → 워 pattern."}],more:{func:"A lot of describing words (and a few action words) whose stem ends in ㅂ change that ㅂ to 우 when a vowel ending comes next. That's why 춥다 (to be cold) becomes 추워요, not 춥어요.",funcLead:"A lot of describing words (and a few action words) whose stem ends in ㅂ change that ㅂ to 우 when a vowel ending comes next.",keyPoint:{label:"Vowel ending vs consonant ending",body:"The ㅂ only changes before a vowel: 춥다 → 추워요 (vowel) but 춥다 → 춥고 (consonant). Almost all ㅂ-irregular words use 우; only 돕다 and 곱다 use 오. For now, just learn 추워요 as a set phrase and you'll see the pattern."},pronunciation:"추워요 is said smoothly as [추워요]. The 우+어 → 워 is a real spelling change, not just a sound, so you actually write 워.",pitfall:{wrong:"날씨가 춥어요.",right:"날씨가 추워요.",explanation:"It feels natural to just add the ending and say 춥어요, but ㅂ-irregular stems change the ㅂ to 우 before a vowel, giving 추워요."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The weather is so cold today."',tokens:["오늘","날씨가","너무","추워요."],correct:"오늘 날씨가 너무 추워요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This bag is really light."',tokens:["이","가방은","정말","가벼워요."],correct:"이 가방은 정말 가벼워요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"날씨가 춥어요.",ok:!1},{text:"날씨가 추워요.",ok:!0}],explanation:"It feels natural to just add the ending and say 춥어요, but ㅂ-irregular stems change the ㅂ to 우 before a vowel, giving 추워요."}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b2",chapterId:"chapter-41",index:1},{kind:"words",title:"단어 Words 2 · 걷다~",cards:[{kind:"guess",word:{ko:"걷다",romanization:"geotda",en:"to walk",pos:"verb",nuance:"걷다 means to walk on foot and is a ㄷ irregular verb: before a vowel ending the final ㄷ softens to ㄹ, so the 요-form is 걸어요 (not 걷어요) and the past is 걸었어요. Before a consonant ending the ㄷ stays put, so the formal form remains 걷습니다 and you say 걷지 마세요, 걷고 싶어요. The nearest relative is 산책하다 ('take a stroll'): 걷다 is the raw act of walking anywhere, while 산책하다 implies a leisurely walk for pleasure, so 'I walk to work' is 걸어서 출근해요, never 산책해서 출근해요. The trap for English speakers is that 걷다 doesn't take an object the way 'walk the dog' does — Korean uses 산책시키다 for that, and the path you walk takes 을/를 (공원을 걸어요), so don't reach for 에. Also remember 걸어서 ('on foot') is one fixed chunk for describing how you travel."},sentence:{ko:"퇴근하고 공원을 걸어요.",en:"I walk in the park after work."},target:"걸어",options:["to walk","to listen","to ask"],note:"Linked to dictionary card word-verb-400."},{kind:"guess",word:{ko:"묻다",romanization:"mutda",en:"to ask",pos:"verb",nuance:"묻다 means 'to ask (a question / inquire)' and takes the object marker 을/를 for the thing asked about: 길을 물어요. It is a ㄷ-irregular verb: before a vowel ending the stem ㄷ changes to ㄹ, giving 물어요 and 물었어요 and 물을 거예요, but before consonant endings the ㄷ stays — 묻습니다, 묻고, 묻지 마세요. The person you ask takes 에게/한테, or honorific 께 for someone of higher status: 선생님께 물어요. In real speech Koreans far more often say 물어보다 ('ask and see', literally 묻다 + 보다), which sounds softer and more tentative than the bare, slightly abrupt 묻다 — so 물어보세요 ('please ask') is the natural request, not 물으세요. Two contrasts: do not confuse this 묻다 with the homograph 묻다 meaning 'to bury' (regular: 땅에 묻다), and distinguish 묻다 ('ask a question') from 부탁하다 ('to request a favor'). The English-speaker pitfall is keeping the ㄷ before a vowel to say 묻어요 (which actually reads as the 'bury' verb) instead of the irregular 물어요."},sentence:{ko:"모르면 선생님께 물어봐요.",en:"If you do not know, ask the teacher."},target:"물어",options:["to listen","to walk","to ask"],note:"Linked to dictionary card word-verb-353."},{kind:"guess",word:{ko:"낫다",romanization:"natda",en:"to heal; to get better",pos:"verb",nuance:"낫다 means an illness or wound heals, and it is a ㅅ-irregular verb: the ㅅ disappears before a vowel (나아요, 나았어요, 나을, 나으세요) but stays before a consonant (낫습니다, 낫고, 낫지). It is intransitive — the cold or the cut is the subject (감기가 나았어요, 상처가 나았어요) — so you never 'heal something' with it; for that you'd use 치료하다 (to treat) or 고치다 (to cure/fix). The big trap for everyone, native and learner alike, is the homophone cluster: 낫다 'heal', 낳다 'give birth', and 났다 (from 나다, 'broke out/occurred') all sound like [낟따] but mean totally different things, so 나았어요 (got better) must never be spelled 낳았어요 (gave birth). Note 낫다 also has a second meaning, 'to be better/preferable' (이게 더 나아요 = this one's better), which shares the exact same conjugation. It collocates with 빨리/금방/곧 낫다 (heal fast/soon) and 다 낫다 (fully heal)."},sentence:{ko:"감기가 다 나았어요.",en:"My cold got completely better."},target:"나았",options:["to heal; to get better","to listen","to walk"],note:"Linked to dictionary card word-verb-053."},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"저는 그 사람 이름을 몰라요.",en:"I do not know that person's name."},target:"몰라",options:["to listen","to walk","to not know"],note:"Linked to dictionary card word-verb-345."},{kind:"guess",word:{ko:"다르다",romanization:"dareuda",en:"to be different",pos:"adjective",nuance:"다르다 is the antonym of 같다 and conjugates as a 르-irregular: the stem 다르 + 아요 doubles the ㄹ and drops 으 to give 달라요 (never 다라요); past is 달랐어요. The pre-noun form 다른 is one of the most-used words in Korean and covers both 'different' and 'another' (다른 색 = 'a different/another colour'). The dangerous trap for English speakers is 틀리다, which means 'to be wrong / incorrect' — even native speakers loosely say 틀리다 for 'different' in speech, but in correct Korean 답이 틀리다 = 'the answer is wrong' while 답이 다르다 = 'the answer is different'. Mixing them can imply someone is mistaken when you only meant they differ, which can sound rude. Pair 다르다 with 하고/와 for the thing compared: 작년하고 달라요 ('it's different from last year')."},sentence:{ko:"두 색깔이 조금 달라요.",en:"The two colors are a little different."},target:"달라",options:["to be different","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1244."},{kind:"guess",word:{ko:"부르다",romanization:"bureuda",en:"to call",pos:"verb",nuance:"부르다 chiefly means to call/summon someone to come (택시를 부르다, 친구를 부르다), to call out a name (이름을 부르다), and — a key idiom — to sing (노래를 부르다, the standard phrase, not 노래를 하다). Don't confuse it with 전화하다, which is 'to phone': 친구를 불러요 means call your friend over to where you are, while 친구한테 전화해요 means ring them up. It's a textbook 르-irregular: before an 아/어 ending the final ㅡ drops and an extra ㄹ appears, so 부르 + 어요 → 불러요 and past → 불렀어요, but before consonant endings it stays whole (부르고, 부를 거예요, 부릅니다). Two traps: first, learners say 부르어요 — wrong, it must be 불러요. Second, beware the homonym 부르다 'to be full' (배가 부르다), a completely different adjective; 배가 불러요 means 'I'm full', not 'the stomach calls'. Also note honorific contexts: to summon a superior you'd soften with 모시다 ('escort/bring respectfully') rather than bluntly 부르다."},sentence:{ko:"제 이름을 불러 주세요.",en:"Please call my name."},target:"불러",options:["to listen","to call","to walk"],note:"Linked to dictionary card word-verb-477."},{kind:"payoff",line:{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요."},hl:"모르"}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b3",chapterId:"chapter-41",index:2},{kind:"pattern",title:"문법 Grammar · ㄷ Irregular: 듣다 → 들어요",cards:[{kind:"teach",name:"ㄷ Irregular: 듣다 → 들어요",sub:"",rows:[{when:"ㄷ-irregular stem + vowel ending (-아/어요, -았/었-, -으면)",add:"ㄷ → ㄹ, then add 어요",ex:"듣다 → 들+어요 → 들어요"},{when:"ㄷ-irregular stem + consonant ending (-고, -지만, -습니다)",add:"no change, ㄷ stays",ex:"듣다 → 듣고, 듣습니다"},{when:"Regular ㄷ verbs (받다, 닫다, 믿다)",add:"ㄷ never changes",ex:"받다 → 받아요 (not 발아요)"}],examples:[{ko:"저는 음악을 자주 들어요.",en:"I listen to music a lot.",romanization:"jeoneun eumageul jaju deureoyo.",note:"듣다 + 아/어요: ㄷ becomes ㄹ before the vowel, so 들어요."},{ko:"매일 학교까지 걸어요.",en:"I walk to school every day.",romanization:"maeil hakgyokkaji georeoyo.",note:"걷다 (to walk) is ㄷ-irregular: 걷 → 걸 → 걸어요."}],more:{func:"A small group of action words whose stem ends in ㄷ change that ㄷ to ㄹ when a vowel ending follows. So 듣다 (to hear/listen) becomes 들어요, not 듣어요.",funcLead:"A small group of action words whose stem ends in ㄷ change that ㄷ to ㄹ when a vowel ending follows.",keyPoint:{label:"Not every ㄷ verb is irregular",body:"Only a few verbs change (듣다, 걷다, 묻다 'ask', 싣다 'load'). Everyday verbs like 받다 (get), 닫다 (close), 믿다 (believe) keep their ㄷ: 받아요, 닫아요, 믿어요. You just have to remember which ones are irregular."},pronunciation:"들어요 links as [드러요] — the ㄹ slides into the next syllable. Don't worry about the rule mid-conversation; learn 들어요 as a chunk.",pitfall:{wrong:"음악을 듣어요.",right:"음악을 들어요.",explanation:"It's tempting to keep the ㄷ and say 듣어요, but ㄷ-irregular verbs change ㄷ to ㄹ before a vowel ending, giving 들어요."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I listen to music a lot."',tokens:["저는","음악을","자주","들어요."],correct:"저는 음악을 자주 들어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I walk to school every day." (매일 시작 · Start with 매일.)',tokens:["매일","학교까지","걸어요."],correct:"매일 학교까지 걸어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"음악을 들어요.",ok:!0},{text:"음악을 듣어요.",ok:!1}],explanation:"It's tempting to keep the ㄷ and say 듣어요, but ㄷ-irregular verbs change ㄷ to ㄹ before a vowel ending, giving 들어요."}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b4",chapterId:"chapter-41",index:3},{kind:"words",title:"단어 Words 3 · 빨갛다~",cards:[{kind:"guess",word:{ko:"빨갛다",romanization:"ppalgata",en:"to be red",pos:"adjective",nuance:"빨갛다 is the vivid, pure 'red' of an apple, a stop light, or a blushing face. Among red words, contrast it with 붉다, which is the more literary, darker 'reddish/crimson' used for blood, sunsets, and emotion (붉은 노을), while 빨갛다 is the bright everyday red a child would point at. As an adjective it describes a STATE, so the thing that is red takes 이/가 (얼굴이 빨개요), never 을/를. The biggest trap for English speakers is the ㅎ-irregular: the stem-final ㅎ vanishes AND the vowel fuses, so it is never 빨갛아요 but 빨개요, and the noun-modifying form is 빨간 (빨간 사과), not 빨갛은. To say something 'turns red,' use 빨개지다, because 빨갛다 alone is a static quality, not a change. Note 빨간색 is the noun 'the color red.'"},sentence:{ko:"얼굴이 빨개요.",en:"Your face is red."},target:"빨개",options:["to be red","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1207."},{kind:"guess",word:{ko:"파랗다",romanization:"parata",en:"to be blue",pos:"adjective",nuance:"파랗다 is the bright blue of a clear sky and the sea, and in Korean it famously also covers what English calls 'green' for traffic lights and fresh leaves (파란불 'the green light,' 파란 잔디 'green grass') — a real surprise for learners. The neighboring word 푸르다 is more poetic and leans 'verdant/azure,' used for 푸른 산 'green mountains' and 푸른 하늘 in songs, while 파랗다 is the plain everyday blue. Being an adjective, the blue thing takes 이/가 (하늘이 파래요), not 을/를. The ㅎ-irregular is the key pitfall: never 파랗아요 but 파래요, and the modifier is 파란 (파란 바다), not 파랗은. Use 파래지다 for 'turn blue,' and 파란색 for the noun 'the color blue.'"},sentence:{ko:"오늘 하늘이 파래요.",en:"The sky is blue today."},target:"파래",options:["cold (weather)","to be blue","hot (weather)"],note:"Linked to dictionary card word-ext-1208."},{kind:"guess",word:{ko:"노랗다",romanization:"norata",en:"to be yellow",pos:"adjective",nuance:"노랗다 is the cheerful pure yellow of a banana, a chick, or a school bus. Korean color adjectives like this come in a 'bright vs dark' vowel-harmony pair: 노랗다 (bright, with ㅗ/ㅏ) feels light and vivid, while its darker partner 누렇다 (with ㅜ/ㅓ) means a dull, dingy, faded yellow like old paper or unhealthy skin — choosing the wrong one changes the whole feeling. As an adjective it takes 이/가 on the yellow thing (잎이 노래요), not 을/를. Watch the ㅎ-irregular: it is 노래요, never 노랗아요, and the modifier is 노란 (노란 우산), not 노랗은. There is also a vivid set phrase 눈앞이 노래지다 'to feel faint/hopeless,' literally 'the front of the eyes turns yellow.' The noun is 노란색."},sentence:{ko:"바나나가 노래요.",en:"The banana is yellow."},target:"노래",options:["to be yellow","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1209."},{kind:"guess",word:{ko:"어떻다",romanization:"eotteota",en:"to be how",pos:"adjective",nuance:"어떻다 is the question-adjective 'to be how / to be what-like,' the root behind a whole family Koreans use constantly. Learn its three faces: 어때(요)? = 'How is it? / How about it?' (asking a state or making a soft suggestion — 이거 어때요?), 어떤 = the modifier 'what kind of' before a noun (어떤 음악 'what kind of music'), and 어떻게 = the adverb 'how / in what way' for asking method (어떻게 해요? 'how do you do it?'). Do not confuse 어떻다 with 어떡하다, the contraction of 어떻게 하다 'to do how,' which gives the very common cry 어떡해! 'what do I do?!' As an irregular ㅎ adjective, the polite/question form is 어때요, never 어떻아요, and the past is 어땠어요. The single most frequent learner error is choosing the wrong family member — using 어떤 where 어떻게 is needed, or vice versa."},sentence:{ko:"이 방법은 어때요?",en:"How is this method?"},target:"어때",options:["to be how","cold (weather)","hot (weather)"],note:"Linked to dictionary card word-ext-1218."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"알다 means 'to know / be aware of / be acquainted with' and takes the object marker 을/를: 저 사람을 알아요. It is a ㄹ-irregular verb: the stem ㄹ drops before ㅂ, ㄴ, and the honorific ㅅ, giving 압니다 (not 알습니다) and 아세요 (not 알으세요), but the ㄹ stays before vowel endings, so the everyday polite form is 알아요. Two contrasts are essential. First, its opposite is not the negative 안 알아요 — that is wrong — but the separate verb 모르다, so 'I don't know' is 몰라요. Second, 알다 vs 알겠다: 알아요 claims knowledge you already hold ('I know that'), while 알겠어요 signals you have just understood or accepted something ('I see / got it / will do'), which is why a polite 'understood' is 알겠습니다, never 압니다. The English-speaker pitfall is twofold: forming 'don't know' as 안 알아요 instead of 몰라요, and keeping the ㄹ to say 알습니다 instead of 압니다."},sentence:{ko:"이 단어를 아세요?",en:"Do you know this word?"},target:"아세",options:["to know","to listen","to walk"],note:"Linked to dictionary card word-verb-344."},{kind:"guess",word:{ko:"살다",romanization:"salda",en:"to live",pos:"verb",nuance:"살다 means 'to live' in two senses — to reside somewhere and to be alive — and is a ㄹ-irregular verb. The stem ㄹ disappears before ㅂ, ㄴ, and the honorific 시, producing 삽니다 (not 살읍니다), 사세요 (not 살으세요), and 사니까; before vowel endings the ㄹ stays, so the polite present is 살아요. For where you live, the default particle is the static-location 에: 서울에 살아요. Interestingly, because living is an activity carried out over time, the dynamic-location 에서 is also acceptable and common, especially with hopes and experiences (한국에서 살고 싶어요) — this is one of the few cases where both 에 and 에서 work with the same verb. Contrast 살다 with 거주하다 (居住하다, Sino-Korean 'to reside'), a stiff, formal/written word used on official forms (거주지 'place of residence'); in speech you always say 살다. The English-speaker pitfall is keeping the ㄹ to say 살읍니다 instead of 삽니다, and reflexively choosing 에서 for every location when plain residence prefers 에."},sentence:{ko:"어디 사세요?",en:"Where do you live?"},target:"사세",options:["to live","to listen","to walk"],note:"Linked to dictionary card word-verb-346."},{kind:"payoff",line:{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요."},hl:"빨갛"}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b5",chapterId:"chapter-41",index:4},{kind:"pattern",title:"문법 Grammar · ㅅ Irregular: 낫다 → 나아요",cards:[{kind:"teach",name:"ㅅ Irregular: 낫다 → 나아요",sub:"",rows:[{when:"ㅅ-irregular stem + vowel ending (-아/어요, -았/었-, -으면)",add:"ㅅ drops; vowels stay separate (no joining)",ex:"낫다 → 나+아요 → 나아요"},{when:"ㅅ-irregular stem + consonant ending (-고, -지만, -습니다)",add:"no change, ㅅ stays",ex:"낫다 → 낫고, 낫습니다"},{when:"Regular ㅅ verbs (웃다, 씻다, 벗다)",add:"ㅅ never drops",ex:"웃다 → 웃어요 (not 우어요)"}],examples:[{ko:"감기가 다 나았어요.",en:"My cold is all better now.",romanization:"gamgiga da naasseoyo.",note:"낫다 → 나았어요; ㅅ drops but 나+았 stays as two parts, no joining."},{ko:"이 식당이 저 식당보다 나아요.",en:"This restaurant is better than that one.",romanization:"i sikdangi jeo sikdangboda naayo.",note:"낫다 'be better' → 나아요; the two ㅏ's stay separate, written 나아."}],more:{func:"Some action/describing words whose stem ends in ㅅ drop the ㅅ before a vowel ending — but unlike ㄷ and ㅂ, the two vowels do NOT join up. So 낫다 (to get better) becomes 나아요, keeping both vowels.",funcLead:"Some action/describing words whose stem ends in ㅅ drop the ㅅ before a vowel ending — but unlike ㄷ and ㅂ, the two vowels do NOT join up.",keyPoint:{label:"ㅅ drops but the vowels stay apart",body:"Unlike 추워요 or 들어요, the ㅅ-irregular leaves the two vowels apart: 낫다 → 나아요 (not 나요). Compare regular 웃다 → 웃어요, where the ㅅ stays. The irregular ones to know: 낫다, 붓다, 젓다, 짓다."},pronunciation:"나아요 keeps two clear ㅏ sounds [나아요]; don't shorten it to [나요]. That held, two-beat vowel is the giveaway of the ㅅ-irregular.",pitfall:{wrong:"감기가 다 나요.",right:"감기가 다 나았어요.",explanation:"Learners drop the ㅅ and then wrongly squeeze the vowels into 나요. The ㅅ-irregular keeps both vowels: present 나아요, past 나았어요."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "My cold is all better now."',tokens:["감기가","다","나았어요."],correct:"감기가 다 나았어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This restaurant is better than that one."',tokens:["이","식당이","저","식당보다","나아요."],correct:"이 식당이 저 식당보다 나아요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"감기가 다 나았어요.",ok:!0},{text:"감기가 다 나요.",ok:!1}],explanation:"Learners drop the ㅅ and then wrongly squeeze the vowels into 나요. The ㅅ-irregular keeps both vowels: present 나아요, past 나았어요."}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b6",chapterId:"chapter-41",index:5},{kind:"pattern",title:"문법 Grammar · 르 Irregular: 모르다 → 몰라요",cards:[{kind:"teach",name:"르 Irregular: 모르다 → 몰라요",sub:"",rows:[{when:"르 stem + vowel ending, when the syllable before 르 has ㅏ or ㅗ",add:"drop ㅡ, add ㄹ to the syllable before, then 라",ex:"모르다 → 몰ㄹ + 아 → 몰라요"},{when:"르 stem + vowel ending, when the syllable before 르 has any other vowel",add:"drop ㅡ, add ㄹ to the syllable before, then 러",ex:"부르다 → 불ㄹ + 어 → 불러요"},{when:"르 stem + consonant ending (-고, -지만)",add:"no change",ex:"모르다 → 모르고, 모르지만"}],examples:[{ko:"그 사람 이름을 잘 몰라요.",en:"I don't really know that person's name.",romanization:"geu saram ireumeul jal mollayo.",note:"모르다 → 몰라요; 모 before 르 has ㅗ, so the ending is 라."},{ko:"친구가 노래를 불렀어요.",en:"My friend sang a song.",romanization:"chinguga noraereul bulleosseoyo.",note:"부르다 → 불렀어요; 부 has ㅜ (not ㅏ/ㅗ), so the ending is 러/렀."}],more:{func:"Words ending in 르 add an extra ㄹ to the syllable before 르 and drop the ㅡ before -아/어. So 모르다 (to not know) becomes 몰라요, with a doubled ㄹ.",funcLead:"Words ending in 르 add an extra ㄹ to the syllable before 르 and drop the ㅡ before -아/어.",keyPoint:{label:"라 vs 러 depends on the vowel before 르",body:"If the syllable before 르 has ㅏ or ㅗ, use 라 (모르다 → 몰라요, 빠르다 → 빨라요). Otherwise use 러 (부르다 → 불러요, 누르다 → 눌러요). It's the same ㅏ/ㅗ vs everything-else choice as -아요/-어요."},pronunciation:"몰라요 has a strong doubled ㄹ [몰라요] — the first ㄹ closes 몰 and the second opens 라.",pitfall:{wrong:"그 사람을 몰라요 → 모르아요",right:"그 사람을 몰라요.",explanation:"Learners try to add the ending straight onto 모르 and get 모르아요. The 르-irregular drops the ㅡ and doubles the ㄹ, so it's 몰라요."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't really know that person's name."`,tokens:["그","사람","이름을","잘","몰라요."],correct:"그 사람 이름을 잘 몰라요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "My friend sang a song."',tokens:["친구가","노래를","불렀어요."],correct:"친구가 노래를 불렀어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"그 사람을 몰라요.",ok:!0},{text:"그 사람을 몰라요 → 모르아요",ok:!1}],explanation:"Learners try to add the ending straight onto 모르 and get 모르아요. The 르-irregular drops the ㅡ and doubles the ㄹ, so it's 몰라요."}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b7",chapterId:"chapter-41",index:6},{kind:"pattern",title:"문법 Grammar · ㅡ Irregular: 바쁘다 → 바빠요",cards:[{kind:"teach",name:"ㅡ Irregular: 바쁘다 → 바빠요",sub:"",rows:[{when:"ㅡ stem + vowel ending, when the syllable before ㅡ has ㅏ or ㅗ",add:"drop ㅡ, add 아 → 빠",ex:"바쁘다 → 바ㅃ + 아 → 바빠요"},{when:"ㅡ stem + vowel ending, other vowel (or no syllable before, like 쓰다)",add:"drop ㅡ, add 어 → 써/뻐",ex:"쓰다 → ㅆ + 어 → 써요"},{when:"ㅡ stem + consonant ending (-고, -지만)",add:"no change, ㅡ stays",ex:"바쁘다 → 바쁘고, 바쁘지만"}],examples:[{ko:"요즘 일이 너무 바빠요.",en:"I'm so busy these days.",romanization:"yojeum iri neomu bappayo.",note:"바쁘다 → 바빠요; 바 has ㅏ, so the dropped ㅡ takes 아 → 빠."},{ko:"지금 편지를 써요.",en:"I'm writing a letter right now.",romanization:"jigeum pyeonjireul sseoyo.",note:"쓰다 → 써요; nothing before ㅡ, so it defaults to 어 → 써."}],more:{func:"When a stem ends in ㅡ (like 쓰다, 바쁘다), the ㅡ drops out before -아/어. Then the syllable before it decides whether you add 아 or 어. So 바쁘다 (to be busy) becomes 바빠요.",funcLead:"When a stem ends in ㅡ (like 쓰다, 바쁘다), the ㅡ drops out before -아/어.",keyPoint:{label:"Drop the ㅡ, then pick 아 or 어",body:"The ㅡ always disappears before -아/어. To choose, look at the syllable before it: ㅏ/ㅗ → 아 (바빠요, 아파요), anything else (or nothing) → 어 (써요, 예뻐요). This is the same vowel-harmony idea as regular -아요/-어요."},pronunciation:"바빠요 has a tense ㅃ [바빠요], and 써요 starts with a tense ㅆ [써요]. The dropped ㅡ leaves a strong, double consonant sound.",pitfall:{wrong:"요즘 너무 바쁘어요.",right:"요즘 너무 바빠요.",explanation:"It feels natural to keep the ㅡ and add the ending, giving 바쁘어요. But ㅡ-stems drop the ㅡ first, so it's 바빠요 (and 쓰다 → 써요, not 쓰어요)."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm so busy these days."`,tokens:["요즘","일이","너무","바빠요."],correct:"요즘 일이 너무 바빠요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm writing a letter right now."`,tokens:["지금","편지를","써요."],correct:"지금 편지를 써요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"요즘 너무 바빠요.",ok:!0},{text:"요즘 너무 바쁘어요.",ok:!1}],explanation:"It feels natural to keep the ㅡ and add the ending, giving 바쁘어요. But ㅡ-stems drop the ㅡ first, so it's 바빠요 (and 쓰다 → 써요, not 쓰어요)."}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b8",chapterId:"chapter-41",index:7},{kind:"pattern",title:"문법 Grammar · ㅎ Irregular: 빨갛다 → 빨개요",cards:[{kind:"teach",name:"ㅎ Irregular: 빨갛다 → 빨개요",sub:"",rows:[{when:"ㅎ-irregular stem + -아/어요",add:"drop ㅎ, vowel becomes ㅐ, add 요",ex:"빨갛다 → 빨가 → 빨개요"},{when:"ㅎ-irregular stem + 어떻다 / 이렇다 etc.",add:"same: drop ㅎ, vowel → ㅐ",ex:"어떻다 → 어때요 / 이렇다 → 이래요"},{when:"ㅎ-irregular stem + consonant ending (-고, -지만)",add:"no change, ㅎ stays",ex:"빨갛다 → 빨갛고, 빨갛지만"}],examples:[{ko:"사과가 정말 빨개요.",en:"The apple is really red.",romanization:"sagwaga jeongmal ppalgaeyo.",note:"빨갛다 → 빨개요; ㅎ drops and the vowel turns into ㅐ."},{ko:"하늘이 너무 파래요.",en:"The sky is so blue.",romanization:"haneuri neomu paraeyo.",note:"파랗다 → 파래요; same ㅎ-drop with the vowel becoming ㅐ."}],more:{func:"Most color words and a few pointing words (그렇다, 어떻다) end in ㅎ. Before -아/어, the ㅎ drops AND the vowel changes to ㅐ. So 빨갛다 (to be red) becomes 빨개요. Note: 좋다 is regular — 좋아요.",funcLead:"Most color words and a few pointing words (그렇다, 어떻다) end in ㅎ.",keyPoint:{label:"ㅎ drops and the vowel turns into ㅐ",body:"With ㅎ-irregulars, two things happen at once before -아/어: the ㅎ disappears and the vowel becomes ㅐ (빨갛다 → 빨개요, 그렇다 → 그래요). Watch out: 좋다 (be good) is NOT irregular — it's just 좋아요. Learn 그래요 and 어때요 as ready-made phrases first."},pronunciation:"빨개요 is said [빨개요] with the ㅐ vowel; 그래요 is [그래요]. Don't try to keep the ㅎ sound — it's gone before the ending.",pitfall:{wrong:"사과가 빨갛아요.",right:"사과가 빨개요.",explanation:"It seems logical to keep the ㅎ and add 아요, giving 빨갛아요. But ㅎ-irregulars drop the ㅎ and change the vowel to ㅐ, so it's 빨개요. (And don't overcorrect 좋다 — that one really is 좋아요.)"}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The apple is really red."',tokens:["사과가","정말","빨개요."],correct:"사과가 정말 빨개요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The sky is so blue."',tokens:["하늘이","너무","파래요."],correct:"하늘이 너무 파래요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"사과가 빨갛아요.",ok:!1},{text:"사과가 빨개요.",ok:!0}],explanation:"It seems logical to keep the ㅎ and add 아요, giving 빨갛아요. But ㅎ-irregulars drop the ㅎ and change the vowel to ㅐ, so it's 빨개요. (And don't overcorrect 좋다 — that one really is 좋아요.)"}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b9",chapterId:"chapter-41",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner asks why common words change shape in polite speech.",lines:[{speaker:"민서",ko:"오늘 너무 추워요. 그런데 왜 '춥어요'가 아니에요?",en:"It is so cold today. But why isn't it '춥어요'?",romanization:"oneul neomu chuwoyo. geureonde wae 'chupeoyo'ga anieyo?"},{speaker:"지훈",ko:"춥다처럼 ㅂ으로 끝나는 말은 추워요, 더워요처럼 바뀌어요.",en:"Words ending in ㅂ, like 춥다, change to forms like 추워요 and 더워요.",romanization:"chupdacheoreom bieubeuro kkeutnaneun mareun chuwoyo, deowoyo-cheoreom bakkwieoyo."},{speaker:"민서",ko:"그럼 듣다는 들어요, 걷다는 걸어요가 맞죠?",en:"Then 듣다 becomes 들어요, and 걷다 becomes 걸어요, right?",romanization:"geureom deutdaneun deureoyo, geotdaneun georeoyoga matjyo?"},{speaker:"지훈",ko:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",en:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요.",romanization:"majayo. moreudaneun mollayo, ppalgataneun ppalgaeyo-cheoreom ikhimyeon dwaeyo."},{speaker:"민서",ko:"알겠어요. 자주 쓰는 단어부터 외울게요.",en:"Got it. I will memorize the high-frequency words first.",romanization:"algesseoyo. jaju sseuneun daneobuteo oeulgeyo."}]},{kind:"order",prompt:"Build: 'I don't know well.'",tokens:["잘","몰라요"],correct:"잘 몰라요",explanation:"모르다 is a 르 irregular and becomes 몰라요. 잘 softens it to “I do not know well.”"},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"맞아요. 모르다는 몰라요, 빨갛다는 빨개요처럼 익히면 돼요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"Right. Learn them as pairs, like 모르다 to 몰라요 and 빨갛다 to 빨개요."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Words ending in ㅂ, like 춥다, change to forms like 추워요 and 더워요."',sentence:"___처럼 ㅂ으로 끝나는 말은 추워요, 더워요처럼 바뀌어요.",options:[{text:"춥다",ok:!0},{text:"덥다",ok:!1},{text:"맵다",ok:!1}],explanation:""}],canDo:"Conjugate ㅂ-irregular adjectives correctly (춥다→추워요 · 어렵다→어려워요)",id:"chapter-41-b10",chapterId:"chapter-41",index:9},{kind:"reading",title:"읽기 Reading · 사전형과 말할 때의 모양",cards:[{kind:"read",title:"사전형과 말할 때의 모양",chunks:["한국어 사전에는 춥다, 듣다, 모르다처럼 기본형이 나오지만, 실제 대화에서는 추워요, 들어요, 몰라요처럼 바뀐 모양을 더 자주 들어요. 그래서 불규칙 활용은 시험용 표가 아니라 일상 발음과 문장을 바로잡는 도구예요. '오늘 추워요', '음악을 들어요', '저는 잘 몰라요', '이 방법은 어때요?'","같은 문장을 먼저 익히면 규칙 이름도 자연스럽게 따라와요. 단, 비슷하게 생겼다고 모두 바뀌지는 않아요. 듣다는 들어요지만 닫다는 닫아요이고, 낫다는 나아요지만 웃다는 웃어요예요."],translation:"Korean dictionaries show base forms such as 춥다, 듣다, and 모르다, but real conversation uses changed forms such as 추워요, 들어요, and 몰라요. Irregular conjugation is not just a test table; it repairs everyday pronunciation and sentences. Learn useful sentences first, then attach the rule names. Also remember that lookalikes are not always irregular: 듣다 changes to 들어요, but 닫다 stays 닫아요; 낫다 changes to 나아요, but 웃다 stays 웃어요.",qas:[{q:"사전에는 어떤 모양이 나오지만 실제 대화에서는 어떤 모양을 더 자주 들어요?",a:"사전에는 춥다, 듣다, 모르다 같은 기본형이 나오지만 실제 대화에서는 추워요, 들어요, 몰라요 같은 활용형을 더 자주 들어요."},{q:"듣다와 닫다는 어떻게 달라요?",a:"듣다는 들어요로 바뀌지만 닫다는 닫아요로 그대로 활용해요."},{q:"불규칙 활용은 왜 일상 대화에 중요해요?",a:"추워요, 들어요, 몰라요 같은 매우 자주 쓰는 문장에 바로 들어가기 때문이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"한국어 사전에는 춥다, 듣다, ___처럼 기본형이 나오지만, 실제 대화에서는 추워요, 들어요, 몰라요처럼 바뀐 모양을 더 자주 들어요.",options:[{text:"걷다",ok:!1},{text:"모르다",ok:!0},{text:"묻다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___는 들어요지만 닫다는 닫아요이고, 낫다는 나아요지만 웃다는 웃어요예요.",options:[{text:"걷다",ok:!1},{text:"듣다",ok:!0},{text:"묻다",ok:!1}],explanation:""}],canDo:"Conjugate ㄷ-irregular verbs correctly (듣다→들어요 · 걷다→걸어요)",id:"chapter-41-b11",chapterId:"chapter-41",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which form correctly conjugates 춥다 in polite present speech?",sentence:null,options:[{text:"추워요",ok:!0},{text:"춥어요",ok:!1},{text:"춥아요",ok:!1}],explanation:"춥다 follows the ㅂ irregular: ㅂ changes to 우 before 어요."},{kind:"drill",prompt:"Which pair shows the ㄷ irregular?",sentence:null,options:[{text:"듣다 → 들어요",ok:!0},{text:"닫다 → 달아요",ok:!1},{text:"받다 → 발아요",ok:!1}],explanation:"듣다 changes ㄷ to ㄹ. 닫다 and 받다 are regular."},{kind:"drill",prompt:"Which sentence uses 르 irregular correctly?",sentence:null,options:[{text:"저는 그 이름을 몰라요.",ok:!0},{text:"저는 그 이름을 모르어요.",ok:!1},{text:"저는 그 이름을 모라요.",ok:!1}],explanation:"모르다 becomes 몰라요: ㄹ doubles onto the previous syllable."},{kind:"drill",prompt:"Which form is natural for 어떻다?",sentence:null,options:[{text:"어때요?",ok:!0},{text:"어떻어요?",ok:!1},{text:"어떻게요?",ok:!1}],explanation:"어떻다 is a ㅎ irregular adjective: 어떻다 + 어요 → 어때요."},{kind:"drill",prompt:"Which sentence shows ㄹ deletion before -세요?",sentence:null,options:[{text:"이 단어를 아세요?",ok:!0},{text:"이 단어를 알세요?",ok:!1},{text:"이 단어를 알아세요?",ok:!1}],explanation:"알다 keeps ㄹ in 알아요 but drops ㄹ before -세요: 아세요."},{kind:"drill",prompt:"날씨___ 추워요. (The weather is cold.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"춥다 describes the weather, so 날씨 takes 가. 를 would make weather an object, which does not fit an adjective sentence."}],canDo:"Conjugate 르-irregular and ㅡ-irregular words (모르다→몰라요 · 바쁘다→바빠요)",id:"chapter-41-b12",chapterId:"chapter-41",index:11}]},{id:"chapter-42",number:42,title:"에게 / 한테 / 께 · 와/과 · 하고 · (이)랑",goal:"Choose the right particle for receiver, companion, possession, also, only, scarcity, surprising amount, and minimum option.",biteCount:14,bites:[{kind:"words",title:"단어 Words 1 · 친구~",cards:[{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?"},target:"친구",options:["teacher","gift; present","friend"],note:"Linked to dictionary card word-noun-003."},{kind:"guess",word:{ko:"선생님",romanization:"seonsaengnim",en:"teacher",pos:"noun",nuance:"님 makes the word respectful. 선생님 is also used as a polite title."},sentence:{ko:"선생님께 이메일도 드렸어요.",en:"I also sent the teacher an email."},target:"선생님",options:["friend","teacher","gift; present"],note:"Linked to dictionary card word-noun-002."},{kind:"guess",word:{ko:"선물",romanization:"seonmul",en:"gift; present",pos:"noun",nuance:"선물 can be the thing given, received, bought, or prepared. In this chapter, focus on the particle around the person and the particle attached to 선물 itself."},sentence:{ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend."},target:"선물",options:["gift; present","friend","teacher"],note:"Linked to dictionary card word-ext-ch42-seonmul."},{kind:"guess",word:{ko:"이메일",romanization:"imeil",en:"email",pos:"noun",nuance:"이메일 is the everyday loanword (from English 'e-mail') for electronic mail, used freely at work and in daily life; the Sino alternative 전자우편 (電子郵便 'electronic post') exists but sounds stiff and bureaucratic, mostly seen on official forms. Crucially, 이메일 ≠ paper mail: a physical letter is 편지, and the postal-mail system is 우편, so 'I got your letter' about a posted envelope is 편지를 받았어요, not 이메일. It collocates with 보내다 (send), 받다 (receive), 확인하다 (check), 첨부하다 (attach a file), 답장하다 (reply). The English-speaker pitfall is the recipient particle — a person who receives mail takes 에게/한테 (동료에게 이메일을 보내요), and don't drag the English verb 'do' over: you 이메일을 보내다 or 쓰다, never 이메일하다."},sentence:{ko:"선생님께 이메일도 드려야 해요.",en:"I also need to send the teacher an email."},target:"이메일",options:["friend","teacher","email"],note:"Linked to dictionary card word-ext-123."},{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"친구의 책도 돌려줘야 해요.",en:"I also need to return my friend's book."},target:"책",options:["friend","teacher","book"],note:"Linked to dictionary card word-noun-025."},{kind:"guess",word:{ko:"영화",romanization:"yeonghwa",en:"movie",pos:"noun",nuance:"영화 is Sino-Korean, 映畵 ('project-picture'), literally a projected image, and it is the standard word for a movie/film. It pairs with 보다 ('see/watch'), never 듣다 ('listen'), because film is something you view. A single film is counted with the bound noun 편 (영화 두 편 = two movies), not 개. Don't confuse 영화 with 드라마: 드라마 is a serialized TV series, while 영화 is a self-contained cinema film, so a Korean TV soap is a 드라마, not a 영화. The cinema building is 영화관 (or the loanword 극장). The classic English-speaker pitfall is letting 'a movie' steer you to the generic counter 개 (영화 한 개 sounds wrong) — use 편; and don't calque 'go to a movie' as 영화에 가다, since you say 영화(를) 보러 가다, 'go in order to watch a movie'."},sentence:{ko:"영화도 보러 가요?",en:"Are you also going to see a movie?"},target:"영화",options:["friend","movie","teacher"],note:"Linked to dictionary card word-ext-302."},{kind:"payoff",line:{speaker:"민서",ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?"},hl:"친구"}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b1",chapterId:"chapter-42",index:0},{kind:"pattern",title:"문법 Grammar · 에게 / 한테 / 께",cards:[{kind:"hunt",name:"에게 / 한테 / 께",sub:"to a person (께 = honorific)",lines:[{tokens:[{pre:"친구",mid:"에게",post:"",hit:!0},{pre:"선물을",mid:"",post:"",hit:!1},{pre:"줬어요.",mid:"",post:"",hit:!1}],ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend.",romanization:"chinguege seonmureul jwosseoyo."},{tokens:[{pre:"동생",mid:"한테",post:"",hit:!0},{pre:"책을",mid:"",post:"",hit:!1},{pre:"빌려줬어요.",mid:"",post:"",hit:!1}],ko:"동생한테 책을 빌려줬어요.",en:"I lent a book to my younger sibling.",romanization:"dongsaenghante chaegeul billyeojwosseoyo."}],rule:{name:"에게 / 한테 / 께",rows:[{when:"Neutral or written, after any person noun",add:"noun + 에게",ex:"친구 → 친구에게 (to a friend)"},{when:"Casual spoken, after any person noun",add:"noun + 한테",ex:"동생 → 동생한테 (to my younger sibling)"},{when:"Honorific, a person you respect",add:"noun + 께",ex:"선생님 → 선생님께 (to the teacher)"},{when:"'from a person' (source)",add:"noun + 에게서 / 한테서",ex:"친구한테서 들었어요 (I heard it from a friend)"}]},more:{func:"Marks the person who receives or is the target of an action: giving, sending, asking, telling, lending. English uses 'to (a person)'.",funcLead:"Marks the person who receives or is the target of an action: giving, sending, asking, telling, lending.",keyPoint:{label:"에게/한테 vs 께",body:"에게 and 한테 mean the same thing (한테 just sounds more casual). 께 is the honorific version for a respected person and usually rides with humble verbs like 드리다 and 여쭤보다."},pronunciation:"께 is a tense [kk] sound, like the kk in 'bookkeeper' — 선생님께 is [seon-saeng-nim-kke], never a plain [g].",pitfall:{wrong:"선물에게 줬어요.",right:"친구에게 선물을 줬어요.",explanation:"English 'gave to the gift' is obviously wrong, but learners attach 에게 to whatever follows 'to'. 에게 marks only the person receiver; the thing given takes the object particle 을/를."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I gave a gift to a friend." (친구에게 시작 · Start with 친구에게.)',tokens:["친구에게","선물을","줬어요."],correct:"친구에게 선물을 줬어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I lent a book to my younger sibling." (동생한테 시작 · Start with 동생한테.)',tokens:["동생한테","책을","빌려줬어요."],correct:"동생한테 책을 빌려줬어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구에게 선물을 줬어요.",ok:!0},{text:"선물에게 줬어요.",ok:!1}],explanation:"English 'gave to the gift' is obviously wrong, but learners attach 에게 to whatever follows 'to'. 에게 marks only the person receiver; the thing given takes the object particle 을/를."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Neutral or written, after any person noun",sentence:"친구___",options:[{text:"에게",ok:!0},{text:"한테",ok:!1},{text:"께",ok:!1}],explanation:"친구 → 친구에게 (to a friend)"}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b2",chapterId:"chapter-42",index:1},{kind:"words",title:"단어 Words 2 · 시험~",cards:[{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"시험 문제가 세 개나 남았어요.",en:"As many as three exam questions are left."},target:"시험",options:["exam","friend","teacher"],note:"Linked to dictionary card word-ext-111."},{kind:"guess",word:{ko:"문제",romanization:"munje",en:"problem; question",pos:"noun",nuance:"문제(問題, 'ask + topic') has two everyday senses English keeps apart: a trouble or difficulty ('we have a problem') AND a question on a test or exercise ('problem 3'). Crucially, both are solved with the same verb 풀다 (literally 'to untie/loosen') — 문제를 풀다 works for a math item and for a real-life difficulty alike, where English would switch to 'answer' vs 'solve.' Other key partners: 문제가 생기다 (a problem arises), 문제가 되다 (to become an issue), and the handy one-word 문제없어요 ('no problem'). Contrast 문제 with 질문 (a question you ASK someone to get information) — a test 문제 is a problem to solve, but raising your hand to ask is 질문하다, not 문제하다. The English-speaker pitfall is the subject/object split: existence and arising take 이 (문제가 있다/생기다), but solving takes 를 (문제를 풀다) — learners often say 문제가 풀어요."},sentence:{ko:"문제가 세 개나 남았어요.",en:"As many as three questions are left."},target:"문제",options:["friend","problem; question","teacher"],note:"Linked to dictionary card word-ext-426."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study; studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"공부밖에 못 해요.",en:"I can do nothing but study."},target:"공부",options:["friend","teacher","study; studying"],note:"Linked to dictionary card word-ext-1560."},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피라도 마실래요?",en:"Do you want to at least drink coffee?"},target:"커피",options:["friend","teacher","coffee"],note:"Linked to dictionary card word-noun-013."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"한 시간만요.",en:"Just one hour."},target:"시간",options:["time","friend","teacher"],note:"Linked to dictionary card word-noun-009."},{kind:"guess",word:{ko:"물",romanization:"mul",en:"water",pos:"noun",nuance:"물 is essential in restaurants. 물 주세요 is more useful than just knowing “water.”"},sentence:{ko:"물이라도 드릴까요?",en:"Should I at least bring you water?"},target:"물",options:["water","friend","teacher"],note:"Linked to dictionary card word-noun-012."},{kind:"payoff",line:{speaker:"지훈",ko:"아니요, 시험 문제가 세 개나 남아서 공부밖에 못 해요.",en:"No, as many as three exam questions are left, so I can only study."},hl:"시험"}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b3",chapterId:"chapter-42",index:2},{kind:"pattern",title:"문법 Grammar · 와/과 · 하고 · (이)랑",cards:[{kind:"teach",name:"와/과 · 하고 · (이)랑",sub:"and / with",rows:[{when:"After a vowel-final noun (written/tidy)",add:"noun + 와",ex:"커피 → 커피와 물 (coffee and water)"},{when:"After a consonant-final noun (written/tidy)",add:"noun + 과",ex:"책 → 책과 가방 (a book and a bag)"},{when:"Any noun (neutral spoken)",add:"noun + 하고",ex:"민수하고 (with Minsu)"},{when:"Vowel-final / consonant-final (casual spoken)",add:"noun + 랑 / 이랑",ex:"친구 → 친구랑 / 동생 → 동생이랑"}],examples:[{ko:"친구랑 영화를 봐요.",en:"I watch a movie with a friend.",romanization:"chingurang yeonghwareul bwayo.",note:"친구 ends in a vowel, so 랑; casual speech prefers (이)랑."},{ko:"민수하고 같이 갔어요.",en:"I went together with Minsu.",romanization:"minsuhago gachi gasseoyo.",note:"하고 plus 같이 makes the 'with / together' reading unmistakable."}],more:{func:"Links two nouns ('A and B') or marks the companion you do something with ('with A'). All three mean the same; they differ only in register.",funcLead:"Links two nouns ('A and B') or marks the companion you do something with ('with A').",keyPoint:{label:"와/과 vs 하고 vs (이)랑",body:"Meaning is identical; register differs. 와/과 = neutral-to-written, 하고 = neutral spoken, (이)랑 = casual spoken. Add 같이 when you want 'with' to be clear over 'and'."},pronunciation:"과 after a consonant tenses: 책과 sounds like [chaek-kkwa]; 와 after a vowel stays light, 커피와 [keo-pi-wa].",pitfall:{wrong:"친구랑 영화를 보고 팝콘이랑 먹었어요.",right:"영화를 보고 팝콘을 먹었어요.",explanation:"와/과·하고·(이)랑 connect nouns, not actions. To join two verbs ('watch and eat'), use the connective -고, not these particles."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I watch a movie with a friend." (친구랑 시작 · Start with 친구랑.)',tokens:["친구랑","영화를","봐요."],correct:"친구랑 영화를 봐요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I went together with Minsu." (민수하고 시작 · Start with 민수하고.)',tokens:["민수하고","같이","갔어요."],correct:"민수하고 같이 갔어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구랑 영화를 보고 팝콘이랑 먹었어요.",ok:!1},{text:"영화를 보고 팝콘을 먹었어요.",ok:!0}],explanation:"와/과·하고·(이)랑 connect nouns, not actions. To join two verbs ('watch and eat'), use the connective -고, not these particles."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — After a vowel-final noun (written/tidy)",sentence:"커피___",options:[{text:"과 가방",ok:!1},{text:"랑",ok:!1},{text:"와 물",ok:!0}],explanation:"커피 → 커피와 물 (coffee and water)"}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b4",chapterId:"chapter-42",index:3},{kind:"words",title:"단어 Words 3 · 돈~",cards:[{kind:"guess",word:{ko:"돈",romanization:"don",en:"money",pos:"noun",nuance:"돈 is money. In stores, 카드 and 현금 are often more specific and useful."},sentence:{ko:"돈이 만 원밖에 없어요.",en:"I only have 10,000 won."},target:"돈",options:["money","friend","teacher"],note:"Linked to dictionary card word-noun-015."},{kind:"guess",word:{ko:"방법",romanization:"bangbeop",en:"method; way",pos:"noun",nuance:"방법 is Sino-Korean (方法, 方 'direction/manner' + 法 'rule/method'), the 'way', 'method', or 'means' of doing something — the procedure or approach to reach a goal. Compare it with 방식 (方式, 'style/mode/manner'): 방법 is the concrete how-to ('a method to fix it'), while 방식 is the overall style or fashion in which something is done (생활 방식 = lifestyle, 사고방식 = way of thinking) — you wouldn't say 사고방법. Also distinguish 수단 (手段, 'means/instrument', often the tool or even an unscrupulous means: 교통수단 = means of transport, 수단과 방법을 가리지 않다 = by any means necessary). Register-neutral, very common. Core collocations: 방법이 있다/없다, 방법을 찾다/알다/모르다/바꾸다, [동사]~는 방법 (a way to do ~), 해결 방법 (solution), 사용 방법 (how to use). The English-speaker pitfall is the 'a way to do X' frame: it's [verb in ~는 form] + 방법, e.g. 'a way to study' is 공부하는 방법, NOT 공부 방법 in spoken contexts (though 공부 방법 as a fixed noun-noun compound is fine for 'study method'). Don't say 방법으로 어떻게 when you just mean 어떻게 ('how') — 방법 is the noun 'method', not the question word 'how'."},sentence:{ko:"이 방법밖에 없어요.",en:"There is no way except this."},target:"방법",options:["friend","method; way","teacher"],note:"Linked to dictionary card word-ext-428."},{kind:"guess",word:{ko:"계획",romanization:"gyehoek",en:"plan",pos:"noun",nuance:"계획(計劃, 'count/reckon + plan') is a worked-out plan or scheme for the future. Its single most important quirk is the verb: Koreans BUILD a plan with 세우다 (literally 'to erect/stand up') — 계획을 세우다 — not 만들다 ('make') as the English calque suggests. Other partners: 계획이 있다 (have a plan) and the smooth adverb 계획대로 ('as planned'). Distinguish 계획 from 예정 豫定, which is a SCHEDULED arrangement that is already set ('내일 출발할 예정이에요' = I'm scheduled/due to leave tomorrow), and from 약속, a personal commitment/appointment with someone — 계획 is your own roadmap, 예정 is a fixed scheduling, 약속 involves another party. The English-speaker pitfall is exactly 계획을 만들다 (use 세우다), and translating 'plan to do' with 계획 as a verb — Korean uses -(으)려고 하다 or -(으)ㄹ 계획이다: 여행할 계획이에요 ('I plan to travel'), not 여행을 계획해요 in casual speech."},sentence:{ko:"오늘의 계획은 공부예요.",en:"Today's plan is studying."},target:"계획",options:["plan","friend","teacher"],note:"Linked to dictionary card word-ext-429."},{kind:"guess",word:{ko:"주다",romanization:"juda",en:"to give",pos:"verb",nuance:"주세요 comes from 주다 and is one of the most important polite request endings."},sentence:{ko:"친구에게 선물을 줬어요.",en:"I gave a gift to a friend."},target:"줬",options:["to give","friend","teacher"],note:"Linked to dictionary card word-verb-022."},{kind:"guess",word:{ko:"드리다",romanization:"deurida",en:"to give/send humbly to someone respected",pos:"verb",nuance:"드리다 respects the recipient, not the subject. It is different from -(으)시-, which honors the subject."},sentence:{ko:"선생님께 이메일을 드렸어요.",en:"I sent the teacher an email."},target:"드렸",options:["friend","to give/send humbly to someone respected","teacher"],note:"Linked to dictionary card word-ext-ch13-deurida."},{kind:"payoff",line:{speaker:"지훈",ko:"좋아요. 선생님께 이메일도 보내드리고, 친구의 책도 돌려줘야 해요.",en:"Sounds good. I also need to send the teacher an email and return my friend's book."},hl:"드리"}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b5",chapterId:"chapter-42",index:4},{kind:"pattern",title:"문법 Grammar · 밖에 + negative",cards:[{kind:"hunt",name:"밖에 + negative",sub:"nothing but / only (and it's not enough)",lines:[{tokens:[{pre:"공부",mid:"밖에",post:"",hit:!0},{pre:"못",mid:"",post:"",hit:!1},{pre:"해요.",mid:"",post:"",hit:!1}],ko:"공부밖에 못 해요.",en:"I can do nothing but study.",romanization:"gongbubakke mot haeyo."},{tokens:[{pre:"한",mid:"",post:"",hit:!1},{pre:"시간",mid:"밖에",post:"",hit:!0},{pre:"없어요.",mid:"",post:"",hit:!1}],ko:"한 시간밖에 없어요.",en:"I only have one hour.",romanization:"han siganbakke eopseoyo."}],rule:{name:"밖에 + negative",rows:[{when:"noun + 밖에 with 없다",add:"noun + 밖에 + 없어요",ex:"한 시간밖에 없어요 (I only have one hour)"},{when:"noun + 밖에 with 못",add:"noun + 밖에 + 못 V",ex:"물밖에 못 마셔요 (I can drink nothing but water)"},{when:"noun + 밖에 with 안 / -지 않다",add:"noun + 밖에 + 안 V",ex:"공부밖에 안 해요 (I do nothing but study)"},{when:"Replaces 이/가/을/를",add:"no subject/object particle before 밖에",ex:"이것밖에 없어요 (✓), 이것을밖에 (✗)"}]},more:{func:"Marks a limit that always needs a negative predicate. It frames the amount as scarce or insufficient: 'nothing but X', 'only X (and that's all there is)'.",funcLead:"Marks a limit that always needs a negative predicate.",keyPoint:{label:"밖에 vs 만",body:"Both translate as 'only', but 밖에 demands a negative predicate and feels scarce/insufficient (공부밖에 못 해요), while 만 is neutral and takes a positive verb (공부만 해요). If you see a positive verb, you need 만, not 밖에."},pronunciation:"밖에 links across the ㄲ: [ba-kke], so 공부밖에 is [gong-bu-ba-kke] and 한 시간밖에 is [han si-gan-ba-kke].",pitfall:{wrong:"공부밖에 해요.",right:"공부밖에 못 해요. / 공부만 해요.",explanation:"Because English 'only' goes with positive verbs, learners drop the negative. 밖에 grammatically requires 못/안/없어요. If you want a plain positive 'only', switch to 만."}}},{kind:"drill",prompt:"There's no way except this one.",sentence:"이 방법___ 없어요.",options:[{text:"밖에",ok:!0},{text:"에게",ok:!1},{text:"한테",ok:!1}],explanation:"밖에 plus 없어요 = a forced, no-other-choice frame."},{kind:"drill",prompt:"I can only drink water.",sentence:"물___ 못 마셔요.",options:[{text:"에게",ok:!1},{text:"밖에",ok:!0},{text:"한테",ok:!1}],explanation:"물 takes 밖에 with no extra particle, paired with 못."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I can do nothing but study." (공부밖에 시작 · Start with 공부밖에.)',tokens:["공부밖에","못","해요."],correct:"공부밖에 못 해요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I only have one hour." (한 시작 · Start with 한.)',tokens:["한","시간밖에","없어요."],correct:"한 시간밖에 없어요.",explanation:""}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b6",chapterId:"chapter-42",index:5},{kind:"pattern",title:"문법 Grammar · (이)나",cards:[{kind:"hunt",name:"(이)나",sub:"as many as / or",lines:[{tokens:[{pre:"문제가",mid:"",post:"",hit:!1},{pre:"세",mid:"",post:"",hit:!1},{pre:"개",mid:"나",post:"",hit:!0},{pre:"남았어요.",mid:"",post:"",hit:!1}],ko:"문제가 세 개나 남았어요.",en:"As many as three questions are left.",romanization:"munjega se gaena namasseoyo."},{tokens:[{pre:"커피를",mid:"",post:"",hit:!1},{pre:"다섯",mid:"",post:"",hit:!1},{pre:"잔",mid:"이나",post:"",hit:!0},{pre:"마셨어요.",mid:"",post:"",hit:!1}],ko:"커피를 다섯 잔이나 마셨어요.",en:"I drank as many as five cups of coffee.",romanization:"keopireul daseot jan-ina masyeosseoyo."}],rule:{name:"(이)나",rows:[{when:"After a consonant-final number/noun",add:"+ 이나",ex:"다섯 잔 → 다섯 잔이나 (as many as 5 cups)"},{when:"After a vowel-final number/noun",add:"+ 나",ex:"세 개 → 세 개나 (as many as 3)"},{when:"'A or B' (rough choice)",add:"noun(이)나 noun",ex:"커피나 물 (coffee or water)"},{when:"Loose suggestion ('or something')",add:"noun + (이)나",ex:"물이나 마실까요? (shall we just drink water or something?)"}]},more:{func:"After a number or amount it adds 'surprisingly much' (as many as); between two nouns it offers a loose choice ('A or B'). This chapter centers on the 'as many as' use.",funcLead:"After a number or amount it adds 'surprisingly much' (as many as); between two nouns it offers a loose choice ('A or B').",keyPoint:{label:"(이)나 vs 밖에",body:"Both attach to amounts but pull opposite ways. 다섯 잔이나 = the amount feels big (more than expected); 다섯 잔밖에 못 마셨어요 = the amount feels small (less than wanted). 나 says 'wow, that much'; 밖에 says 'only that little'."},pronunciation:"이나/나 trigger no special tensing; just match the final sound: 개나 [gae-na], 잔이나 [jan-i-na].",pitfall:{wrong:"세 개나밖에 남았어요.",right:"세 개나 남았어요. / 세 개밖에 안 남았어요.",explanation:"Learners blend the two because both attach to numbers. Pick one stance: 나 = surprisingly many (positive verb), 밖에 = surprisingly few (negative verb). They cannot stack."}}},{kind:"drill",prompt:"I waited a whole hour.",sentence:"한 시간___ 기다렸어요.",options:[{text:"나",ok:!1},{text:"이나",ok:!0}],explanation:"시간 ends in a consonant → 이나; the wait felt long."},{kind:"drill",prompt:"Give me coffee or water (either is fine).",sentence:"커피___ 물 주세요.",options:[{text:"나",ok:!0},{text:"에게",ok:!1},{text:"한테",ok:!1}],explanation:"Here (이)나 means a loose 'or' between two acceptable options."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "As many as three questions are left."',tokens:["문제가","세","개나","남았어요."],correct:"문제가 세 개나 남았어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I drank as many as five cups of coffee."',tokens:["커피를","다섯","잔이나","마셨어요."],correct:"커피를 다섯 잔이나 마셨어요.",explanation:""}],canDo:"Show means or direction with (으)로 (버스로 가요)",id:"chapter-42-b7",chapterId:"chapter-42",index:6},{kind:"pattern",title:"문법 Grammar · (이)라도",cards:[{kind:"hunt",name:"(이)라도",sub:"at least; even if only",lines:[{tokens:[{pre:"시간",mid:"",post:"",hit:!1},{pre:"없으면",mid:"",post:"",hit:!1},{pre:"물",mid:"이라도",post:"",hit:!0},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"시간 없으면 물이라도 마셔요.",en:"If you don't have time, at least drink some water.",romanization:"sigan eopseumyeon murirado masyeoyo."},{tokens:[{pre:"커피",mid:"라도",post:"",hit:!0},{pre:"한잔할까요?",mid:"",post:"",hit:!1}],ko:"커피라도 한잔할까요?",en:"Shall we at least grab a coffee?",romanization:"keopirado hanjanhalkkayo?"}],rule:{name:"(이)라도",rows:[{when:"After a vowel-final noun",add:"noun + 라도",ex:"커피 → 커피라도 (coffee, if nothing else)"},{when:"After a consonant-final noun",add:"noun + 이라도",ex:"물 → 물이라도 (at least water)"},{when:"With a suggestion (-(으)ㄹ까요? / -읍시다)",add:"noun(이)라도 + suggestion",ex:"물이라도 마실까요? (shall we at least drink some water?)"},{when:"'even a little' with time/amount",add:"amount + (이)라도",ex:"잠깐이라도 쉬세요 (rest, even for a moment)"}]},more:{func:"Offers a minimum or fallback option when the ideal one isn't available: 'at least X', 'even if only X', 'X if nothing else'.",funcLead:"Offers a minimum or fallback option when the ideal one isn't available: 'at least X', 'even if only X', 'X if nothing else'.",keyPoint:{label:"(이)라도 vs 만",body:"만 picks X as the exclusive choice ('only X'); (이)라도 picks X as a settling-for second choice ('X if nothing better'). 물만 마셔요 = I drink only water (by choice); 물이라도 마셔요 = at least drink water (since there's nothing else)."},pronunciation:"(이)라도 is light with no tensing; just link smoothly: 물이라도 [mu-ri-ra-do], 커피라도 [keo-pi-ra-do].",pitfall:{wrong:"물이라도만 마셔요.",right:"물이라도 마셔요. / 물만 마셔요.",explanation:"(이)라도 and 만 express opposite attitudes (settling vs. exclusive), so they don't stack. Choose 이라도 for 'at least, if nothing else' or 만 for 'only, by choice'."}}},{kind:"drill",prompt:"Rest, even for just a moment.",sentence:"잠깐___ 쉬세요.",options:[{text:"이라도",ok:!0},{text:"라도",ok:!1}],explanation:"잠깐 is consonant-final → 이라도; 'even a little' time is better than none."},{kind:"drill",prompt:"Let's at least take the bus (go by bus).",sentence:"버스___ 타고 가요.",options:[{text:"라도",ok:!0},{text:"에게",ok:!1},{text:"한테",ok:!1}],explanation:"버스 is vowel-final → 라도; the bus is the second-best option."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If you don't have time, at least drink some water."`,tokens:["시간","없으면","물이라도","마셔요."],correct:"시간 없으면 물이라도 마셔요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"물이라도 마셔요. / 물만 마셔요.",ok:!0},{text:"물이라도만 마셔요.",ok:!1}],explanation:"(이)라도 and 만 express opposite attitudes (settling vs. exclusive), so they don't stack. Choose 이라도 for 'at least, if nothing else' or 만 for 'only, by choice'."}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b8",chapterId:"chapter-42",index:7},{kind:"pattern",title:"문법 Grammar · 의",cards:[{kind:"teach",name:"의",sub:"'s / of (noun-to-noun link)",rows:[{when:"noun + 의 + noun (possession)",add:"의",ex:"친구의 책 (a friend's book) · 한국의 음식 (Korea's food)"},{when:"저/나 + 의 contract",add:"제 / 내",ex:"저의 → 제 · 나의 → 내"},{when:"Usually dropped in speech",add:"(no 의)",ex:"친구 가방 = 친구의 가방"}],examples:[{ko:"이건 친구의 책이에요.",en:"This is my friend's book.",romanization:"igeon chinguui chaegieyo.",note:"친구 + 의 + 책 — the first noun owns the second."},{ko:"제 가방이 어디 있어요?",en:"Where is my bag?",romanization:"je gabangi eodi isseoyo?",note:'저의 contracts to 제 — the everyday way to say "my."'}],more:{func:`의 links two nouns to show possession or relationship, like English "'s" or "of": 친구의 가방 (a friend's bag). In speech it is usually dropped (친구 가방), and 저의/나의 contract to 제/내.`,funcLead:`의 links two nouns to show possession or relationship, like English "'s" or "of": 친구의 가방 (a friend's bag).`,keyPoint:{label:"Drop 의 in speech; contract 저의 → 제",body:"Written Korean keeps 의 (친구의 책), but spoken Korean usually drops it (친구 책). The one place it survives is the contractions 제 (저의), 내 (나의), 네 (너의) — always say 제 책, not 저의 책 in conversation."},pronunciation:"The possessive particle 의 may be pronounced [의] or, very commonly in conversation, [에]: 친구의 → [친구의] or [친구에]. Inside a word, non-initial 의 may also be heard as [이] in permitted pronunciations. Treat [에] as a useful spoken option, not the only possible sound.",pitfall:{wrong:"저의 가방",right:"제 가방",explanation:"In speech, 저의 always shrinks to 제. Say 제 가방 (my bag), not 저의 가방 — the full form sounds stiff and written."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "This is my friend's book."`,tokens:["이건","친구의","책이에요."],correct:"이건 친구의 책이에요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Where is my bag?"',tokens:["제","가방이","어디","있어요?"],correct:"제 가방이 어디 있어요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저의 가방",ok:!1},{text:"제 가방",ok:!0}],explanation:"In speech, 저의 always shrinks to 제. Say 제 가방 (my bag), not 저의 가방 — the full form sounds stiff and written."}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b9",chapterId:"chapter-42",index:8},{kind:"pattern",title:"문법 Grammar · (으)로",cards:[{kind:"hunt",name:"(으)로",sub:"by means of / toward (direction)",lines:[{tokens:[{pre:"버스",mid:"로",post:"",hit:!0},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"버스로 학교에 가요.",en:"I go to school by bus.",romanization:"beoseuro hakgyoe gayo."},{tokens:[{pre:"손",mid:"으로",post:"",hit:!0},{pre:"먹었어요.",mid:"",post:"",hit:!1}],ko:"손으로 먹었어요.",en:"I ate with my hands.",romanization:"soneuro meogeosseoyo."}],rule:{name:"(으)로",rows:[{when:"After a vowel-final noun",add:"noun + 로",ex:"버스 → 버스로 (by bus)"},{when:"After a consonant-final noun",add:"noun + 으로",ex:"손 → 손으로 (with one's hand)"},{when:"After a ㄹ-final noun (no 으)",add:"noun + 로",ex:"지하철 → 지하철로 (by subway)"},{when:"Direction (toward)",add:"place + (으)로",ex:"오른쪽으로 가세요 (go to the right)"}]},more:{func:"Marks how you do something (tool, means, transport) or which direction you head: 'by/with X', 'toward X'.",funcLead:"Marks how you do something (tool, means, transport) or which direction you head: 'by/with X', 'toward X'.",keyPoint:{label:"(으)로 vs 에 (destination)",body:"에 marks the exact destination you arrive at (학교에 가요 = go to school); (으)로 marks the direction you face or the means you use (학교로 가요 = head toward school; 버스로 가요 = go by bus). For transport and tools, always (으)로, never 에."},pronunciation:"After ㄹ the 로 doubles the ㄹ: 지하철로 is [ji-ha-cheol-lo], not [ji-ha-cheol-ro].",pitfall:{wrong:"버스에 학교에 가요.",right:"버스로 학교에 가요.",explanation:"English uses 'by bus' / 'to school' with no particle clash, but in Korean the means takes (으)로 and the destination takes 에. Don't put 에 on the transport — 버스에 가요 would mean 'go onto the bus'."}}},{kind:"drill",prompt:"I transferred to the subway.",sentence:"지하철___ 갈아탔어요.",options:[{text:"로",ok:!0},{text:"으로",ok:!1}],explanation:"지하철 ends in ㄹ, so just 로 (no 으); pronounced [ji-ha-cheol-lo]."},{kind:"drill",prompt:"Come this way.",sentence:"이쪽___ 오세요.",options:[{text:"으로",ok:!0},{text:"에게",ok:!1},{text:"한테",ok:!1}],explanation:"이쪽 is consonant-final → 으로; here it marks direction, not means."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I go to school by bus." (버스로 시작 · Start with 버스로.)',tokens:["버스로","학교에","가요."],correct:"버스로 학교에 가요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"버스에 학교에 가요.",ok:!1},{text:"버스로 학교에 가요.",ok:!0}],explanation:"English uses 'by bus' / 'to school' with no particle clash, but in Korean the means takes (으)로 and the destination takes 에. Don't put 에 on the transport — 버스에 가요 would mean 'go onto the bus'."}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b10",chapterId:"chapter-42",index:9},{kind:"pattern",title:"문법 Grammar · 마다",cards:[{kind:"teach",name:"마다",sub:"every / each",rows:[{when:"After a time noun",add:"noun + 마다",ex:"아침 → 아침마다 (every morning)"},{when:"After a counted unit",add:"unit + 마다",ex:"세 시간 → 세 시간마다 (every three hours)"},{when:"After a person/thing noun",add:"noun + 마다",ex:"사람 → 사람마다 (each person)"},{when:"With a place noun",add:"place + 마다",ex:"나라 → 나라마다 (every country)"}],examples:[{ko:"아침마다 커피를 마셔요.",en:"I drink coffee every morning.",romanization:"achimmada keopireul masyeoyo.",note:"아침 + 마다 = 'every morning'; no extra time particle is needed."},{ko:"주말마다 친구를 만나요.",en:"I meet my friends every weekend.",romanization:"jumalmada chingureul mannayo.",note:"마다 attaches straight to 주말; it already means 'every', so don't add 에."}],more:{func:"Attaches to a noun to mean 'every X' or 'each X', often for repeated times or all members of a group: 'every morning', 'each person'.",funcLead:"Attaches to a noun to mean 'every X' or 'each X', often for repeated times or all members of a group: 'every morning', 'each person'.",keyPoint:{label:"마다 vs 매-",body:"마다 is a particle stuck onto a noun (아침마다, 날마다). 매 is a prefix glued in front (매일 = every day, 매주 = every week). Both mean 'every', but 매 forms set words while 마다 attaches freely to almost any noun."},pronunciation:"마다 is plain and light: 아침마다 [a-chim-ma-da], 주말마다 [ju-mal-ma-da]. No tensing or linking surprises.",pitfall:{wrong:"아침마다에 커피를 마셔요.",right:"아침마다 커피를 마셔요.",explanation:"마다 already carries the 'at every' meaning, so adding the time particle 에 is redundant and wrong. Use 마다 alone — never 마다에."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I drink coffee every morning." (아침마다 시작 · Start with 아침마다.)',tokens:["아침마다","커피를","마셔요."],correct:"아침마다 커피를 마셔요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I meet my friends every weekend." (주말마다 시작 · Start with 주말마다.)',tokens:["주말마다","친구를","만나요."],correct:"주말마다 친구를 만나요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"아침마다 커피를 마셔요.",ok:!0},{text:"아침마다에 커피를 마셔요.",ok:!1}],explanation:"마다 already carries the 'at every' meaning, so adding the time particle 에 is redundant and wrong. Use 마다 alone — never 마다에."}],canDo:"Show means or direction with (으)로 (버스로 가요)",id:"chapter-42-b11",chapterId:"chapter-42",index:10},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends negotiate a weekend plan while one person has study obligations.",lines:[{speaker:"민서",ko:"주말에 친구랑 영화도 보러 가요?",en:"Are you also going to see a movie with a friend this weekend?",romanization:"jumare chingurang yeonghwado boreo gayo?"},{speaker:"지훈",ko:"아니요, 시험 문제가 세 개나 남아서 공부밖에 못 해요.",en:"No, as many as three exam questions are left, so I can only study.",romanization:"aniyo, siheom munjega se gaena namaseo gongbubakke mot haeyo."},{speaker:"민서",ko:"그럼 커피라도 마실래요? 한 시간만요.",en:"Then do you want to at least drink coffee? Just one hour.",romanization:"geureom keopirado masillaeyo? han siganmannyo."},{speaker:"지훈",ko:"좋아요. 선생님께 이메일도 보내드리고, 친구의 책도 돌려줘야 해요.",en:"Sounds good. I also need to send the teacher an email and return my friend's book.",romanization:"joayo. seonsaengnimkke imeildo bonaedeurigo, chinguui chaekdo dollyeojwoya haeyo."}]},{kind:"order",prompt:"Build: 'I have only one hour, and it is not enough.'",tokens:["한 시간밖에","없어요"],correct:"한 시간밖에 없어요",explanation:"밖에 must pair with a negative like 없어요. It sounds like the amount is limited or insufficient."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"좋아요. 선생님께 이메일도 보내드리고, 친구의 책도 돌려줘야 해요.",options:[{text:"민서",ok:!1},{text:"지훈",ok:!0}],explanation:"Sounds good. I also need to send the teacher an email and return my friend's book."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Are you also going to see a movie with a friend this weekend?"',sentence:"주말에 ___랑 영화도 보러 가요?",options:[{text:"선생님",ok:!1},{text:"선물",ok:!1},{text:"친구",ok:!0}],explanation:""}],canDo:"Mark the person who receives an action (친구한테 · 선생님께)",id:"chapter-42-b12",chapterId:"chapter-42",index:11},{kind:"reading",title:"읽기 Reading · 주말 계획을 조사로 정리하기",cards:[{kind:"read",title:"주말 계획을 조사로 정리하기",chunks:["주말 계획을 말할 때는 명사보다 조사가 더 많은 정보를 줄 때가 있어요. 친구랑 영화를 보면 함께 가는 사람을 말하는 것이고, 영화도 본다고 하면 다른 일에 영화를 추가하는 거예요. 시험 문제가 세 개나 남았다고 하면 양이 많게 느껴지고, 공부밖에 못 한다고 하면 선택지가 거의 없다는 뜻이에요.","그래도 커피라도 마시자고 하면 완전한 약속은 아니지만 최소한 가능한 제안을 하는 거예요. 마지막으로 선생님께 이메일을 보내드리고 친구의 책을 돌려줘야 한다면, 께는 받는 사람의 높임, 의는 소유 관계를 보여 줘요."],translation:"When talking about weekend plans, particles often carry more information than the noun itself. 친구랑 tells who you go with, 영화도 adds a movie to other plans, 세 개나 shows the amount feels large, 공부밖에 못 해요 means the options are limited, 커피라도 offers a minimum plan, 께 marks a respected receiver, and 의 marks possession.",qas:[{q:"친구랑 영화 보면 어떤 의미예요?",a:"친구와 함께 영화를 본다는 뜻이에요."},{q:"공부밖에 못 해요에서 왜 못 해요가 필요해요?",a:"밖에가 부정 표현과 함께 쓰여서 선택지가 제한된다는 뜻을 만들기 때문이에요."},{q:"커피라도 마실래요?는 어떤 느낌이에요?",a:"완전한 계획은 아니지만 최소한 커피라도 마시자는 제안이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"주말 ___을 말할 때는 명사보다 조사가 더 많은 정보를 줄 때가 있어요.",options:[{text:"선물",ok:!1},{text:"시간",ok:!1},{text:"계획",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___랑 영화를 보면 함께 가는 사람을 말하는 것이고, 영화도 본다고 하면 다른 일에 영화를 추가하는 거예요.",options:[{text:"선물",ok:!1},{text:"시간",ok:!1},{text:"친구",ok:!0}],explanation:""}],canDo:"Link nouns or a companion with 'and/with' (친구하고 · 친구랑)",id:"chapter-42-b13",chapterId:"chapter-42",index:12},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly marks the teacher as a respected receiver?",sentence:null,options:[{text:"선생님께 이메일을 드렸어요.",ok:!0},{text:"선생님에서 이메일을 드렸어요.",ok:!1},{text:"선생님만 이메일을 드렸어요.",ok:!1}],explanation:"께 marks a respected person receiving the action, and 드리다 matches the respectful tone."},{kind:"drill",prompt:"Which sentence uses 밖에 correctly?",sentence:null,options:[{text:"공부밖에 못 해요.",ok:!0},{text:"공부밖에 해요.",ok:!1},{text:"공부밖에 좋아요.",ok:!1}],explanation:"밖에 needs a negative idea such as 못, 안, or 없어요."},{kind:"drill",prompt:"Which sentence means 'as many as three exam questions are left'?",sentence:null,options:[{text:"시험 문제가 세 개나 남았어요.",ok:!0},{text:"시험 문제가 세 개만 남았어요.",ok:!1},{text:"시험 문제가 세 개밖에 남았어요.",ok:!1}],explanation:"이나/나 after a number shows the amount feels large or surprising."},{kind:"drill",prompt:"Which pair shows the difference between 만 and 밖에?",sentence:null,options:[{text:"커피만 마셨어요 / 커피밖에 못 마셨어요",ok:!0},{text:"커피만 못 마셨어요 / 커피밖에 마셨어요",ok:!1},{text:"커피만 마셨어요 / 커피밖에 마셨어요",ok:!1}],explanation:"만 works with a positive predicate; 밖에 needs a negative predicate."},{kind:"drill",prompt:"Which sentence naturally marks possession?",sentence:null,options:[{text:"친구의 책도 돌려줘야 해요.",ok:!0},{text:"친구에게 책도 돌려줘야 해요.",ok:!1},{text:"친구밖에 책도 돌려줘야 해요.",ok:!1}],explanation:"의 links 친구 to 책: the friend's book."},{kind:"drill",prompt:"선생님___ 이메일을 보냈어요. (I sent an email to the teacher.)",sentence:null,options:[{text:"께",ok:!0},{text:"께서",ok:!1},{text:"를",ok:!1}],explanation:"께 respectfully marks the receiver of the email. 께서 would mark the teacher as a respected subject, and 를 would make the teacher a direct object."},{kind:"drill",prompt:"Which sentence means “I only drink coffee” without the scarcity feeling?",sentence:null,options:[{text:"커피만 마셔요.",ok:!0},{text:"커피밖에 안 마셔요.",ok:!1},{text:"커피라도 마셔요.",ok:!1}],explanation:"만 simply limits the choice to coffee. 밖에 plus negative adds a stronger “nothing except” feeling."}],canDo:"Use 밖에 + negative for 'only', and 마다 for 'every' (한 시간밖에 없어요 · 주말마다)",id:"chapter-42-b14",chapterId:"chapter-42",index:13}]},{id:"chapter-43",number:43,title:"Counting Word Order: Noun + Number + Counter · Native-Number Contractions Before a Counter",goal:"Use noun + number + counter order confidently.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 개~",cards:[{kind:"guess",word:{ko:"개",romanization:"gae",en:"general counter for things",pos:"counter",nuance:"개 is the general counter for things. Everyday counts normally use native-number forms such as 한 개, 두 개, and 세 개; formal labels and technical contexts can follow other numbering conventions."},sentence:{ko:"의자 네 개가 필요해요.",en:"We need four chairs."},target:"개",options:["general counter for things","student","puppy; dog"],note:"Linked to dictionary card word-ext-010."},{kind:"guess",word:{ko:"명",romanization:"myeong",en:"counter for people",pos:"counter",nuance:"명 is the neutral counter for people; use the honorific counter 분 when respect is relevant. Everyday counts normally use 한 명, 두 명, 세 명, and 네 명."},sentence:{ko:"학생 세 명이 와요.",en:"Three students are coming."},target:"명",options:["student","counter for people","puppy; dog"],note:"Linked to dictionary card word-ext-011."},{kind:"guess",word:{ko:"마리",romanization:"mari",en:"counter for animals",pos:"counter",nuance:"마리 is the universal counter for animals — dogs, cats, fish, birds, insects, livestock, and even a whole cooked chicken or fish on the table. Crucially it is size-independent: the same word counts an ant (개미 한 마리) and an elephant (코끼리 한 마리). 마리 is native Korean (no hanja) and takes native numbers. Its single most important contrast is with 명, the counter for PEOPLE: animals are 마리, humans are 명, and crossing that line matters socially. 마리 is also distinct from 분, the honorific people-counter. The big English-speaker pitfall is using 마리 for people because English says 'two' for both — but calling a person 한 마리 is insulting or mocking (treating them like an animal); always use 명 (or honorific 분) for humans. A second slip is the generic 개 for animals, which sounds wrong — creatures take 마리."},sentence:{ko:"강아지 한 마리도 데려온대요.",en:"They say they are bringing one dog too."},target:"마리",options:["counter for animals","student","puppy; dog"],note:"Linked to dictionary card word-ext-691."},{kind:"guess",word:{ko:"잔",romanization:"jan",en:"counter for cups/glasses",pos:"counter",nuance:"잔 is the counter for a serving of liquid held in a cup or glass — it counts the POURED drink, not the container itself. Its near-rivals are 병 (a whole bottle) and 컵 (the physical cup as an object), and the dividing line is what you're measuring: 맥주 한 병 is a full bottle, 맥주 한 잔 is one glass poured from it. The hanja is 盞 ('small cup'), though it feels fully native in use and always takes native-Korean numbers (한, 두, 세 잔), never Sino-Korean 일/이. Watch two traps: 한잔하다 written together is a VERB ('go for a drink') and is idiomatic, so don't read it as a literal count; and English 'a cup of coffee' tempts learners to reach for 컵, but the natural measure word for the drink itself is 잔."},sentence:{ko:"커피 네 잔 준비할게요.",en:"I will prepare four cups of coffee."},target:"잔",options:["student","counter for cups/glasses","puppy; dog"],note:"Linked to dictionary card word-ext-682."},{kind:"guess",word:{ko:"권",romanization:"gwon",en:"counter for books and volumes",pos:"counter",nuance:"권 is the counter for anything BOUND into a spine — novels, textbooks, notebooks, magazines, and each separate volume of a multi-volume series. Its critical contrast is with 장, which counts a single loose SHEET: 종이 한 장 is one sheet of paper, but the whole bound book made of many sheets is 책 한 권. The hanja is 卷, originally 'a scroll/roll', which is why it now measures a complete bound work. It always takes native-Korean numbers and is among the most frequent counters when you talk about reading or studying. The classic English-speaker pitfall is defaulting to the all-purpose 개 ('책 두 개') because English just says 'two books' — but printed/bound works specifically take 권; a related slip is using 권 for a single page, when one page is 한 장."},sentence:{ko:"안내 책도 두 권만 주세요.",en:"Please give me just two guide books too."},target:"권",options:["counter for books and volumes","student","puppy; dog"],note:"Linked to dictionary card word-ext-685."},{kind:"guess",word:{ko:"장",romanization:"jang",en:"counter for flat sheets",pos:"counter",nuance:"장 counts flat, thin items — sheets of paper, tickets, photographs, banknotes, stickers, postcards, and even thin foods like a sheet of dried seaweed (김) or a slice of cheese. Its sharpest contrast is with 권: 장 is the single loose SHEET, whereas many sheets bound together become 책 한 권 (a book). The hanja is 張, meaning 'to stretch/spread out flat', which captures exactly the flatness it measures. It always takes native numbers and is one of the most-used counters in daily errands — at ticket counters, copy machines, and photo booths. The English-speaker pitfall is reaching for 개 (a generic count) for tickets and photos because English says 'two tickets'; the natural, expected counter is 장. A second trap is using 장 for a whole magazine or book, which is 권, since those are bound, not loose."},sentence:{ko:"종이 열 장이면 돼요.",en:"Ten sheets of paper are enough."},target:"장",options:["counter for flat sheets","student","puppy; dog"],note:"Linked to dictionary card word-ext-686."},{kind:"payoff",line:{speaker:"지훈",ko:"학생 세 명이 오고, 강아지 한 마리도 데려온대요.",en:"Three students are coming, and they say they are bringing one dog too."},hl:"마리"}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b1",chapterId:"chapter-43",index:0},{kind:"pattern",title:"문법 Grammar · Counting Word Order: Noun + Number + Counter",cards:[{kind:"teach",name:"Counting Word Order: Noun + Number + Counter",sub:"",rows:[{when:"Basic count of a thing",add:"noun + (space) number + (space) counter",ex:"사과 세 개 = three apples (apple / three / units)"},{when:"Add a verb after the count",add:"keep noun + number + counter, then verb",ex:"커피 두 잔 주세요 = please give me two coffees"},{when:"Mark the counted noun as object",add:"the object particle 을/를 goes on the NOUN, not on the counter",ex:"빵을 네 개 샀어요 = I bought four pieces of bread"}],examples:[{ko:"사과 세 개 주세요.",en:"Please give me three apples.",romanization:"sagwa se gae juseyo.",note:"Order is noun (사과) → number (세) → counter (개); no particle joins 세 and 개."},{ko:"고양이 두 마리가 있어요.",en:"There are two cats.",romanization:"goyangi du mari-ga isseoyo.",note:"The subject particle 가 attaches to the counter 마리 at the end of the count phrase, not to 고양이."}],more:{func:"To count things in Korean, you name the thing first, then say how many. The pattern is NOUN + NUMBER + COUNTER, with no particle between the number and the counter. English says 'three apples'; Korean says 'apple three (units)' — 사과 세 개.",funcLead:"To count things in Korean, you name the thing first, then say how many.",keyPoint:{label:"Korean reverses the English order",body:"English usually uses number + noun ('three apples'). Standard Korean counting uses noun + number + counter (사과 세 개). In short lists or elliptical speech you may also hear a counter omitted, but noun + number + counter is the reliable full pattern for learners."},pronunciation:"",pitfall:{wrong:"세 사과 (se sagwa)",right:"사과 세 개 (sagwa se gae)",explanation:"English speakers often copy 'three apples' and put the number first with no counter. The reliable full Korean pattern puts the noun first and a counter word after the number: 사과 세 개."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please give me three apples."',tokens:["사과","세","개","주세요."],correct:"사과 세 개 주세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "There are two cats."',tokens:["고양이","두","마리가","있어요."],correct:"고양이 두 마리가 있어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"사과 세 개 (sagwa se gae)",ok:!0},{text:"세 사과 (se sagwa)",ok:!1}],explanation:"English speakers often copy 'three apples' and put the number first with no counter. The reliable full Korean pattern puts the noun first and a counter word after the number: 사과 세 개."}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b2",chapterId:"chapter-43",index:1},{kind:"words",title:"단어 Words 2 · 벌~",cards:[{kind:"guess",word:{ko:"벌",romanization:"beol",en:"counter for sets of clothing",pos:"counter",nuance:"벌 counts clothing as a COMPLETE garment or a coordinated outfit, so a suit, dress, hanbok, or pajama set is 한 벌 even though it physically has several pieces — the counter measures the whole worn unit, not the parts. Its near-synonyms split by what they measure: 벌 is the full set, while 장 counts a single flat piece (티셔츠 한 장 — one tee) and 개 is the casual generic count. 벌 is native Korean (no hanja) and takes native numbers. The biggest English-speaker trap is logic-counting the pieces: a two-piece suit feels like 'two items', but the matching set is 한 벌, not 두 벌. A second trap is genre confusion — clothes are 벌, but the shoes that complete the look are 켤레, so don't say 신발 한 벌."},sentence:{ko:"옷 한 벌만 챙겼어요.",en:"I packed only one set of clothes."},target:"벌",options:["student","puppy; dog","counter for sets of clothing"],note:"Linked to dictionary card word-ext-684."},{kind:"guess",word:{ko:"대",romanization:"dae",en:"counter for vehicles and machines",pos:"counter",nuance:"대 is the all-purpose counter for machines and vehicles — cars, motorcycles, bicycles, computers, phones, cameras, TVs, washing machines, and air conditioners — basically anything mechanical or electronic, so a resident reaches for it constantly when talking about appliances. The hanja is 臺 ('platform/stand'), historically the base a machine sat on, which is why it measures equipment. It contrasts with 채 (whole buildings) and 명 (people): the vehicle is 대, the people riding inside it are 명. It always takes native-Korean numbers. The main English-speaker pitfall is reaching for the generic 개 ('차 두 개') because English just says 'two cars'; machines and vehicles specifically take 대. A subtler trap is counting passengers with 대 — only the machine is 대, while the humans in it are counted with 명."},sentence:{ko:"노트북 한 대가 필요해요.",en:"We need one laptop."},target:"대",options:["student","counter for vehicles and machines","puppy; dog"],note:"Linked to dictionary card word-ext-687."},{kind:"guess",word:{ko:"번",romanization:"beon",en:"counter for times or number labels",pos:"counter",nuance:"번 (한자 番) is the counter for an assigned, ordered number — bus and route numbers, subway exits, exam questions, list items, jersey and seat numbers — and in this ID sense it always takes Sino-Korean numbers: 삼 번 출구, 오 번 버스, never 세 번 출구. Its tricky twin is the homograph 번 meaning 'times/occasions', which takes NATIVE numbers: 세 번 (three times), 다섯 번 (five times). The dividing line is meaning, not spelling: does 번 label a thing (use Sino) or count repetitions (use native)? A near-synonym for the labelling sense is 호(號), but 호 attaches to rooms and issue/model numbers (302호, 창간호) while 번 covers routes, exits, and questions. The English-speaker pitfall is the Sino/native split inside a single counter: learners who have just mastered '세 번 = three times' over-apply native numbers to bus and exit numbers, producing 세 번 버스 — which a Korean parses as 'the bus, three times', not 'bus number 3'. Anchor it with the contrast pair 삼 번 (No. 3) vs. 세 번 (3 times)."},sentence:{ko:"벌써 세 번 해 봤어요.",en:"I have already tried it three times."},target:"번",options:["student","puppy; dog","counter for times or number labels"],note:"Linked to dictionary card word-ext-1424."},{kind:"guess",word:{ko:"학생",romanization:"haksaeng",en:"student",pos:"noun",nuance:"학생 is a common identity word. Use 이에요 after 학생 because it ends in a consonant."},sentence:{ko:"학생 세 명이 와요.",en:"Three students are coming."},target:"학생",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-noun-001."},{kind:"guess",word:{ko:"강아지",romanization:"gangaji",en:"puppy; dog",pos:"noun",nuance:"강아지 literally means a puppy (the young of 개 'dog'), but in real Korean life it is the warm, default word people use for any beloved pet dog regardless of age — saying 우리 강아지 about a ten-year-old dog is completely normal and conveys affection, much like English 'puppy' or 'doggy' used fondly. The neutral, technical word for a grown dog is 개, which is what you use in formal writing, signs (개 조심 'beware of dog'), and breed talk; bare 개 can also sound blunt or even appear in insults (이 개 같은...), so 강아지 is the gentler everyday choice. As an endearment, calling a child 우리 강아지 means 'my little darling'. The English-speaker pitfall is register: in a report or formal context use 개, but in warm daily speech 강아지 is right. It ends in a vowel, so it takes 가/를."},sentence:{ko:"강아지 한 마리도 데려온대요.",en:"They say they are bringing one dog too."},target:"강아지",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-ext-216."},{kind:"guess",word:{ko:"커피",romanization:"keopi",en:"coffee",pos:"noun",nuance:"In speech, 커피 마셔요 without 를 is also natural, but learn the full frame first."},sentence:{ko:"커피 네 잔 준비할게요.",en:"I will prepare four cups of coffee."},target:"커피",options:["student","puppy; dog","coffee"],note:"Linked to dictionary card word-noun-013."},{kind:"payoff",line:{speaker:"민서",ko:"오늘 체험 수업에 학생 몇 명 와요?",en:"How many students are coming to today's trial class?"},hl:"학생"}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b3",chapterId:"chapter-43",index:2},{kind:"pattern",title:"문법 Grammar · Native-Number Contractions Before a Counter",cards:[{kind:"teach",name:"Native-Number Contractions Before a Counter",sub:"",rows:[{when:"하나 + counter",add:"하나 → 한",ex:"한 개 = one item (NOT 하나 개)"},{when:"둘 + counter",add:"둘 → 두",ex:"두 잔 = two cups"},{when:"셋 + counter",add:"셋 → 세",ex:"세 명 = three people"},{when:"넷 + counter",add:"넷 → 네",ex:"네 마리 = four animals"},{when:"스물 + counter",add:"스물 → 스무",ex:"스무 살 = twenty years old"}],examples:[{ko:"커피 한 잔 마셨어요.",en:"I drank one cup of coffee.",romanization:"keopi han jan masyeosseoyo.",note:"하나 contracts to 한 before the counter 잔; saying 하나 잔 is wrong."},{ko:"연필 두 자루 빌려주세요.",en:"Please lend me two pencils.",romanization:"yeonpil du jaru billyeo-juseyo.",note:"둘 becomes 두 before 자루, the counter for pencils and pen-shaped things."}],more:{func:"Korean native numbers 하나, 둘, 셋, 넷 and 스물 change shape when a counter follows them. They drop their final part: 하나→한, 둘→두, 셋→세, 넷→네, 스물→스무. Use the contracted form only when a counter comes right after.",funcLead:"Korean native numbers 하나, 둘, 셋, 넷 and 스물 change shape when a counter follows them.",keyPoint:{label:"Contract only before a counter",body:"하나/둘/셋/넷/스물 keep their full form when counting alone ('하나, 둘, 셋…') but contract to 한/두/세/네/스무 the moment a counter follows. Compare: 사과가 하나 있어요 (one apple, no counter) vs. 사과 한 개 있어요 (one apple, with counter 개)."},pronunciation:"",pitfall:{wrong:"하나 개, 둘 잔, 넷 마리",right:"한 개, 두 잔, 네 마리",explanation:"Learners memorize 하나/둘/셋/넷 and use them unchanged. Before any counter they MUST contract to 한/두/세/네. This is one of the most common beginner mistakes."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I drank one cup of coffee."',tokens:["커피","한","잔","마셨어요."],correct:"커피 한 잔 마셨어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please lend me two pencils."',tokens:["연필","두","자루","빌려주세요."],correct:"연필 두 자루 빌려주세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"하나 개, 둘 잔, 넷 마리",ok:!1},{text:"한 개, 두 잔, 네 마리",ok:!0}],explanation:"Learners memorize 하나/둘/셋/넷 and use them unchanged. Before any counter they MUST contract to 한/두/세/네. This is one of the most common beginner mistakes."}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b4",chapterId:"chapter-43",index:3},{kind:"words",title:"단어 Words 3 · 책~",cards:[{kind:"guess",word:{ko:"책",romanization:"chaek",en:"book",pos:"noun",nuance:"책 is useful with 읽다, 사다, 있다, and 없다. It also helps beginners practice object marker 을 because 책 ends in a consonant."},sentence:{ko:"책 두 권만 주세요.",en:"Please give me just two books."},target:"책",options:["student","puppy; dog","book"],note:"Linked to dictionary card word-noun-025."},{kind:"guess",word:{ko:"종이",romanization:"jongi",en:"paper",pos:"noun",nuance:"종이 is a pure native Korean word for paper, both as the material (made from 나무/pulp) and as a sheet of it. The crucial point is its counter: flat, thin things are counted with 장 (종이 한 장, 두 장) — the same 장 used for tickets (표 한 장), photos (사진 한 장), and pizza slices, so learning 종이 anchors the whole 'flat-sheet' counter family. Distinguish the raw material 종이 from finished paper products that have their own names: a 신문 (newspaper), a 책 (book), a 공책/노트 (notebook), and a filled-out 서류 (document) are all made of 종이 but are never just called 종이. Useful collocations: 종이에 쓰다/적다 (write on paper), 종이를 접다 (fold paper), 종이를 자르다/찢다 (cut/tear paper). The English-speaker pitfall is twofold: defaulting to 개 instead of 장 to count sheets, and using 종이 for a form you must complete — that is 서류 (paperwork) or the document's specific name."},sentence:{ko:"종이는 몇 장 필요해요?",en:"How many sheets of paper do we need?"},target:"종이",options:["student","paper","puppy; dog"],note:"Linked to dictionary card word-ext-1374."},{kind:"guess",word:{ko:"의자",romanization:"uija",en:"chair",pos:"noun",nuance:"의자 is Sino-Korean 椅子 ('chair') and covers any seat with legs — dining chairs, office chairs (사무용 의자 or 사무 의자), folding chairs (접이식 의자). The single most common English-speaker error is the particle with 앉다: sitting DOWN is reaching a resting position, so it must be 의자에 앉아요 (에 = destination), not 의자에서 앉아요 — even though English 'sit ON the chair' tempts you toward a location particle. Compare with standing up, which is motion away and DOES take 에서: 의자에서 일어나요. Distinguish 의자 (chair, you sit on it) from 소파 (sofa/couch, plush multi-seat) and 책상 (desk) — beginners sometimes pair them loosely. The set phrase for offering someone a seat is 의자를 빼 드리다 (pull the chair out for them). Register is neutral."},sentence:{ko:"의자 네 개가 필요해요.",en:"We need four chairs."},target:"의자",options:["student","chair","puppy; dog"],note:"Linked to dictionary card word-ext-065."},{kind:"guess",word:{ko:"옷",romanization:"ot",en:"clothes",pos:"noun",nuance:"옷 is a pure native Korean word (no hanja) meaning clothes/clothing for the body, and the verb you MUST pair it with is 입다 (to wear on the torso/body) — never 신다, which is reserved for footwear on the feet (신발을 신다), nor 쓰다 (hats/glasses) nor 끼다 (gloves/rings). English 'wear/put on' covers every garment with one verb, so this split is the central pitfall: 옷을 신어요 is a classic beginner error. To take clothes off is 벗다, to change them 갈아입다. For 'these clothes look good on you,' Korean says 옷이 잘 어울려요 (the clothes suit you), not a direct translation of 'you look good.' Note 옷 is treated as singular/uncountable grammatically (no plural needed): one outfit or a wardrobe full is still just 옷. The dressier counterpart 의상 (costume/attire, 衣裳) is for performances or formal contexts. Register is neutral and everyday."},sentence:{ko:"옷 한 벌만 챙겼어요.",en:"I packed only one set of clothes."},target:"옷",options:["student","puppy; dog","clothes"],note:"Linked to dictionary card word-ext-067."},{kind:"guess",word:{ko:"사진",romanization:"sajin",en:"photo",pos:"noun",nuance:"사진 is usually paired with 찍다 for taking photos."},sentence:{ko:"사진 세 장만 보내 주세요.",en:"Please send just three photos."},target:"사진",options:["student","photo","puppy; dog"],note:"Linked to dictionary card word-noun-023."},{kind:"payoff",line:{speaker:"민서",ko:"그럼 의자 네 개랑 커피 네 잔 준비할게요.",en:"Then I will prepare four chairs and four cups of coffee."},hl:"의자"}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b5",chapterId:"chapter-43",index:4},{kind:"pattern",title:"문법 Grammar · Counting People and Animals: 명 / 분 / 마리",cards:[{kind:"teach",name:"Counting People and Animals: 명 / 분 / 마리",sub:"",rows:[{when:"Counting people (neutral/plain)",add:"native number (contracted) + 명",ex:"학생 세 명 = three students"},{when:"Counting people politely (honorific)",add:"native number (contracted) + 분",ex:"손님 두 분 = two guests"},{when:"Counting any animal",add:"native number (contracted) + 마리",ex:"개 한 마리 = one dog"}],examples:[{ko:"교실에 학생 다섯 명이 있어요.",en:"There are five students in the classroom.",romanization:"gyosil-e haksaeng daseot myeong-i isseoyo.",note:"명 is the neutral counter for people: classmates, friends, ordinary people."},{ko:"할머니 두 분이 오셨어요.",en:"Two grandmothers came.",romanization:"halmeoni du bun-i osyeosseoyo.",note:"분 is the honorific counter, right for elders; the verb is also honorific 오셨어요."}],more:{func:"People are counted with 명 (plain) or 분 (honorific, for people you respect). Animals — pets, fish, birds, insects — are all counted with 마리.",funcLead:"People are counted with 명 (plain) or 분 (honorific, for people you respect).",keyPoint:{label:"명 vs. 분 = respect level",body:"명 and 분 both count people; the difference is politeness. Use 분 for guests, elders, teachers, and customers; use 명 for friends, kids, or a general headcount. Never use 분 for yourself. Animals always take 마리, never 명."},pronunciation:"",pitfall:{wrong:"손님 두 명이 왔어요 (said to a customer's face)",right:"손님 두 분이 오셨어요",explanation:"English has no built-in 'respect counter,' so learners default to 명 for everyone. For guests, elders, and customers, use the honorific 분 to sound polite."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "There are five students in the classroom." (교실에 시작 · Start with 교실에.)',tokens:["교실에","학생","다섯","명이","있어요."],correct:"교실에 학생 다섯 명이 있어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Two grandmothers came."',tokens:["할머니","두","분이","오셨어요."],correct:"할머니 두 분이 오셨어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"손님 두 분이 오셨어요",ok:!0},{text:"손님 두 명이 왔어요 (said to a customer's face)",ok:!1}],explanation:"English has no built-in 'respect counter,' so learners default to 명 for everyone. For guests, elders, and customers, use the honorific 분 to sound polite."}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b6",chapterId:"chapter-43",index:5},{kind:"pattern",title:"문법 Grammar · Counting Objects, Drinks, Books, and Sheets: 개 / 잔 / 권 / 장",cards:[{kind:"teach",name:"Counting Objects, Drinks, Books, and Sheets: 개 / 잔 / 권 / 장",sub:"",rows:[{when:"General object (default counter)",add:"number + 개",ex:"사탕 두 개 = two candies"},{when:"A drink served in a cup or glass",add:"number + 잔",ex:"물 한 잔 = one glass of water"},{when:"A book or notebook",add:"number + 권",ex:"책 세 권 = three books"},{when:"A thin flat sheet",add:"number + 장",ex:"종이 네 장 = four sheets of paper"}],examples:[{ko:"지우개 두 개만 주세요.",en:"Please give me just two erasers.",romanization:"jiugae du gae-man juseyo.",note:"개 is the all-purpose counter for everyday objects like erasers."},{ko:"녹차 한 잔 더 주세요.",en:"One more cup of green tea, please.",romanization:"nokcha han jan deo juseyo.",note:"잔 counts drinks served in a cup or glass — tea, coffee, water, juice."}],more:{func:"Different kinds of things take different counters. 개 = general objects, 잔 = cups/glasses of a drink, 권 = books and notebooks, 장 = flat sheets (paper, tickets, photos).",funcLead:"Different kinds of things take different counters.",keyPoint:{label:"개 is the safe default",body:"When you don't know the right counter, 개 usually works for objects. But the specific counters are expected for their categories: drinks → 잔, books → 권, flat sheets → 장. Saying 책 세 개 is understandable but sounds like a learner; 책 세 권 is correct."},pronunciation:"권 ends in a clear final ㄴ; before 을 it links as 권을 [궈늘 / gwo-neul]. 장을 links as [장을 / jang-eul] with the ㅇ carrying over.",pitfall:{wrong:"책 세 개, 커피 두 개",right:"책 세 권, 커피 두 잔",explanation:"English uses 'three books / two coffees' with no special unit, so learners overuse 개. Match the counter to the category: 권 for books, 잔 for cups of a drink."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please give me just two erasers."',tokens:["지우개","두","개만","주세요."],correct:"지우개 두 개만 주세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "One more cup of green tea, please."',tokens:["녹차","한","잔","더","주세요."],correct:"녹차 한 잔 더 주세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"책 세 개, 커피 두 개",ok:!1},{text:"책 세 권, 커피 두 잔",ok:!0}],explanation:"English uses 'three books / two coffees' with no special unit, so learners overuse 개. Match the counter to the category: 권 for books, 잔 for cups of a drink."}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b7",chapterId:"chapter-43",index:6},{kind:"pattern",title:"문법 Grammar · Counting Clothes and Machines: 벌 / 대",cards:[{kind:"teach",name:"Counting Clothes and Machines: 벌 / 대",sub:"",rows:[{when:"A set or suit of clothes",add:"number + 벌",ex:"옷 한 벌 = one set of clothes"},{when:"Another outfit or suit",add:"number + 벌",ex:"양복 두 벌 = two suits"},{when:"A car or vehicle",add:"number + 대",ex:"차 한 대 = one car"},{when:"A machine or appliance",add:"number + 대",ex:"컴퓨터 두 대 = two computers"}],examples:[{ko:"새 옷 한 벌 샀어요.",en:"I bought one new set of clothes.",romanization:"sae ot han beol sasseoyo.",note:"벌 counts a full outfit, not single garments; 한 from 하나 before the counter."},{ko:"양복 두 벌이 필요해요.",en:"I need two suits.",romanization:"yangbok du beol-i piryohaeyo.",note:"벌 also counts suits and other matched sets of clothing."}],more:{func:"벌 counts sets of clothing — an outfit, a suit, pajamas. 대 counts machines and vehicles — cars, phones, computers, TVs, anything mechanical.",funcLead:"벌 counts sets of clothing — an outfit, a suit, pajamas.",keyPoint:{label:"벌 = clothing sets, 대 = machines",body:"Use 벌 for clothes you wear as a set (옷 한 벌, 양복 두 벌) and 대 for anything mechanical (차 한 대, 핸드폰 두 대, 세탁기 한 대). Don't reach for 개 here — 차 한 개 or 옷 한 개 sounds clearly wrong to native ears."},pronunciation:"",pitfall:{wrong:"차 한 개, 옷 두 개",right:"차 한 대, 옷 두 벌",explanation:"Learners fall back on the all-purpose 개, but vehicles and machines need 대 and sets of clothing need 벌. 차 한 개 and 옷 한 개 sound clearly wrong to native speakers."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I bought one new set of clothes."',tokens:["새","옷","한","벌","샀어요."],correct:"새 옷 한 벌 샀어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I need two suits."',tokens:["양복","두","벌이","필요해요."],correct:"양복 두 벌이 필요해요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"차 한 개, 옷 두 개",ok:!1},{text:"차 한 대, 옷 두 벌",ok:!0}],explanation:"Learners fall back on the all-purpose 개, but vehicles and machines need 대 and sets of clothing need 벌. 차 한 개 and 옷 한 개 sound clearly wrong to native speakers."}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b8",chapterId:"chapter-43",index:7},{kind:"pattern",title:"문법 Grammar · Counting Time and Frequency: 번 / 시간 / 살",cards:[{kind:"teach",name:"Counting Time and Frequency: 번 / 시간 / 살",sub:"",rows:[{when:"Number of times (occurrences)",add:"number + 번",ex:"한 번 = one time / once"},{when:"Repeating an action",add:"number + 번",ex:"세 번 봤어요 = I saw it three times"},{when:"Duration in hours",add:"number + 시간",ex:"두 시간 = two hours"},{when:"A person's age",add:"number + 살",ex:"스무 살 = twenty years old"}],examples:[{ko:"그 영화를 두 번 봤어요.",en:"I watched that movie twice.",romanization:"geu yeonghwa-reul du beon bwasseoyo.",note:"번 counts how many times; 둘 contracts to 두 before it."},{ko:"하루에 세 번 약을 먹어요.",en:"I take medicine three times a day.",romanization:"haru-e se beon yag-eul meogeoyo.",note:"번 with a native number gives the frequency of an action."}],more:{func:"번 counts the number of times something happens (once, twice). 시간 counts hours of duration. 살 counts years of age. All three take native numbers, contracted before the counter.",funcLead:"번 counts the number of times something happens (once, twice).",keyPoint:{label:"시간 (duration) vs. 시 (o'clock)",body:"세 시간 means 'three hours' (how long), but 세 시 means 'three o'clock' (what time). Both use native numbers but answer different questions. 번 counts occurrences (한 번 = once), and 살 counts age (열 살 = ten years old)."},pronunciation:"",pitfall:{wrong:"세 시간 (used for 'at three o'clock')",right:"세 시에 (at three o'clock) vs. 세 시간 (for three hours)",explanation:"English 'three hours' and 'three o'clock' look alike, so learners mix up 시간 and 시. Use 시간 for how long something lasts and 시 for the time on the clock."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I watched that movie twice."',tokens:["그","영화를","두","번","봤어요."],correct:"그 영화를 두 번 봤어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I take medicine three times a day." (하루에 시작 · Start with 하루에.)',tokens:["하루에","세","번","약을","먹어요."],correct:"하루에 세 번 약을 먹어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"세 시에 (at three o'clock) vs. 세 시간 (for three hours)",ok:!0},{text:"세 시간 (used for 'at three o'clock')",ok:!1}],explanation:"English 'three hours' and 'three o'clock' look alike, so learners mix up 시간 and 시. Use 시간 for how long something lasts and 시 for the time on the clock."}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b9",chapterId:"chapter-43",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two staff members prepare supplies for a small trial class.",lines:[{speaker:"민서",ko:"오늘 체험 수업에 학생 몇 명 와요?",en:"How many students are coming to today's trial class?",romanization:"oneul cheheom sueobe haksaeng myeot myeong wayo?"},{speaker:"지훈",ko:"학생 세 명이 오고, 강아지 한 마리도 데려온대요.",en:"Three students are coming, and they say they are bringing one dog too.",romanization:"haksaeng se myeongi ogo, gangaji han marido deryeondaeyo."},{speaker:"민서",ko:"그럼 의자 네 개랑 커피 네 잔 준비할게요.",en:"Then I will prepare four chairs and four cups of coffee.",romanization:"geureom uija ne gaerang keopi ne jan junbihalgeyo."},{speaker:"지훈",ko:"종이는 몇 장 필요해요?",en:"How many sheets of paper do we need?",romanization:"jongineun myeot jang piryohaeyo?"},{speaker:"민서",ko:"열 장이면 돼요. 안내 책도 두 권만 주세요.",en:"Ten sheets are enough. Please give me just two guide books too.",romanization:"yeol jangimyeon dwaeyo. annae chaekdo du gwonman juseyo."},{speaker:"지훈",ko:"이 준비는 벌써 세 번 해 봐서 괜찮아요.",en:"We have already done this prep three times, so it is fine.",romanization:"i junbineun beolsseo se beon hae bwaseo gwaenchanayo."}]},{kind:"order",prompt:"Build: 'two cups of coffee'",tokens:["커피","두 잔"],correct:"커피 두 잔",explanation:"Korean counter order is noun + number + counter. 잔 is the counter for cups or glasses."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"학생 세 명이 오고, 강아지 한 마리도 데려온대요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"Three students are coming, and they say they are bringing one dog too."},{kind:"drill",prompt:`무엇이 들어갈까요? · "How many students are coming to today's trial class?"`,sentence:"오늘 체험 수업에 ___ 몇 명 와요?",options:[{text:"강아지",ok:!1},{text:"학생",ok:!0},{text:"커피",ok:!1}],explanation:""}],canDo:"Order a count as NOUN + NUMBER + COUNTER (학생이 세 명)",id:"chapter-43-b10",chapterId:"chapter-43",index:9},{kind:"reading",title:"읽기 Reading · 몇 개가 아니라 무엇을 세는지 먼저 보기",cards:[{kind:"read",title:"몇 개가 아니라 무엇을 세는지 먼저 보기",chunks:["한국어에서 수량을 말할 때는 숫자만 맞으면 끝이 아니에요. 무엇을 세는지 먼저 봐야 해요. 학생은 세 명, 강아지는 한 마리, 커피는 네 잔, 책은 두 권, 종이는 열 장처럼 명사에 맞는 단위가 달라져요.","처음에는 개를 모든 물건에 붙이고 싶지만, 책 두 개보다 책 두 권이 자연스럽고, 사진 세 개보다 사진 세 장이 자연스러워요. 또 하나, 둘, 셋, 넷은 단위명사 앞에서 한, 두, 세, 네로 줄어들어요. 그래서 하나 명이 아니라 한 명, 둘 잔이 아니라 두 잔이라고 말해요."],translation:"In Korean, counting is not only about choosing the right number. You first look at what kind of thing you are counting. Students are counted with 명, animals with 마리, cups of coffee with 잔, books with 권, and sheets of paper or photos with 장. The first few native Korean numbers also contract before counters: 하나 becomes 한, 둘 becomes 두, 셋 becomes 세, and 넷 becomes 네.",qas:[{q:"학생을 셀 때 어떤 단위명사를 써요?",a:"명"},{q:"책 두 개보다 어떤 표현이 더 자연스러워요?",a:"책 두 권"},{q:"하나, 둘, 셋, 넷은 단위명사 앞에서 어떻게 바뀌어요?",a:"한, 두, 세, 네로 바뀌어요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"학생은 세 명, ___는 한 마리, 커피는 네 잔, 책은 두 권, 종이는 열 장처럼 명사에 맞는 단위가 달라져요.",options:[{text:"의자",ok:!1},{text:"옷",ok:!1},{text:"강아지",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"처음에는 개를 모든 물건에 붙이고 싶지만, 책 두 개보다 책 두 권이 자연스럽고, ___ 세 개보다 사진 세 장이 자연스러워요.",options:[{text:"의자",ok:!1},{text:"옷",ok:!1},{text:"사진",ok:!0}],explanation:""}],canDo:"Contract native numbers before a counter (하나→한 · 둘→두 · 셋→세 · 넷→네)",id:"chapter-43-b11",chapterId:"chapter-43",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which counter fits students?",sentence:null,options:[{text:"학생 세 명",ok:!0},{text:"학생 세 마리",ok:!1},{text:"학생 세 잔",ok:!1}],explanation:"명 counts people."},{kind:"drill",prompt:"Which counter fits a dog?",sentence:null,options:[{text:"강아지 한 마리",ok:!0},{text:"강아지 한 명",ok:!1},{text:"강아지 한 권",ok:!1}],explanation:"마리 counts animals."},{kind:"drill",prompt:"Which counter fits coffee?",sentence:null,options:[{text:"커피 두 잔",ok:!0},{text:"커피 두 장",ok:!1},{text:"커피 두 권",ok:!1}],explanation:"잔 counts cups or glasses."},{kind:"drill",prompt:"Which counter fits books?",sentence:null,options:[{text:"책 두 권",ok:!0},{text:"책 두 잔",ok:!1},{text:"책 두 마리",ok:!1}],explanation:"권 counts books and volumes."},{kind:"drill",prompt:"Which sentence counts occurrences?",sentence:null,options:[{text:"세 번 해 봤어요.",ok:!0},{text:"세 권 해 봤어요.",ok:!1},{text:"세 잔 해 봤어요.",ok:!1}],explanation:"번 counts occurrences or number labels depending on context."},{kind:"drill",prompt:"학생 세 명___ 왔어요. (Three students came.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"The counted group is the subject that came, so 명 takes 이 here. 을 would make the students an object."},{kind:"drill",prompt:"Which phrase counts two dogs naturally?",sentence:null,options:[{text:"강아지 두 마리",ok:!0},{text:"강아지 둘 개",ok:!1},{text:"강아지 이 명",ok:!1}],explanation:"Animals take 마리, and two before a counter is 두. 명 counts people, not animals."}],canDo:"Pick the right counter for people, animals, and objects (명 · 마리 · 잔 · 권 · 개)",id:"chapter-43-b12",chapterId:"chapter-43",index:11}]},{id:"chapter-44",number:44,title:"연음 (Linking): A Final Consonant Slides onto the Next Vowel · 경음화 (Tensing): A Plain Consonant Tenses After a Stop",goal:"Map written Korean to spoken Korean using four high-frequency rules.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"먹어요는 [머거요]처럼 이어져요.",en:"먹어요 links and sounds like [머거요]."},target:"먹어",options:["to sit","to read","to eat"],note:"Linked to dictionary card word-verb-001."},{kind:"guess",word:{ko:"한국어",romanization:"hangugeo",en:"Korean language",pos:"noun",nuance:"한국어 points to the language. 한국 사람 points to a Korean person."},sentence:{ko:"한국어는 [한구거]처럼 이어져요.",en:"한국어 links and sounds like [한구거]."},target:"한국어",options:["Korean language","school","gukbap; soup with rice"],note:"Linked to dictionary card word-ext-ch03-hangugeo."},{kind:"guess",word:{ko:"앉다",romanization:"antda",en:"to sit",pos:"verb",nuance:"앉아 주세요 is a polite request; 앉으세요 is also common and a little more direct."},sentence:{ko:"앉아요는 [안자요]처럼 들려요.",en:"앉아요 sounds like [안자요]."},target:"앉아",options:["to eat","to read","to sit"],note:"Linked to dictionary card word-verb-010."},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"읽어요는 [일거요]처럼 들려요.",en:"읽어요 sounds like [일거요]."},target:"읽어",options:["to read","to eat","to sit"],note:"Linked to dictionary card word-verb-011."},{kind:"guess",word:{ko:"학교",romanization:"hakgyo",en:"school",pos:"noun",nuance:"학교 is one of the clearest words for practicing 에 vs 에서."},sentence:{ko:"학교는 [학꾜]처럼 들려요.",en:"학교 sounds like [학꾜]."},target:"학교",options:["Korean language","gukbap; soup with rice","school"],note:"Linked to dictionary card word-noun-006."},{kind:"guess",word:{ko:"국밥",romanization:"gukbap",en:"gukbap; soup with rice",pos:"noun",nuance:"국밥 is literally 국 'soup' + 밥 'rice' — a hot bowl in which rice is either pre-mixed into the broth (토렴) or served alongside to add yourself, eaten fast and cheap as a complete one-bowl meal. It differs from a plain 국 in that 국밥 is a whole meal (rice included), whereas 국 is just the soup component of a larger spread. The defining verb to learn is 말다 'to put/swirl rice into soup' — 밥을 국에 말다 — which has no clean English equivalent and trips learners up. 국밥 is the classic 해장 'hangover-cure' food, and Busan's 돼지국밥 (pork) is nationally famous. Pitfall: even though it looks like soup, you say 국밥을 먹다 'eat gukbap', not 마시다 'drink', because the rice makes it food, not a beverage — and don't forget the counter 그릇 when ordering a single bowl."},sentence:{ko:"국밥은 [국빱]처럼 들려요.",en:"국밥 sounds like [국빱]."},target:"국밥",options:["gukbap; soup with rice","Korean language","school"],note:"Linked to dictionary card word-ext-707."},{kind:"payoff",line:{speaker:"민서",ko:"먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어져요.",en:"먹어요 is not [meok-eo-yo]; it links and sounds like [머거요]."},hl:"먹어"}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b1",chapterId:"chapter-44",index:0},{kind:"pattern",title:"문법 Grammar · 연음 (Linking): A Final Consonant Slides onto the Next Vowel",cards:[{kind:"teach",name:"연음 (Linking): A Final Consonant Slides onto the Next Vowel",sub:"",rows:[{when:"받침 + a vowel starting with ㅇ",add:"the 받침 moves into the empty ㅇ slot",ex:"한국어 → [한구거]"},{when:"a single 받침 (ㄱ/ㄴ/ㄹ/ㅁ/ㅂ/ㅅ etc.) before a vowel",add:"that consonant becomes the next syllable's onset",ex:"음악 → [으막], 옷이 → [오시]"},{when:"a double 받침 (겹받침) before a vowel",add:"the first consonant stays, the second links over",ex:"읽어요 → [일거요], 앉아요 → [안자요]"},{when:"받침 ㅇ before a vowel",add:"no linking; ㅇ [ŋ] stays where it is",ex:"고양이 → [고양이] (the ㅇ does not move)"}],examples:[{ko:"한국어 발음이 어려워요.",en:"Korean pronunciation is hard.",romanization:"han-gu-geo ba-reu-mi eo-ryeo-wo-yo",note:"한국어 → [한구거] (국's ㄱ links to 어); 발음이 → [바르미] (음's ㅁ links to 이)."},{ko:"이 단어를 읽어 보세요.",en:"Try reading this word.",romanization:"i da-neo-reul il-geo bo-se-yo",note:"단어 → [다너] (단's ㄴ links to 어); 읽어 → [일거] (겹받침 ㄺ splits: ㄹ stays, ㄱ links)."}],more:{func:"When a syllable ends in a 받침 (final consonant) and the next syllable starts with ㅇ (a silent placeholder before a vowel), the 받침 jumps over and is pronounced as the first sound of that next syllable. The spelling never changes — only the sound. This is why 한국어 is said [한구거]: the ㄱ of 국 links onto the 어.",funcLead:"When a syllable ends in a 받침 (final consonant) and the next syllable starts with ㅇ (a silent placeholder before a vowel), the 받침 jumps over and is pronounced a…",keyPoint:{label:"Spelling vs. sound",body:"Linking changes only the sound, never the spelling. You always write 한국어, but you say [한구거]. Reading each syllable as written (han-guk-eo) sounds robotic; native speakers link automatically."},pronunciation:"한국어 is [한구거], not [한국어]. Listen for the 받침 sliding right: 옷이 [오시], 꽃이 [꼬치], 밥을 [바블].",pitfall:{wrong:"han-guk · eo (a hard stop between the syllables)",right:"han-gu-geo (the ㄱ glides into the next syllable)",explanation:"English speakers tend to pronounce every syllable as written and insert a small gap before a vowel. In Korean the 받침 must flow onto the following vowel with no break, so 한국어 sounds like [한구거]."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Korean pronunciation is hard."',tokens:["한국어","발음이","어려워요."],correct:"한국어 발음이 어려워요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Try reading this word."',tokens:["이","단어를","읽어","보세요."],correct:"이 단어를 읽어 보세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"han-guk · eo (a hard stop between the syllables)",ok:!1},{text:"han-gu-geo (the ㄱ glides into the next syllable)",ok:!0}],explanation:"English speakers tend to pronounce every syllable as written and insert a small gap before a vowel. In Korean the 받침 must flow onto the following vowel with no break, so 한국어 sounds like [한구거]."}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b2",chapterId:"chapter-44",index:1},{kind:"words",title:"단어 Words 2 · 국민~",cards:[{kind:"guess",word:{ko:"국민",romanization:"gungmin",en:"citizens; the people of a nation",pos:"noun",nuance:"국민 (國民, 國 'nation' + 民 'people' — 'the people of the nation') means the people as citizens of a particular country: a civic, collective term bound up with rights (권리), duties (의무), and the state. Distinguish it from two neighbors. Against 사람들 ('people' in general): 국민 is people specifically as a national citizenry, so '거리에 사람들이 많아요' (lots of people on the street) could never be 국민. Against 시민 (市民, 'citizens'): 시민 leans toward city residents or civil society (시민 단체 = civic groups, 서울 시민 = Seoul residents), while 국민 frames people in relation to the nation and government. Use 국민 whenever the context is national identity, elections, law, or the state's relationship to its population."},sentence:{ko:"국민은 [궁민]처럼 들려요.",en:"국민 sounds like [궁민]."},target:"국민",options:["Korean language","citizens; the people of a nation","school"],note:"Linked to dictionary card word-ext-1818."},{kind:"guess",word:{ko:"닫다",romanization:"datda",en:"to close",pos:"verb",nuance:"닫다 is the opposite of 열다. Use it for doors, windows, stores, apps, and lids."},sentence:{ko:"닫다는 [닫따]처럼 들려요.",en:"닫다 sounds like [닫따]."},target:"닫다",options:["to eat","to close","to sit"],note:"Linked to dictionary card word-verb-025."},{kind:"guess",word:{ko:"좋다",romanization:"jota",en:"to be good; to like",pos:"adjective",nuance:"좋아요 can mean “it is good” or “I like it.” The subject often takes 이/가."},sentence:{ko:"좋다는 [조타]처럼 들려요.",en:"좋다 sounds like [조타]."},target:"좋다",options:["to be good; to like","to eat","Korean language"],note:"Linked to dictionary card word-adjective-027."},{kind:"guess",word:{ko:"입학하다",romanization:"iphakada",en:"to enroll in school",pos:"verb",nuance:"입학하다 is Sino-Korean 入學 — 入 'enter' + 學 'learning/school' — literally 'enter into learning', i.e. be admitted to and begin a school. Its exact opposite is 졸업하다 (卒業). Here is a beautiful particle trap that mirrors its opposite: 입학하다 uses 에 ('enter INTO' a school — 대학에 입학하다), whereas 졸업하다 uses 를 (대학을 졸업하다). English 'enroll IN' luckily matches the 에 here, but learners who memorized 졸업하다's 를 wrongly carry it over. Don't confuse 입학하다 with 등록하다 'to register': 입학하다 is the once-in-a-school-career act of being admitted, while 등록하다 is the recurring paperwork of signing up (for a term, a course). As a noun+하다 verb it conjugates on 하다 (입학해요, 입학했어요, formal 입학합니다); negative and impossible split the noun (입학 안 해요, 입학 못 해요). Note the pronunciation: 입학 sounds like [이팍], the ㅂ and ㅎ fusing to ㅍ."},sentence:{ko:"입학은 [이팍]처럼 들려요.",en:"입학 sounds like [이팍]."},target:"입학",options:["to eat","to sit","to enroll in school"],note:"Linked to dictionary card word-verb-487."},{kind:"guess",word:{ko:"축하해요",romanization:"chukahaeyo",en:"Congratulations.",pos:"expression",nuance:"축하해요 congratulates someone on genuinely HAPPY news. 축하(祝賀) is Sino-Korean — 祝 'to wish, to celebrate' + 賀 'to congratulate' — and it conjugates as a 하다-verb: 축하하다 → 축하해요 (polite) → 축하합니다 (formal) → 축하해 (casual). The structural pattern is [occasion noun] + 축하해요: 결혼 축하해요, 합격 축하해요, 생일 축하해요, 출산 축하해요. Register is critical: toward a senior, use the humble 축하드려요 / 축하드립니다 (드리다 'to give humbly'), NOT plain 축하해요, because you are offering the congratulation upward as a gift rather than stating it. The English-speaker pitfall is using 축하해요 like the broad English 'congratulations' — in Korean, 축하 is strictly for joyful milestones. For someone going through hardship (failed exam, difficult project, loss) you never 축하; you say 힘내세요 ('stay strong'), 고생했어요 ('you worked hard'), or offer 수고 language. Also, don't conflate with 화이팅 — 화이팅 cheers someone ON before they face a challenge; 축하해요 celebrates AFTER the good outcome has arrived."},sentence:{ko:"축하해요는 [추카해요]처럼 들려요.",en:"축하해요 sounds like [추카해요]."},target:"축하해요",options:["I'm not good at Korean.","to eat","Congratulations."],note:"Linked to dictionary card expr-123."},{kind:"guess",word:{ko:"한국어를 잘 못해요",romanization:"hangugeoreul jal motaeyo",en:"I'm not good at Korean.",pos:"expression",nuance:"한국어를 잘 못해요 = 한국어 (Korean language) + 를 (object marker) + 잘 (well) + 못하다 (to be unable to do well). The key interpretive point: 잘 못하다 means 'can't do it well' (ability is limited), while 안 하다 means 'I don't do it' (by choice). Using 안 하다 — 한국어를 안 해요 — implies you are refusing or unwilling, which is not what you mean. The 잘 softens the claim from 'I can't speak Korean at all' (한국어 못해요) to 'I'm not good at it', which is more accurate and humble. 한국어 is the neutral/formal word for the language, while 한국말 is more colloquial and warm; both are correct. The classic follow-up toolkit: 천천히 말씀해 주세요 ('please speak slowly'), 다시 한 번 말씀해 주시겠어요? ('could you say that again?'), and 영어 하시는 분 계세요? ('is there anyone who speaks English?'). English speakers most often get the particle wrong (한국어가 잘 못해요 — the language is the object, not the subject) or write 잘못해요 as one word, which means 'to do something wrong/make a mistake' — a completely different word."},sentence:{ko:"못해요는 [모태요]처럼 들려요.",en:"못해요 sounds like [모태요]."},target:"못해요",options:["I'm not good at Korean.","Congratulations.","to eat"],note:"Linked to dictionary card expr-394."},{kind:"payoff",line:{speaker:"지훈",ko:"그럼 국민은 [궁민], 먹는은 [멍는]처럼 들리죠?",en:"Then 국민 sounds like [궁민], and 먹는 sounds like [멍는], right?"},hl:"국민"}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b3",chapterId:"chapter-44",index:2},{kind:"pattern",title:"문법 Grammar · 경음화 (Tensing): A Plain Consonant Tenses After a Stop",cards:[{kind:"teach",name:"경음화 (Tensing): A Plain Consonant Tenses After a Stop",sub:"",rows:[{when:"[ㄱ] 받침 + ㄱ/ㄷ/ㅂ/ㅅ/ㅈ",add:"the following consonant tenses",ex:"학교 → [학꾜], 책상 → [책쌍]"},{when:"[ㄷ] 받침 (ㄷ,ㅅ,ㅈ,ㅊ,ㅌ all sound [ㄷ]) + a plain consonant",add:"the following consonant tenses",ex:"숟가락 → [숟까락], 듣고 → [듣꼬]"},{when:"[ㅂ] 받침 (ㅂ,ㅍ sound [ㅂ]) + a plain consonant",add:"the following consonant tenses",ex:"입국 → [입꾹], 잡지 → [잡찌]"},{when:"a plain consonant after ㄴ/ㄹ/ㅁ/ㅇ",add:"usually NO tensing (those are not stops)",ex:"안경 → [안경] (stays plain)"}],examples:[{ko:"학교에서 한국어를 배워요.",en:"I learn Korean at school.",romanization:"hak-kkyo-e-seo han-gu-geo-reul bae-wo-yo",note:"학교 → [학꾜]: the [ㄱ] of 학 tenses the following ㄱ into ㄲ."},{ko:"책상 위에 책이 있어요.",en:"There is a book on the desk.",romanization:"chaek-ssang wi-e chae-gi i-sseo-yo",note:"책상 → [책쌍]: the [ㄱ] 받침 tenses ㅅ to ㅆ. (책이 → [채기] is linking, a separate rule.)"}],more:{func:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is immediately followed by a plain consonant ㄱ, ㄷ, ㅂ, ㅅ, or ㅈ, that following consonant becomes its tense (된소리) version: ㄱ→ㄲ, ㄷ→ㄸ, ㅂ→ㅃ, ㅅ→ㅆ, ㅈ→ㅉ. This is why 학교 is said [학꾜].",funcLead:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is immediately followed by a plain consonant ㄱ, ㄷ, ㅂ, ㅅ, or ㅈ, that following consonant becomes its tense (된소리) version:…",keyPoint:{label:"Tense only after a stop",body:"Tensing happens after the three stop sounds [ㄱ][ㄷ][ㅂ], not after the sonorants ㄴ/ㄹ/ㅁ/ㅇ. Compare 학교 [학꾜] (tensing) with 안경 [안경] (no tensing) — the 받침 in 안경 is ㄴ, which is not a stop."},pronunciation:"학교 is [학꾜], not [학교]. The ㄲ is the same tense sound as in 꼬리/꽃 — tighten the throat, no puff of air.",pitfall:{wrong:"hak-gyo (a soft, voiced 'g' after the k)",right:"hak-kkyo (a sharp, tense ㄲ)",explanation:"English speakers often voice the consonant after a stop, turning ㄱ into a soft 'g'. Korean does the opposite: the consonant tenses to ㄲ. So 학교 is [학꾜], with a tight, unaspirated ㄲ, never a relaxed 'g'."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I learn Korean at school." (학교에서 시작 · Start with 학교에서.)',tokens:["학교에서","한국어를","배워요."],correct:"학교에서 한국어를 배워요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "There is a book on the desk." (책상 시작 · Start with 책상.)',tokens:["책상","위에","책이","있어요."],correct:"책상 위에 책이 있어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"hak-gyo (a soft, voiced 'g' after the k)",ok:!1},{text:"hak-kkyo (a sharp, tense ㄲ)",ok:!0}],explanation:"English speakers often voice the consonant after a stop, turning ㄱ into a soft 'g'. Korean does the opposite: the consonant tenses to ㄲ. So 학교 is [학꾜], with a tight, unaspirated ㄲ, never a relaxed 'g'."}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b4",chapterId:"chapter-44",index:3},{kind:"pattern",title:"문법 Grammar · 비음화 (Nasalization): A Stop Becomes Nasal Before ㄴ/ㅁ",cards:[{kind:"teach",name:"비음화 (Nasalization): A Stop Becomes Nasal Before ㄴ/ㅁ",sub:"",rows:[{when:"[ㄱ] 받침 + ㄴ/ㅁ",add:"ㄱ → ㅇ [ŋ]",ex:"한국말 → [한궁말], 작년 → [장년]"},{when:"[ㄷ] 받침 + ㄴ/ㅁ",add:"ㄷ → ㄴ",ex:"듣는 → [든는], 끝나다 → [끈나다]"},{when:"[ㅂ] 받침 + ㄴ/ㅁ",add:"ㅂ → ㅁ",ex:"입니다 → [임니다], 감사합니다 → [감사함니다]"},{when:"a stop + a non-nasal consonant",add:"no nasalization (a different rule applies)",ex:"학교 → [학꾜] (tensing, not nasal)"}],examples:[{ko:"한국말 발음이 자연스러워요.",en:"Your Korean pronunciation is natural.",romanization:"han-gung-mal ba-reu-mi ja-yeon-seu-reo-wo-yo",note:"한국말 → [한궁말]: the [ㄱ] of 국 becomes ㅇ before ㅁ."},{ko:"감사합니다.",en:"Thank you.",romanization:"gam-sa-ham-ni-da",note:"합니다 → [함니다]: the [ㅂ] of 합 becomes ㅁ before ㄴ — the single most common nasalization learners hear."}],more:{func:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is followed by the nasal consonant ㄴ or ㅁ, the stop changes into the matching nasal: ㄱ→ㅇ[ŋ], ㄷ→ㄴ, ㅂ→ㅁ. The mouth assimilates to the nasal that follows. This is why 한국말 is said [한궁말].",funcLead:"When a 받침 pronounced as a stop [ㄱ/ㄷ/ㅂ] is followed by the nasal consonant ㄴ or ㅁ, the stop changes into the matching nasal: ㄱ→ㅇ[ŋ], ㄷ→ㄴ, ㅂ→ㅁ.",keyPoint:{label:"-입니다 / -습니다",body:"The polite formal endings -ㅂ니다 / -습니다 are ALWAYS nasalized in speech: 입니다 [임니다], 습니다 [슴니다]. Saying [입니다] with a real ㅂ sounds unnatural — the ㅂ always becomes ㅁ before the ㄴ."},pronunciation:"한국말 is [한궁말]: the ㄱ disappears into a nasal ㅇ. Hum it — the air should go through your nose on the 궁.",pitfall:{wrong:"hap-ni-da (a hard 'p' before the n)",right:"ham-ni-da (the ㅂ turns into ㅁ)",explanation:"English keeps the stop and nasal separate ('hap-nip'). Korean blends them: a stop before ㄴ/ㅁ assimilates into the matching nasal. So 합니다 is [함니다] and 한국말 is [한궁말], never with the original stop intact."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Your Korean pronunciation is natural."',tokens:["한국말","발음이","자연스러워요."],correct:"한국말 발음이 자연스러워요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"ham-ni-da (the ㅂ turns into ㅁ)",ok:!0},{text:"hap-ni-da (a hard 'p' before the n)",ok:!1}],explanation:"English keeps the stop and nasal separate ('hap-nip'). Korean blends them: a stop before ㄴ/ㅁ assimilates into the matching nasal. So 합니다 is [함니다] and 한국말 is [한궁말], never with the original stop intact."}],canDo:"Recognize nasalization and aspiration in speech (국민 → [궁민]; 좋다 → [조타])",id:"chapter-44-b5",chapterId:"chapter-44",index:4},{kind:"pattern",title:"문법 Grammar · 격음화 (Aspiration): ㅎ Merges with a Plain Stop into an Aspirate",cards:[{kind:"teach",name:"격음화 (Aspiration): ㅎ Merges with a Plain Stop into an Aspirate",sub:"",rows:[{when:"ㅎ 받침 + ㄱ/ㄷ/ㅈ",add:"merge into ㅋ/ㅌ/ㅊ",ex:"좋다 → [조타], 좋고 → [조코], 좋지 → [조치]"},{when:"[ㄱ] 받침 + ㅎ",add:"ㄱ + ㅎ → ㅋ",ex:"축하 → [추카], 백화점 → [배콰점]"},{when:"[ㄷ] 받침 + ㅎ",add:"ㄷ + ㅎ → ㅌ",ex:"맏형 → [마텽]"},{when:"[ㅂ] 받침 + ㅎ",add:"ㅂ + ㅎ → ㅍ",ex:"입학 → [이팍], 잡화 → [자퐈]"}],examples:[{ko:"발음이 좋다고 들었어요.",en:"I heard your pronunciation is good.",romanization:"ba-reu-mi jo-ta-go deu-reo-sseo-yo",note:"좋다 → [조타]: ㅎ 받침 + ㄷ merge into the aspirate ㅌ."},{ko:"입학을 축하해요!",en:"Congratulations on starting school!",romanization:"i-pa-geul chu-ka-hae-yo",note:"입학 → [이팍]: [ㅂ] + ㅎ → ㅍ; 축하 → [추카]: [ㄱ] + ㅎ → ㅋ. Two aspirations in one sentence."}],more:{func:"When ㅎ meets a plain consonant ㄱ, ㄷ, ㅂ, or ㅈ (in either order — ㅎ before the consonant, or a [ㄱ/ㄷ/ㅂ] 받침 before ㅎ), the two merge into a single aspirated consonant: ㄱ→ㅋ, ㄷ→ㅌ, ㅂ→ㅍ, ㅈ→ㅊ. This is why 좋다 is said [조타].",funcLead:"When ㅎ meets a plain consonant ㄱ, ㄷ, ㅂ, or ㅈ (in either order — ㅎ before the consonant, or a [ㄱ/ㄷ/ㅂ] 받침 before ㅎ), the two merge into a single aspirated conson…",keyPoint:{label:"Aspiration vs. tensing",body:"Both reshape a plain stop, but the trigger differs. ㅎ + ㄱ/ㄷ/ㅂ/ㅈ gives an ASPIRATED consonant (ㅋ/ㅌ/ㅍ/ㅊ, with a puff of air): 좋다 [조타]. A stop + plain consonant gives a TENSE consonant (ㄲ/ㄸ/ㅃ, no air): 학교 [학꾜]. Hold your hand to your mouth — aspiration puffs, tensing doesn't."},pronunciation:"좋다 is [조타], not [졷다] or [조따]. The ㅌ is aspirated like the ㅌ in 타요 — release a clear puff of air, not a tense ㄸ.",pitfall:{wrong:"jot-da (keeping the ㅎ and ㄷ as two separate hard sounds)",right:"jo-ta (the ㅎ and ㄷ merge into one aspirated ㅌ)",explanation:"English speakers try to pronounce both the ㅎ and the following stop, or drop the ㅎ entirely as a tense [조따]. In Korean the two fuse into a single aspirated consonant with a puff of air, so 좋다 is [조타] and 축하 is [추카]."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I heard your pronunciation is good."',tokens:["발음이","좋다고","들었어요."],correct:"발음이 좋다고 들었어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"jo-ta (the ㅎ and ㄷ merge into one aspirated ㅌ)",ok:!0},{text:"jot-da (keeping the ㅎ and ㄷ as two separate hard sounds)",ok:!1}],explanation:"English speakers try to pronounce both the ㅎ and the following stop, or drop the ㅎ entirely as a tense [조따]. In Korean the two fuse into a single aspirated consonant with a puff of air, so 좋다 is [조타] and 축하 is [추카]."}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b6",chapterId:"chapter-44",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner compares written Hangul with actual pronunciation.",lines:[{speaker:"민서",ko:"먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어져요.",en:"먹어요 is not [meok-eo-yo]; it links and sounds like [머거요].",romanization:"meogeoyoneun [meok-eo-yo]ga anira [meogeoyo]cheoreom ieojyeoyo."},{speaker:"지훈",ko:"학교랑 국밥은 왜 [학꾜], [국빱]처럼 들려요?",en:"Why do 학교 and 국밥 sound like [학꾜] and [국빱]?",romanization:"hakgyorang gukbabeun wae [hakkkyo], [gukppap]cheoreom deullyeoyo?"},{speaker:"민서",ko:"받침 뒤에서 된소리가 나서 그래요.",en:"It is because a tense sound appears after the final consonant.",romanization:"batchim dwieseo doensoriga naseo geuraeyo."},{speaker:"지훈",ko:"그럼 국민은 [궁민], 먹는은 [멍는]처럼 들리죠?",en:"Then 국민 sounds like [궁민], and 먹는 sounds like [멍는], right?",romanization:"geureom gungmineun [gungmin], meongneuneun [meongneun]cheoreom deullijyo?"},{speaker:"민서",ko:"맞아요. 좋다와 입학은 [조타], [이팍]처럼 ㅎ 때문에 세게 나요.",en:"Right. 좋다 and 입학 become stronger sounds like [조타] and [이팍] because of ㅎ.",romanization:"majayo. jotdawa iphak-eun [jota], [ipak]cheoreom hieut ttaemune sege nayo."}]},{kind:"order",prompt:"Build: 'Read Korean slowly.'",tokens:["한국어를","천천히 읽어요"],correct:"한국어를 천천히 읽어요",explanation:"This sentence keeps pronunciation practice inside a real action phrase. 한국어를 is the object and 천천히 tells how to read."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"맞아요. 좋다와 입학은 [조타], [이팍]처럼 ㅎ 때문에 세게 나요.",options:[{text:"민서",ok:!0},{text:"지훈",ok:!1}],explanation:"Right. 좋다 and 입학 become stronger sounds like [조타] and [이팍] because of ㅎ."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Why do 학교 and 국밥 sound like [학꾜] and [국빱]?"',sentence:"___랑 국밥은 왜 [학꾜], [국빱]처럼 들려요?",options:[{text:"한국어",ok:!1},{text:"국민",ok:!1},{text:"학교",ok:!0}],explanation:""}],canDo:"Read a 받침 linking onto the next vowel (한국어 → [한구거], 연음)",id:"chapter-44-b7",chapterId:"chapter-44",index:6},{kind:"reading",title:"읽기 Reading · 글자대로 읽는 것과 실제로 들리는 소리",cards:[{kind:"read",title:"글자대로 읽는 것과 실제로 들리는 소리",chunks:["한글은 규칙적인 문자지만, 실제 말소리는 글자 블록을 하나씩 끊어 읽지 않아요. 먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어지고, 한국어도 [한구거]처럼 들려요. 반대로 학교와 국밥은 뒤 음절이 세져서 [학꾜], [국빱]처럼 들려요.","또 국민과 먹는처럼 ㄴ이나 ㅁ 앞에서는 받침 소리가 코소리로 바뀌고, 좋다와 입학처럼 ㅎ을 만나면 [조타], [이팍]처럼 거센소리가 나요. 철자는 그대로 외우되, 말할 때는 실제 소리 지도를 함께 익혀야 자연스럽게 들립니다."],translation:"Hangul spelling is regular, but speech does not read each block separately. 먹어요 links to [머거요], 한국어 sounds like [한구거], 학교 and 국밥 gain tense sounds, 국민 and 먹는 nasalize before ㄴ or ㅁ, and 좋다 and 입학 aspirate because of ㅎ. Keep the spelling, but learn the spoken map too.",qas:[{q:"먹어요는 실제로 어떻게 이어져 들려요?",a:"[머거요]처럼 들려요."},{q:"학교와 국밥에서 어떤 변화가 일어나요?",a:"뒤 음절이 된소리로 세져서 [학꾜], [국빱]처럼 들려요."},{q:"좋다와 입학은 왜 [조타], [이팍]처럼 들려요?",a:"ㅎ을 만나서 거센소리가 나기 때문이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"먹어요는 [먹-어-요]가 아니라 [머거요]처럼 이어지고, ___도 [한구거]처럼 들려요.",options:[{text:"한국어",ok:!0},{text:"먹다",ok:!1},{text:"앉다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"반대로 ___와 국밥은 뒤 음절이 세져서 [학꾜], [국빱]처럼 들려요.",options:[{text:"먹다",ok:!1},{text:"학교",ok:!0},{text:"앉다",ok:!1}],explanation:""}],canDo:"Hear a plain consonant tense after a stop (학교 → [학꾜], 경음화)",id:"chapter-44-b8",chapterId:"chapter-44",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"먹어요 is naturally pronounced closer to:",sentence:null,options:[{text:"[머거요]",ok:!0},{text:"[먹어 요]",ok:!1},{text:"[먹꼬요]",ok:!1}],explanation:"연음 links ㄱ into the following vowel."},{kind:"drill",prompt:"학교 often sounds like [학꾜] because of:",sentence:null,options:[{text:"경음화",ok:!0},{text:"비음화",ok:!1},{text:"격음화",ok:!1}],explanation:"The following ㄱ becomes tense after the final consonant."},{kind:"drill",prompt:"Which word shows nasalization?",sentence:null,options:[{text:"국민 → [궁민]",ok:!0},{text:"국밥 → [국빱]",ok:!1},{text:"좋다 → [조타]",ok:!1}],explanation:"ㄱ becomes ㅇ before ㅁ."},{kind:"drill",prompt:"Which pair shows aspiration caused by ㅎ?",sentence:null,options:[{text:"입학 → [이팍]",ok:!0},{text:"한국어 → [한구거]",ok:!1},{text:"먹는 → [멍는]",ok:!1}],explanation:"ㅂ and ㅎ combine into ㅍ in speech."},{kind:"drill",prompt:"국민 is naturally heard closer to:",sentence:null,options:[{text:"궁민",ok:!0},{text:"국민 그대로",ok:!1},{text:"군민",ok:!1}],explanation:"Before ㄴ or ㅁ, a stop sound can nasalize. ㄱ before ㅁ is heard closer to ㅇ, giving 궁민."},{kind:"drill",prompt:"학교___ 가요. (I go to school.)",sentence:null,options:[{text:"에",ok:!0},{text:"에서",ok:!1},{text:"가",ok:!1}],explanation:"가요 takes 에 for the destination. 에서 marks an action place, and 가 would make 학교 the subject of going. The pronunciation of 학교 may tense in speech, but the written particle is still 에."}],canDo:"Recognize nasalization and aspiration in speech (국민 → [궁민]; 좋다 → [조타])",id:"chapter-44-b9",chapterId:"chapter-44",index:8}]},{id:"chapter-45",number:45,title:"안 + verb/adjective · 못 + verb",goal:"Choose 안 for simple choice or ordinary negation.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 가다~",cards:[{kind:"guess",word:{ko:"가다",romanization:"gada",en:"to go",pos:"verb",nuance:"Use 에 for destination: 학교에 가요, 집에 가요. Do not use 에서 for destination."},sentence:{ko:"안 가는 거예요, 아니면 못 가는 거예요?",en:"Are you choosing not to go, or are you unable to go?"},target:"가는",options:["to eat","to go","to do"],note:"Linked to dictionary card word-verb-003."},{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"알레르기가 있어서 고기를 못 먹어요.",en:"I cannot eat meat because I have an allergy."},target:"먹어",options:["to go","to do","to eat"],note:"Linked to dictionary card word-verb-001."},{kind:"guess",word:{ko:"하다",romanization:"hada",en:"to do",pos:"verb",nuance:"하다 combines with many nouns: 공부하다, 일하다, 운동하다. It is one of the most important Korean verbs."},sentence:{ko:"요즘 운동 안 해요.",en:"I do not exercise these days."},target:"해",options:["to go","to do","to eat"],note:"Linked to dictionary card word-verb-007."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 없어서 못 가요.",en:"I cannot go because I do not have time."},target:"시간",options:["time","working overtime","meat"],note:"Linked to dictionary card word-noun-009."},{kind:"guess",word:{ko:"야근",romanization:"yageun",en:"working overtime",pos:"noun",nuance:"야근 specifically means staying at the office working late into the night — the iconic symbol of old-school Korean work culture. It is Sino-Korean 夜勤, literally 'night-duty', sharing the 勤 ('duty/labor') of 외근 and 출근. The contrast to nail: 야근 is overtime that runs LATE/at night, whereas 특근 (特勤, 'special duty') and 추가 근무 cover extra work generally, including daytime, weekends, or holidays — so weekend morning work is 특근, not 야근. Its cultural foil is the slang 칼퇴 ('knife-exit' = leaving on the dot at quitting time), the thing everyone dreams of instead. And the carrot is 야근 수당 (overtime pay), which is 나오다 (paid out), not 받다-only. The English-speaker pitfall is using 야근 as a blanket word for all 'overtime' — keep the time-of-day nuance — and saying 야근을 가다 ('go to overtime'); you don't go to it, you 야근을 하다."},sentence:{ko:"야근 때문에 못 가요.",en:"I cannot go because of overtime."},target:"야근",options:["working overtime","time","meat"],note:"Linked to dictionary card word-ext-548."},{kind:"guess",word:{ko:"고기",romanization:"gogi",en:"meat",pos:"noun",nuance:"In everyday speech 고기 by default means red land meat — usually 돼지고기(pork) or 소고기(beef) — so 고기 먹으러 가자 implies a BBQ, not seafood. To be specific you compound the animal onto 고기: 닭고기(chicken), 소고기(beef), 돼지고기(pork). The words to contrast are 생선(fish as food) and 해산물(seafood), which Koreans do NOT file under 고기; chicken sits on the edge, so people usually say 닭고기 rather than bare 고기 for it. The set cooking verb is 굽다, a ㅂ-irregular that becomes 구워요/구웠어요 (not 'gubeoyo'). The English-speaker pitfall is the English umbrella sense of 'meat' that includes fish and poultry — in Korean, unmarked 고기 leans strongly toward pork/beef, and you should name the animal when you mean otherwise."},sentence:{ko:"고기는 안 먹어요?",en:"Do you not eat meat?"},target:"고기",options:["meat","time","working overtime"],note:"Linked to dictionary card word-ext-040."},{kind:"payoff",line:{speaker:"민서",ko:"오늘 모임에는 못 가요. 시간이 없어요.",en:"I cannot go to the gathering today. I do not have time."},hl:"가요"}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b1",chapterId:"chapter-45",index:0},{kind:"pattern",title:"문법 Grammar · 안 + verb/adjective",cards:[{kind:"hunt",name:"안 + verb/adjective",sub:"simple negation",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"술을",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"마셔요.",mid:"",post:"",hit:!1}],ko:"저는 술을 안 마셔요.",en:"I don't drink alcohol.",romanization:"jeoneun sureul an masyeoyo."},{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"학교에",mid:"",post:"",hit:!1},{pre:"",mid:"안",post:"",hit:!0},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘은 학교에 안 가요.",en:"I'm not going to school today.",romanization:"oneureun hakgyoe an gayo."}],rule:{name:"안 + verb/adjective",rows:[{when:"Most verbs and adjectives",add:"안 in front of the word",ex:"가요 → 안 가요 (don't go)"},{when:"Adjective",add:"안 in front",ex:"바빠요 → 안 바빠요 (not busy)"},{when:"하다 action verbs (공부하다 등)",add:"안 splits IN: noun + 안 + 해요",ex:"공부해요 → 공부 안 해요 (don't study)"}]},more:{func:`Put 안 directly in front of a verb or adjective to make it negative. This is the everyday spoken negation: "I don't / it isn't." It states a choice or a plain fact, with no sense of being blocked or unable.`,funcLead:"Put 안 directly in front of a verb or adjective to make it negative.",keyPoint:{label:"안 vs 못",body:"안 = don't or won't, by choice or as a plain fact (안 가요, I'm not going). 못 = can't, blocked by an outside obstacle (못 가요, I can't go). If you simply chose not to, use 안; if something stops you, use 못."},pronunciation:"안 is pronounced [an] and, unlike 못, it does NOT tense the next sound. 안 가요 stays [an ga.yo], 안 봐요 stays [an bwa.yo]. Before a verb starting with ㅁ/ㄴ the nasal flows smoothly: 안 마셔요 → [an ma.syeo.yo]. No double-consonant tensing anywhere.",pitfall:{wrong:"안 공부해요",right:"공부 안 해요",explanation:"English speakers treat 공부하다 as one block and put 안 in front of the whole thing. But noun + 하다 verbs split: the noun stays, then 안, then 해요. So it's 공부 안 해요, 운동 안 해요, 요리 안 해요."}}},{kind:"drill",prompt:"This movie isn't scary.",sentence:"이 영화는 ___ 무서워요.",options:[{text:"안",ok:!0},{text:"못",ok:!1},{text:"없어요",ok:!1}],explanation:"안 also negates adjectives (무섭다 = scary), describing a plain quality."},{kind:"drill",prompt:"I don't exercise.",sentence:"저는 운동 ___ 해요.",options:[{text:"못",ok:!1},{text:"안",ok:!0},{text:"없어요",ok:!1}],explanation:"With 운동하다, 안 goes BETWEEN the noun and 해요: 운동 안 해요, not 안 운동해요."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't drink alcohol."`,tokens:["저는","술을","안","마셔요."],correct:"저는 술을 안 마셔요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm not going to school today." (오늘은 시작 · Start with 오늘은.)`,tokens:["오늘은","학교에","안","가요."],correct:"오늘은 학교에 안 가요.",explanation:""}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b2",chapterId:"chapter-45",index:1},{kind:"words",title:"단어 Words 2 · 알레르기~",cards:[{kind:"guess",word:{ko:"알레르기",romanization:"allereugi",en:"allergy",pos:"noun",nuance:"알레르기 gives a concrete outside reason. In Korean this often makes 못 sound appropriate because the limit is physical or medical, not a preference."},sentence:{ko:"알레르기가 있어서 못 먹어요.",en:"I cannot eat it because I have an allergy."},target:"알레르기",options:["time","working overtime","allergy"],note:"Linked to dictionary card word-ext-ch45-allergy."},{kind:"guess",word:{ko:"싫다",romanization:"silta",en:"to dislike; to be undesirable",pos:"adjective",nuance:"싫어요 can sound strong. For polite refusal, 고 싶지 않아요 can be softer."},sentence:{ko:"가기 싫은 건 아니에요.",en:"It is not that I do not want to go."},target:"싫은",options:["to be difficult","to dislike; to be undesirable","to go"],note:"Linked to dictionary card word-adjective-028."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"어렵지 않게 다른 메뉴로 예약할게요.",en:"I will reserve a different menu so it is not difficult."},target:"어렵",options:["to be difficult","to dislike; to be undesirable","to go"],note:"Linked to dictionary card word-adjective-037."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study; studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"오늘은 공부 못 해요.",en:"I cannot study today."},target:"공부",options:["time","working overtime","study; studying"],note:"Linked to dictionary card word-ext-1560."},{kind:"guess",word:{ko:"운동",romanization:"undong",en:"exercise",pos:"noun",nuance:"운동 is Sino-Korean, 運動 ('move-motion'), and is the umbrella word for physical exercise; it normally appears as 운동하다 (운동을 해요). Crucially it is NOT counted or pluralized like English 'a workout' — you don't say 운동들 for several sessions; you say 운동을 자주 해요. The nearest relative is 스포츠 (a borrowed word for organized sports as a category, e.g. watching 스포츠 on TV), whereas 운동 is the act of exercising your own body, so '운동선수' = athlete but '스포츠 경기' = a sports match. The very same 運動 also means a social 'movement/campaign' (민주화 운동 the democracy movement), so context decides. The English-speaker pitfall is reaching for 만들다 ('make') by analogy with 'make exercise' — Korean uses the light verb 하다; and remember the desire ending goes on the verb (운동하고 싶어요), never on the bare noun."},sentence:{ko:"요즘 운동 안 해요.",en:"I do not exercise these days."},target:"운동",options:["time","exercise","working overtime"],note:"Linked to dictionary card word-ext-301."},{kind:"guess",word:{ko:"전화",romanization:"jeonhwa",en:"phone call",pos:"noun",nuance:"전화 is a noun, but 전화하다 is the verb “to call.”"},sentence:{ko:"지금은 전화 못 해요.",en:"I cannot call right now."},target:"전화",options:["phone call","time","working overtime"],note:"Linked to dictionary card word-noun-024."},{kind:"payoff",line:{speaker:"민서",ko:"싫어서 안 먹는 게 아니라 알레르기가 있어서 못 먹어요.",en:"It is not that I avoid it because I dislike it; I cannot eat it because I have an allergy."},hl:"알레르기"}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b3",chapterId:"chapter-45",index:2},{kind:"pattern",title:"문법 Grammar · 못 + verb",cards:[{kind:"hunt",name:"못 + verb",sub:"cannot, because something blocks you",lines:[{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"바빠서",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"가요.",mid:"",post:"",hit:!1}],ko:"오늘 너무 바빠서 못 가요.",en:"I can't go today because I'm too busy.",romanization:"oneul neomu bappaseo mot gayo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"매운",mid:"",post:"",hit:!1},{pre:"음식을",mid:"",post:"",hit:!1},{pre:"",mid:"못",post:"",hit:!0},{pre:"먹어요.",mid:"",post:"",hit:!1}],ko:"저는 매운 음식을 못 먹어요.",en:"I can't eat spicy food.",romanization:"jeoneun maeun eumsigeul mot meogeoyo."}],rule:{name:"못 + verb",rows:[{when:"Most action verbs",add:"못 in front of the verb",ex:"가요 → 못 가요 (can't go)"},{when:"하다 action verbs",add:"못 splits IN: noun + 못 + 해요",ex:"수영해요 → 수영 못 해요 (can't swim)"},{when:"NOT with plain adjectives",add:"use 안 instead",ex:"안 바빠요 (○) / 못 바빠요 (✗)"}]},more:{func:"Put 못 in front of a verb to say you CANNOT do it — not because you don't want to, but because something blocks or prevents you (no time, no skill, no permission, an obstacle). 못 is used with action verbs, not with descriptive adjectives.",funcLead:"Put 못 in front of a verb to say you CANNOT do it — not because you don't want to, but because something blocks or prevents you (no time, no skill, no permissio…",keyPoint:{label:"못 + verb only (never adjectives)",body:"못 means 'unable to DO an action,' so it attaches to action verbs (못 가요, 못 먹어요). You can't be 'unable to be tall' or 'unable to be busy' — for adjectives use 안 (안 커요, 안 바빠요). 못 바빠요 is wrong."},pronunciation:"못 is written with final ㅅ but pronounced [몯]. Before a vowel it links: 못 와요 → [모 돠요]. Before ㄱ/ㄷ/ㅂ/ㅈ it TENSES the next sound: 못 가요 → [몯 까요], 못 봐요 → [몯 빠요]. That tensing is the audible signal of 못 — and the clearest way to tell it apart from 안.",pitfall:{wrong:"저는 안 수영해요 (when you mean you literally can't swim)",right:"저는 수영 못 해요",explanation:"English 'I don't swim' and 'I can't swim' look similar, so learners default to 안. But when an ability or obstacle is involved, Korean wants 못. 안 수영해요 means you choose not to; 수영 못 해요 means you're unable."}}},{kind:"drill",prompt:"I can't swim.",sentence:"저는 수영 ___ 해요.",options:[{text:"못",ok:!0},{text:"안",ok:!1},{text:"없어요",ok:!1}],explanation:"하다 verb: 못 goes between 수영 and 해요. It's a lack of skill, hence 못."},{kind:"drill",prompt:"I couldn't sleep because it was noisy.",sentence:"시끄러워서 잠을 ___ 잤어요.",options:[{text:"못",ok:!0},{text:"안",ok:!1},{text:"없어요",ok:!1}],explanation:"An external obstacle (noise) prevented the action — a classic 못 situation, here in the past."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I can't go today because I'm too busy."`,tokens:["오늘","너무","바빠서","못","가요."],correct:"오늘 너무 바빠서 못 가요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I can't eat spicy food."`,tokens:["저는","매운","음식을","못","먹어요."],correct:"저는 매운 음식을 못 먹어요.",explanation:""}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b4",chapterId:"chapter-45",index:3},{kind:"pattern",title:"문법 Grammar · -지 않아요",cards:[{kind:"hunt",name:"-지 않아요",sub:"the longer / written negation",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"고기를",mid:"",post:"",hit:!1},{pre:"먹",mid:"지",post:"",hit:!0},{pre:"",mid:"않아요",post:".",hit:!0}],ko:"저는 고기를 먹지 않아요.",en:"I don't eat meat.",romanization:"jeoneun gogireul meokji anayo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"가게는",mid:"",post:"",hit:!1},{pre:"비싸",mid:"지",post:"",hit:!0},{pre:"",mid:"않아요",post:".",hit:!0}],ko:"그 가게는 비싸지 않아요.",en:"That shop isn't expensive.",romanization:"geu gageneun bissaji anayo."}],rule:{name:"-지 않아요",rows:[{when:"Verb or adjective stem",add:"stem + -지 않아요",ex:"가다 → 가지 않아요 (don't go)"},{when:"Adjective",add:"stem + -지 않아요",ex:"바쁘다 → 바쁘지 않아요 (not busy)"},{when:"하다 verbs (no splitting!)",add:"공부하 + -지 않아요",ex:"공부하다 → 공부하지 않아요 (don't study)"}]},more:{func:"Attach -지 않아요 to a verb or adjective stem for the 'long form' of negation. It means the same as 안, but is a little more formal and is common in writing, careful speech, and longer sentences. It works smoothly with every verb and adjective, including 하다 verbs (no splitting).",funcLead:"Attach -지 않아요 to a verb or adjective stem for the 'long form' of negation.",keyPoint:{label:"안 vs -지 않아요",body:"They mean the same thing. 안 먹어요 = 먹지 않아요 (I don't eat). 안 is short and spoken; -지 않아요 is longer and slightly more formal or written. Bonus: 하다 verbs DON'T split with -지 않아요 (운동하지 않아요), unlike 운동 안 해요."},pronunciation:"않아요 is pronounced [아나요] — the ㅎ in 않 is silent and the ㄴ links into the following vowel: 가지 않아요 → [가지 아나요]. The ㅎ never makes its own sound here.",pitfall:{wrong:"먹지 안 아요 / 먹지 않어요",right:"먹지 않아요",explanation:"Two errors are common: splitting 안 out as a separate word, and misspelling the ending. The fixed ending is one unit, -지 않아요 [지 아나요]. Don't insert 안 separately, and don't write 않어요."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't eat meat."`,tokens:["저는","고기를","먹지","않아요."],correct:"저는 고기를 먹지 않아요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "That shop isn't expensive."`,tokens:["그","가게는","비싸지","않아요."],correct:"그 가게는 비싸지 않아요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"먹지 안 아요 / 먹지 않어요",ok:!1},{text:"먹지 않아요",ok:!0}],explanation:"Two errors are common: splitting 안 out as a separate word, and misspelling the ending. The fixed ending is one unit, -지 않아요 [지 아나요]. Don't insert 안 separately, and don't write 않어요."}],canDo:"Use the longer written negation -지 않아요 (좋아하지 않아요)",id:"chapter-45-b5",chapterId:"chapter-45",index:4},{kind:"pattern",title:"문법 Grammar · N이/가 없어요",cards:[{kind:"hunt",name:"N이/가 없어요",sub:`absence / "don't have"`,lines:[{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"시간",mid:"이",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"지금 시간이 없어요.",en:"I don't have time right now.",romanization:"jigeum sigani eopseoyo."},{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"차",mid:"가",post:"",hit:!0},{pre:"",mid:"없어요",post:".",hit:!0}],ko:"저는 차가 없어요.",en:"I don't have a car.",romanization:"jeoneun chaga eopseoyo."}],rule:{name:"N이/가 없어요",rows:[{when:"Noun ends in a consonant",add:"noun + 이 없어요",ex:"시간 → 시간이 없어요 (no time)"},{when:"Noun ends in a vowel",add:"noun + 가 없어요",ex:"차 → 차가 없어요 (no car)"},{when:"Opposite (positive)",add:"있어요",ex:"시간이 있어요 (have time)"}]},more:{func:"없어요 is the verb for 'there isn't / I don't have.' It is the opposite of 있어요 (there is / have). The noun takes the subject marker 이/가, and 없어요 covers both 'don't possess' and 'isn't present / doesn't exist.'",funcLead:"없어요 is the verb for 'there isn't / I don't have.' It is the opposite of 있어요 (there is / have).",keyPoint:{label:"없어요 vs 안 + verb",body:"For NOT HAVING or NOT EXISTING, use 없어요, never 안 있어요. 안 있어요 is wrong. So 'no time' = 시간이 없어요 (○), not 시간이 안 있어요 (✗). 안 negates actions and qualities; 없어요 negates existence and possession."},pronunciation:"없어요 is pronounced [업써요]: the ㅂㅅ cluster keeps the ㅂ [p] sound, and the ㅅ links to the next vowel as a tense [ss]. So 시간이 없어요 → [시가니 업써요].",pitfall:{wrong:"시간이 안 있어요",right:"시간이 없어요",explanation:"English 'I don't have time' tempts learners to negate 있어요 with 안. Korean has a dedicated negative verb 없어요 for this; 안 있어요 sounds wrong to native ears. Memorize 있어요 ↔ 없어요 as a pair."}}},{kind:"drill",prompt:"There's no milk in the fridge.",sentence:"냉장고에 우유___.",options:[{text:"이 없어요",ok:!1},{text:"가 없어요",ok:!0}],explanation:"Same 없어요 also means 'isn't there / doesn't exist' — the absence of a thing in a place. 우유 ends in a vowel → 우유가."},{kind:"drill",prompt:"I don't have any plans today.",sentence:"오늘은 약속___.",options:[{text:"이 없어요",ok:!0},{text:"가 없어요",ok:!1}],explanation:"없어요 negates having something (약속 = plans/an appointment); 약속 ends in a consonant → 약속이."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't have time right now."`,tokens:["지금","시간이","없어요."],correct:"지금 시간이 없어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't have a car."`,tokens:["저는","차가","없어요."],correct:"저는 차가 없어요.",explanation:""}],canDo:"Express absence or 'don't have' with N이/가 없어요 (시간이 없어요)",id:"chapter-45-b6",chapterId:"chapter-45",index:5},{kind:"pattern",title:"문법 Grammar · Boundary check",cards:[{kind:"teach",name:"Boundary check",sub:"안 vs 못 vs 아니에요 vs 싫어요",rows:[{when:"Choice / plain fact about an action or quality",add:"안 + verb/adjective",ex:"안 가요 (I'm not going)"},{when:"Inability / outside obstacle",add:"못 + verb",ex:"못 가요 (I can't go)"},{when:"'It is NOT [a noun]' (identity)",add:"noun + 이/가 아니에요",ex:"학생이 아니에요 (not a student)"},{when:"Dislike / 'I don't want to'",add:"싫어요 (or 안 좋아요)",ex:"숙제가 싫어요 (I hate homework)"}],examples:[{ko:"오늘은 안 가요.",en:"I'm not going today.",romanization:"oneureun an gayo.",note:"A choice or plan — plain negation of the action, so 안."},{ko:"바빠서 오늘은 못 가요.",en:"I can't go today because I'm busy.",romanization:"bappaseo oneureun mot gayo.",note:"Something blocks the action (being busy), so 못, not 안."}],more:{func:"Korean splits the English word 'not' across several forms, and choosing the wrong one sounds off. This note sorts them: 안 = don't/won't (choice or fact), 못 = can't (blocked), 아니에요 = 'it's not [a noun]' (identity), 싫어요 = 'I don't like it / I don't want to' (dislike or refusal). Match the form to the meaning, not to the English word.",funcLead:"Korean splits the English word 'not' across several forms, and choosing the wrong one sounds off.",keyPoint:{label:"One English 'not,' four Korean choices",body:"Ask what kind of 'not' it is. Action by choice → 안. Action blocked → 못. 'It's not [a noun]' → 아니에요. 'I don't like / don't want' → 싫어요. Picking by feeling, not by the English word, is the whole skill of this chapter."},pronunciation:"아니에요 → [아니에요], four clear syllables, no linking trick. 싫어요 → [시러요]: the ㅎ in 싫 is silent and the ㄹ links into the vowel, so it sounds like [시러요], not [실허요].",pitfall:{wrong:"이건 제 가방 안 이에요 / 저는 그게 안 좋아요 (meaning 'I hate it')",right:"이건 제 가방이 아니에요 / 저는 그게 싫어요",explanation:"Two traps: (1) you can't negate 이에요/예요 with 안 — to say a noun is NOT something, use 아니에요. (2) For strong dislike or refusal, 싫어요 is the natural word; 안 좋아요 just means 'not good,' which is milder and can sound evasive."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm not going today."`,tokens:["오늘은","안","가요."],correct:"오늘은 안 가요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I can't go today because I'm busy."`,tokens:["바빠서","오늘은","못","가요."],correct:"바빠서 오늘은 못 가요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"이건 제 가방 안 이에요 / 저는 그게 안 좋아요 (meaning 'I hate it')",ok:!1},{text:"이건 제 가방이 아니에요 / 저는 그게 싫어요",ok:!0}],explanation:"Two traps: (1) you can't negate 이에요/예요 with 안 — to say a noun is NOT something, use 아니에요. (2) For strong dislike or refusal, 싫어요 is the natural word; 안 좋아요 just means 'not good,' which is milder and can sound evasive."}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b7",chapterId:"chapter-45",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A friend clarifies whether a refusal is about choice, schedule, or a real restriction.",lines:[{speaker:"민서",ko:"오늘 모임에는 못 가요. 시간이 없어요.",en:"I cannot go to the gathering today. I do not have time.",romanization:"oneul moimeneun mot gayo. sigani eopseoyo."},{speaker:"지훈",ko:"안 가는 거예요, 아니면 정말 못 가는 거예요?",en:"Are you choosing not to go, or are you really unable to go?",romanization:"an ganeun geoyeyo, animyeon jeongmal mot ganeun geoyeyo?"},{speaker:"민서",ko:"가기 싫은 건 아니에요. 야근 때문에 못 가요.",en:"It is not that I do not want to go. I cannot go because of overtime.",romanization:"gagi silheun geon anieyo. yageun ttaemune mot gayo."},{speaker:"지훈",ko:"그럼 회식에서 고기는 안 먹어요?",en:"Then at the company dinner, do you not eat meat?",romanization:"geureom hoesigeseo gogineun an meogeoyo?"},{speaker:"민서",ko:"싫어서 안 먹는 게 아니라 알레르기가 있어서 못 먹어요.",en:"It is not that I avoid it because I dislike it; I cannot eat it because I have an allergy.",romanization:"silheoseo an meongneun ge anira allereugiga isseoseo mot meogeoyo."},{speaker:"지훈",ko:"그럼 어렵지 않게 다른 메뉴로 예약할게요.",en:"Then I will reserve a different menu so it is not difficult.",romanization:"geureom eoryeopji anke dareun menyuro yeyakhalgeyo."}]},{kind:"order",prompt:"Build: 'I cannot eat meat because of an allergy.'",tokens:["알레르기 때문에","고기를 못 먹어요"],correct:"알레르기 때문에 고기를 못 먹어요",explanation:"때문에 gives the medical reason, and 못 marks inability. 고기 is what cannot be eaten, so 고기를 is the object."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"싫어서 안 먹는 게 아니라 알레르기가 있어서 못 먹어요.",options:[{text:"민서",ok:!0},{text:"지훈",ok:!1}],explanation:"It is not that I avoid it because I dislike it; I cannot eat it because I have an allergy."},{kind:"drill",prompt:'무엇이 들어갈까요? · "I cannot go to the gathering today. I do not have time."',sentence:"오늘 모임에는 못 가요. ___이 없어요.",options:[{text:"야근",ok:!1},{text:"시간",ok:!0},{text:"고기",ok:!1}],explanation:""}],canDo:"Negate by choice or fact with 안 (안 먹어요)",id:"chapter-45-b8",chapterId:"chapter-45",index:7},{kind:"reading",title:"읽기 Reading · 안 가요와 못 가요는 같은 말이 아니에요",cards:[{kind:"read",title:"안 가요와 못 가요는 같은 말이 아니에요",chunks:["친구의 초대를 거절할 때 '안 가요'와 '못 가요'는 느낌이 달라요. '안 가요'는 내가 가지 않기로 한 선택처럼 들릴 수 있고, '못 가요'는 시간, 일, 건강 같은 이유 때문에 갈 수 없다는 뜻이에요. 그래서 '시간이 없어서 못 가요'라고 말하면 오해가 줄어요.","음식도 마찬가지예요. '고기는 안 먹어요'는 취향이나 습관처럼 들릴 수 있지만, '알레르기가 있어서 못 먹어요'는 몸의 제한을 설명해요. 더 조심스럽게 말하고 싶을 때는 '싫지 않아요', '어렵지 않아요', '먹지 않아요'처럼 -지 않아요를 쓸 수 있어요."],translation:"When declining an invitation, 안 가요 and 못 가요 do not feel the same. 안 가요 can sound like a choice, while 못 가요 says you cannot go because of time, work, health, or another limit. Food works similarly: 고기는 안 먹어요 may sound like preference or habit, but 알레르기가 있어서 못 먹어요 explains a physical restriction. For careful clarification, use -지 않아요.",qas:[{q:"안 가요는 어떤 느낌으로 들릴 수 있어요?",a:"내가 가지 않기로 한 선택처럼 들릴 수 있어요."},{q:"알레르기가 있을 때 왜 못 먹어요가 자연스러워요?",a:"취향이 아니라 몸의 제한 때문에 먹을 수 없다는 뜻이기 때문이에요."},{q:"조심스럽게 부정하거나 설명할 때 어떤 형태를 쓸 수 있어요?",a:"-지 않아요를 쓸 수 있어요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"'안 가요'는 내가 가지 않기로 한 선택처럼 들릴 수 있고, '못 가요'는 ___, 일, 건강 같은 이유 때문에 갈 수 없다는 뜻이에요.",options:[{text:"시간",ok:!0},{text:"야근",ok:!1},{text:"공부",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"'고기는 안 먹어요'는 취향이나 습관처럼 들릴 수 있지만, '___가 있어서 못 먹어요'는 몸의 제한을 설명해요.",options:[{text:"야근",ok:!1},{text:"알레르기",ok:!0},{text:"공부",ok:!1}],explanation:""}],canDo:"Say you can't because something blocks you with 못 (시간이 없어서 못 가요)",id:"chapter-45-b9",chapterId:"chapter-45",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence says circumstances make it impossible to go?",sentence:null,options:[{text:"오늘은 못 가요.",ok:!0},{text:"오늘은 안 가요.",ok:!1},{text:"오늘은 가기 싫어요.",ok:!1}],explanation:"못 marks inability or a blocked situation."},{kind:"drill",prompt:"Which sentence best explains a medical food restriction?",sentence:null,options:[{text:"알레르기가 있어서 못 먹어요.",ok:!0},{text:"싫어서 안 먹어요.",ok:!1},{text:"먹기 싫지 않아요.",ok:!1}],explanation:"알레르기 is an outside restriction, so 못 먹어요 is natural."},{kind:"drill",prompt:"Which sentence uses absence as the reason?",sentence:null,options:[{text:"시간이 없어서 못 가요.",ok:!0},{text:"시간을 안 가요.",ok:!1},{text:"시간이 못 있어요.",ok:!1}],explanation:"없어요 negates the existence/possession of time."},{kind:"drill",prompt:"Which pair correctly contrasts choice and inability?",sentence:null,options:[{text:"안 가요 / 못 가요",ok:!0},{text:"못 가요 / 시간이 없어요",ok:!1},{text:"없어요 / 아니에요",ok:!1}],explanation:"안 often marks not doing or choosing not to; 못 marks inability or blocked action."},{kind:"drill",prompt:"시간___ 없어요. (I do not have time.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"없어요 uses 이/가 for the thing that is absent. 시간 is not an object of an action here."}],canDo:"Use the longer written negation -지 않아요 (좋아하지 않아요)",id:"chapter-45-b10",chapterId:"chapter-45",index:9}]}],o={generatedFrom:e,chapters:t};export{t as chapters,o as default,e as generatedFrom};
